function setAppViewportVars() {
        const vh = (window.innerHeight || document.documentElement.clientHeight || 1) * 0.01;
        document.documentElement.style.setProperty('--app-vh', `${vh}px`);
      }

      const SHEX_BUILD_VERSION = '20261030-001746-x103-front-20';
      window.SHEX_BUILD_VERSION = SHEX_BUILD_VERSION;

      function reportAppUiDiagnostic(kind, error = null, extra = {}) {
        const safeKind = String(kind || 'unknown_ui_error').slice(0, 80);
        const detail = String(error?.stack || error?.message || error || '').slice(0, 1200);
        const payload = {
          kind: safeKind,
          buildVersion: SHEX_BUILD_VERSION,
          page: String(document.body?.dataset?.xPage || location.hash || '').slice(0, 120),
          userAgent: String(navigator.userAgent || '').slice(0, 500),
          detail,
          ...extra
        };
        console.error('[SHEX_APP_UI_DIAGNOSTIC]', payload);
        return payload;
      }

      async function ensureBuildVersionFresh() {
        if (!/^https?:$/.test(location.protocol)) return;
        try {
          const response = await fetch(`./version.json?t=${Date.now()}`, { cache: 'no-store' });
          if (!response.ok) return;
          const remote = await response.json();
          const remoteVersion = String(remote?.version || '').trim();
          if (!remoteVersion || remoteVersion === SHEX_BUILD_VERSION) return;
          const reloadKey = `shex_build_reload_once:${remoteVersion}`;
          if (sessionStorage.getItem(reloadKey) === '1') return;
          sessionStorage.setItem(reloadKey, '1');
          const nextUrl = new URL(location.href);
          nextUrl.searchParams.set('appv', remoteVersion);
          location.replace(nextUrl.toString());
        } catch (error) {
          console.warn('[SHEX_BUILD_VERSION_CHECK_FAILED]', error?.message || error);
        }
      }

      void ensureBuildVersionFresh();

      const UPDATE_NOTICE_VERSION = '2026-06-17-01';
      const UPDATE_NOTICE_STORAGE_KEY = 'shex_update_notice_seen_version';
      const X_LINK_RESOURCE_LIMIT_MODE = false;
      const X_LINK_RESOURCE_LIMIT_HASHES = new Set(['#transmission', '#x-message-chat', '#x-letter', '#x-reply', '#x-companion', '#x-ta-status', '#x-link-status']);
      const X_LINK_ADMIN_USER_IDS = new Set(['shex_fee7aa44-4790-47fc-a89c-fb6f886a6714']);
      const X_LINK_ADMIN_NAMES = new Set(['创世神414', 'administrator'].map((name) => String(name).trim().normalize('NFKC').toLowerCase()));
      const SHEX_DEBUG_QUERY = new URLSearchParams(window.location.search).get('debug') === '1';
      const XCHAT_CLOUD_REPLY_ROLLOUT = Object.freeze({
        enabled: true,
        adminOnly: true,
        normalUserEnabled: true
      });
      // 字卡拼接对所有字卡会话开放；这只控制“拼接”开关，
      // 不改变 AI / 字卡模式切换、模型选择等管理员权限。
      const CARD_SPLICING_ROLLOUT = Object.freeze({
        enabled: true,
        normalUserEnabled: true
      });
      window.CARD_SPLICING_ROLLOUT = CARD_SPLICING_ROLLOUT;
      // 动态聊天背景灰度。静态图片背景仍对所有用户开放；GIF / MP4 暂时仅管理员可用。
      // 后续开放普通用户时只调整 normalUserEnabled，不需要改设置页或上传流程。
      const CHAT_DYNAMIC_BACKGROUND_ROLLOUT = Object.freeze({
        enabled: true,
        normalUserEnabled: false
      });
      window.CHAT_DYNAMIC_BACKGROUND_ROLLOUT = CHAT_DYNAMIC_BACKGROUND_ROLLOUT;
      // 聊天沉浸式显示灰度：当前仅管理员可用，并同时支持 AI 与字卡回复。
      // 后续开放普通用户时，只调整 normalUserEnabled，不需要改消息生成链路。
      const CHAT_IMMERSIVE_ROLLOUT = Object.freeze({
        enabled: true,
        normalUserEnabled: false
      });
      window.CHAT_IMMERSIVE_ROLLOUT = CHAT_IMMERSIVE_ROLLOUT;
      const USE_CLOUD_XCHAT_REPLY = XCHAT_CLOUD_REPLY_ROLLOUT.enabled;
      const SHEX_DEBUG_MODE = SHEX_DEBUG_QUERY || localStorage.getItem('shex_debug_mode') === '1';
      function shexDebugLog(method, label, payload) {
        if (!SHEX_DEBUG_MODE) return;
        const writer = typeof console?.[method] === 'function' ? console[method] : console.log;
        writer.call(console, label, payload);
      }

      window.X_LINK_RESOURCE_LIMIT_MODE = X_LINK_RESOURCE_LIMIT_MODE;
      window.USE_CLOUD_XCHAT_REPLY = USE_CLOUD_XCHAT_REPLY;
      window.XCHAT_CLOUD_REPLY_ROLLOUT = XCHAT_CLOUD_REPLY_ROLLOUT;
      window.SHEX_DEBUG_MODE = SHEX_DEBUG_MODE;
      window.SHEXDebugLog = shexDebugLog;
      const SHEX_BEAUTIFY_RUNTIME_TRACE_ENABLED = SHEX_DEBUG_MODE || new URLSearchParams(window.location.search).has('beautifyDiag');
      const shexBeautifyRuntimeTraceEvents = [];
      function cloneBeautifyTracePayload(value) {
        try { return JSON.parse(JSON.stringify(value)); }
        catch (_) { return { unserializable:true, text:String(value) }; }
      }
      function recordBeautifyRuntimeTrace(stage, payload = {}) {
        if (!SHEX_BEAUTIFY_RUNTIME_TRACE_ENABLED) return null;
        const entry = { sequence:shexBeautifyRuntimeTraceEvents.length + 1, at:Date.now(), stage:String(stage || 'unknown'), payload:cloneBeautifyTracePayload(payload) };
        shexBeautifyRuntimeTraceEvents.push(entry);
        if (shexBeautifyRuntimeTraceEvents.length > 500) shexBeautifyRuntimeTraceEvents.splice(0, shexBeautifyRuntimeTraceEvents.length - 500);
        console.debug('[SHEX_BEAUTIFY_RUNTIME_TRACE]', entry);
        return entry;
      }
      window.SHEXBeautifyRuntimeTrace = Object.freeze({
        enabled:SHEX_BEAUTIFY_RUNTIME_TRACE_ENABLED,
        record:recordBeautifyRuntimeTrace,
        snapshot:()=>shexBeautifyRuntimeTraceEvents.map(cloneBeautifyTracePayload),
        clear:()=>{shexBeautifyRuntimeTraceEvents.length=0;return true;}
      });
      window.__SHEX_X_CLEAN_ENTRY_OWNS_ROUTING = true;

      function isShexAdminUser(inputUser = null) {
        if (!inputUser && window.SHEXAuth?.isAdmin?.()) return true;
        let current = inputUser;
        if (!current) {
          try {
            current = window.SHEXAuth?.current?.() || JSON.parse(localStorage.getItem('shex_auth_session_v1') || 'null');
          } catch (_) {
            current = null;
          }
        }
        const name = String(current?.username || current?.displayName || '').trim().normalize('NFKC').toLowerCase();
        return Boolean(
          current?.isAdmin
            || current?.role === 'admin'
            || X_LINK_ADMIN_USER_IDS.has(current?.userId)
            || X_LINK_ADMIN_NAMES.has(name)
        );
      }
      window.SHEXIsAdminUser = isShexAdminUser;

      function canUseDynamicChatBackgrounds(inputUser = null) {
        if (!CHAT_DYNAMIC_BACKGROUND_ROLLOUT.enabled) return false;
        return CHAT_DYNAMIC_BACKGROUND_ROLLOUT.normalUserEnabled || isShexAdminUser(inputUser);
      }
      window.SHEXCanUseDynamicChatBackgrounds = canUseDynamicChatBackgrounds;

      const STATIC_CHAT_BACKGROUND_ACCEPT = 'image/png,image/jpeg,image/webp,.png,.jpg,.jpeg,.webp';
      const DYNAMIC_CHAT_BACKGROUND_ACCEPT = 'image/*,video/mp4,.mp4';

      function isDynamicChatBackgroundFile(file = {}) {
        const type = String(file?.type || '').trim().toLowerCase();
        const name = String(file?.name || '').trim().toLowerCase();
        return type === 'image/gif' || type === 'video/mp4' || /\.(gif|mp4)$/.test(name);
      }

      async function chatBackgroundFileAllowed(file = {}) {
        const type = String(file?.type || '').trim().toLowerCase();
        const name = String(file?.name || '').trim().toLowerCase();
        if (canUseDynamicChatBackgrounds()) {
          return type.startsWith('image/') || type === 'video/mp4' || /\.(png|jpe?g|webp|gif|mp4)$/.test(name);
        }
        if (isDynamicChatBackgroundFile(file)) return false;
        if (type === 'image/webp' || /\.webp$/.test(name)) {
          try { if (await window.SHEXImageCropper?.isAnimated?.(file)) return false; }
          catch (_) { return false; }
        }
        return ['image/png', 'image/jpeg', 'image/webp'].includes(type) || /\.(png|jpe?g|webp)$/.test(name);
      }

      function renderChatBackgroundUploadAccess(mask = document.querySelector('#ixSettingsMask')) {
        const enhanced = canUseDynamicChatBackgrounds();
        const root = mask || document;
        const input = root.querySelector?.('#ixBackgroundInput');
        const label = root.querySelector?.('#ixBackgroundUploadLabel');
        const clear = root.querySelector?.('#ixClearBackground');
        const status = root.querySelector?.('#ixBackgroundStatus');
        if (label) label.textContent = enhanced ? '自定义' : '上传图片';
        if (input) input.accept = enhanced ? DYNAMIC_CHAT_BACKGROUND_ACCEPT : STATIC_CHAT_BACKGROUND_ACCEPT;
        if (clear) clear.textContent = enhanced ? '恢复默认' : '恢复默认背景';
        if (status) {
          status.hidden = !enhanced;
          status.textContent = enhanced
            ? '可以上传图片、GIF、短视频作为背景；MP4 不超过 15 秒、10MB，GIF 会保留原格式。'
            : '';
        }
        return enhanced;
      }

      function logXLinkAccessDebug(blockedAt = "check", allowXLink = false, extra = {}) {
        let current = null;
        let disclaimerState = {};
        try {
          current = window.SHEXAuth?.current?.() || JSON.parse(localStorage.getItem('shex_auth_session_v1') || 'null');
        } catch (_) {
          current = null;
        }
        try {
          disclaimerState = JSON.parse(localStorage.getItem('shex_x_link_disclaimer_v1') || '{}');
        } catch (_) {
          disclaimerState = {};
        }
        shexDebugLog('log', '[XLINK_ACCESS_DEBUG]', {
          username: current?.username,
          userId: current?.userId,
          role: current?.role,
          isAdmin: current?.isAdmin,
          isAdminResult: isShexAdminUser(),
          resourceLimitMode: X_LINK_RESOURCE_LIMIT_MODE,
          plan: current?.plan || current?.subscription?.plan || '',
          energyBalance: current?.energyBalance ?? current?.quota?.packBalance ?? '',
          disclaimerAccepted: Boolean(disclaimerState.xLinkDisclaimerRead && disclaimerState.xLinkDisclaimerAgreed),
          blockedAt,
          allowXLink,
          ...extra
        });
      }
      window.SHEXLogXLinkAccessDebug = logXLinkAccessDebug;

      function logAdminCheckDebug(caller = 'check') {
        let current = null;
        try {
          current = window.SHEXAuth?.current?.() || JSON.parse(localStorage.getItem('shex_auth_session_v1') || 'null');
        } catch (_) {
          current = null;
        }
        shexDebugLog('log', '[ADMIN_CHECK_DEBUG]', {
          caller,
          username: current?.username,
          displayName: current?.displayName,
          userId: current?.userId,
          role: current?.role,
          isAdmin: current?.isAdmin,
          authIsAdmin: window.SHEXAuth?.isAdmin?.(),
          isShexAdminUserResult: isShexAdminUser(current)
        });
      }
      window.SHEXLogAdminCheckDebug = logAdminCheckDebug;

      function isXLinkResourceLimitActive() {
        const active = X_LINK_RESOURCE_LIMIT_MODE && !isShexAdminUser();
        if (active) logXLinkAccessDebug('resource_limit', false);
        return active;
      }

      function showXLinkResourceLimitNotice() {
        let overlay = document.querySelector('#xResourceLimitOverlay');
        if (!overlay) {
          overlay = document.createElement('div');
          overlay.id = 'xResourceLimitOverlay';
          overlay.className = 'x-resource-limit-overlay';
          overlay.setAttribute('role', 'dialog');
          overlay.setAttribute('aria-modal', 'true');
          overlay.setAttribute('aria-labelledby', 'xResourceLimitTitle');
          overlay.innerHTML = `
            <section class="x-resource-limit-modal">
              <h3 id="xResourceLimitTitle">X链接功能暂时关闭</h3>
              <p>由于当前云端资源额度不足，X链接相关功能将暂时关闭。</p>
              <p>探索工作室、课程展示、学员展示等页面仍可正常浏览。</p>
              <p>已创建的梦角资料、聊天记录和相关数据不会因此被删除。</p>
              <p>资源额度补充后，X链接功能会重新开放。</p>
              <button class="x-resource-limit-confirm" type="button">知道啦</button>
            </section>
          `;
          document.body.appendChild(overlay);
          overlay.addEventListener('click', (event) => {
            if (event.target === overlay || event.target.closest('.x-resource-limit-confirm')) {
              overlay.classList.remove('show');
              document.body.classList.remove('x-resource-limit-open');
            }
          });
        }
        document.body.classList.add('x-resource-limit-open');
        overlay.classList.add('show');
      }

      function isXLinkResourceLimitedHash(hash = window.location.hash) {
        return isXLinkResourceLimitActive() && X_LINK_RESOURCE_LIMIT_HASHES.has(hash);
      }

      function redirectXLinkLimitToStudio() {
        if (!isXLinkResourceLimitActive()) return false;
        if (!isXLinkResourceLimitedHash()) return false;
        history.replaceState(null, '', '#academy');
        document.body.classList.remove('ix-chat-page', 'x-clean-page');
        document.documentElement.classList.remove('x-clean-lock');
        delete document.body.dataset.xPage;
        window.requestAnimationFrame(() => {
          document.querySelector('#academy')?.scrollIntoView({ behavior: 'auto', block: 'start' });
          showXLinkResourceLimitNotice();
        });
        return true;
      }

      function setupXLinkResourceLimitMode() {
        if (isShexAdminUser()) {
          document.documentElement.classList.remove('x-link-resource-limited');
        }
        document.addEventListener('click', (event) => {
          const link = event.target.closest?.('a[href], button');
          const href = link?.getAttribute?.('href') || '';
          const id = link?.id || '';
          const targetHash = href && X_LINK_RESOURCE_LIMIT_HASHES.has(href) ? href
            : id === 'showMessage' ? '#x-message-chat'
              : id === 'showLetter' ? '#x-letter'
                : id === 'showSReply' ? '#x-reply'
                  : id === 'showCompanion' ? '#x-companion'
                    : id === 'showTaStatus' ? '#x-ta-status'
                      : id === 'showLinkStatus' ? '#x-link-status'
                        : '';
          if (!targetHash) return;
          logXLinkAccessDebug('entry_click', false, {
            href,
            targetHash,
            targetExists: Boolean(document.querySelector(targetHash === '#x-message-chat' ? '#xMessagePanel' : targetHash === '#x-letter' ? '#xLetterPanel' : targetHash === '#x-reply' ? '#xReplyPanel' : targetHash === '#x-companion' ? '#xCompanionPanel' : targetHash === '#x-ta-status' ? '#xTaStatusPanel' : targetHash === '#x-link-status' ? '#xLinkStatusPanel' : '#transmission')),
            elementId: id,
            elementText: String(link?.textContent || '').trim().slice(0, 40)
          });
        }, true);
        if (isShexAdminUser()) return;
        if (!isXLinkResourceLimitActive()) return;
        document.documentElement.classList.add('x-link-resource-limited');
        const limitSelectors = [
          'a[href="#transmission"]',
          'a[href="#x-message-chat"]',
          'a[href="#x-letter"]',
          'a[href="#x-reply"]',
          'a[href="#x-companion"]',
          'a[href="#x-ta-status"]',
          'a[href="#x-link-status"]',
          '#showMessage',
          '#showLetter',
          '#showSReply',
          '#showCompanion',
          '#showTaStatus',
          '#showLinkStatus',
          '#xEditIdentity',
          '#openMessage',
          '#openMessageAgain',
          '[data-message-kind]'
        ];
        document.addEventListener('click', (event) => {
          if (!isXLinkResourceLimitActive()) return;
          const target = event.target.closest(limitSelectors.join(','));
          if (!target) return;
          event.preventDefault();
          event.stopImmediatePropagation();
          if (window.location.hash !== '#academy') history.replaceState(null, '', '#academy');
          document.querySelector('#academy')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
          showXLinkResourceLimitNotice();
        }, true);
        document.querySelectorAll('a[href="#transmission"], a[href="#x-message-chat"], a[href="#x-letter"], a[href="#x-reply"], a[href="#x-companion"], a[href="#x-ta-status"], a[href="#x-link-status"]').forEach((link) => {
          link.setAttribute('aria-disabled', 'true');
          link.dataset.xResourceLimited = 'true';
        });
        document.querySelectorAll('#showMessage, #showLetter, #showSReply, #showCompanion, #showTaStatus, #showLinkStatus, #xEditIdentity, #openMessage, #openMessageAgain, [data-message-kind]').forEach((button) => {
          if (!(button instanceof HTMLElement)) return;
          button.setAttribute('aria-disabled', 'true');
          button.dataset.xResourceLimited = 'true';
        });
        document.querySelectorAll('#showMessage, #showLetter, #showSReply, #showCompanion').forEach((button) => {
          button.innerHTML = `${button.textContent || 'X链接'}<span class="x-resource-limit-button-note">暂时关闭</span>`;
        });
        redirectXLinkLimitToStudio();
        window.addEventListener('hashchange', redirectXLinkLimitToStudio, true);
        document.addEventListener('shex:auth-change', () => {
          if (!isShexAdminUser()) return;
          document.documentElement.classList.remove('x-link-resource-limited');
          document.querySelectorAll('[data-x-resource-limited="true"]').forEach((node) => {
            node.removeAttribute('aria-disabled');
            delete node.dataset.xResourceLimited;
          });
          document.querySelectorAll('.x-resource-limit-button-note').forEach((node) => node.remove());
        });
      }

      document.addEventListener('DOMContentLoaded', setupXLinkResourceLimitMode);

      setAppViewportVars();
      window.addEventListener('resize', setAppViewportVars, { passive: true });
      window.visualViewport?.addEventListener('resize', setAppViewportVars);
      window.addEventListener('orientationchange', () => {
        window.setTimeout(setAppViewportVars, 120);
        window.setTimeout(setAppViewportVars, 420);
      }, { passive: true });
      window.addEventListener('pageshow', setAppViewportVars);

      function setupUpdateNotice() {
        if (!document.querySelector('#home')) return;
        if (window.location.hash && window.location.hash !== '#home') return;

        try {
          if (localStorage.getItem(UPDATE_NOTICE_STORAGE_KEY) === UPDATE_NOTICE_VERSION) return;
        } catch (error) {
          console.warn('[UpdateNotice] localStorage unavailable', error);
        }

        const importantModalSelectors = [
          '.x-disclaimer-modal.show',
          '.ix-settings-mask.show',
          '.wechat-pop.open',
          '.feedback-modal.show',
          '.update-notice-overlay.show'
        ];

        const isImportantModalVisible = () => importantModalSelectors.some((selector) => {
          const node = document.querySelector(selector);
          return node && getComputedStyle(node).display !== 'none' && node.getBoundingClientRect().width > 0;
        });

        const updates = [
          ['X传讯体验优化', '新增条574条字卡'],
          ['塔罗模式升级', '塔罗模式新增一张牌、三张牌、五张牌的选择，使用时更贴近不同问题场景'],
          ['雷诺曼模式升级', '雷诺曼也支持多张牌，并保留牌号展示'],
          ['消息发送体验优化', '优化了自己发送消息时的显示节奏，减少“发出去慢半拍”的感觉'],
          ['图片消息体验优化', '优化了图片上传后的显示状态，让图片消息在传讯里出现得更稳定'],
          ['X链接数据保护加强', '优化了数据加载判断，尽量保护已有梦角资料、聊天记录和链接信息'],
          ['老用户资料保护优化', '减少老用户被误判成新用户的情况，避免已有记录被新的初始化内容影响'],
          ['登录与重新登录体验优化', '登录状态异常时，会出现更清楚、更温和的提示，重新登录和退出入口也更明确'],
          ['提示文案优化', '一些技术性提示改成了更容易理解的说法，尽量不让用户被复杂错误信息吓到'],
          ['学员展示页重做', '学员卡片重新整理为头像、姓名、ID、课程、状态、账号和标签，展示更清楚'],
          ['学员标签样式优化', '学员标签改成更清晰的小气泡样式，页面看起来更精致，也更方便快速浏览'],
          ['学员账号字段补充', '学员资料支持抖音、小红书、微信、B站等账号类型'],
          ['学员头像显示优化', '优化了学员头像字段读取，支持云端头像链接，默认头像也更稳定'],
          ['意见反馈入口优化', '登录后点右上角的用户名可以提交意见反馈，文字和图片都能整理到后台，方便后续继续改进'],
          ['X来信与回信细节整理', '继续优化来信、回信相关页面的命名和保存逻辑，让使用路径更清楚'],
          ['X陪伴体验整理', '继续调整陪伴页面的背景、音乐和返回体验，让陪伴感更稳定'],
          ['静态资源整理优化', '整理了首页背景、月亮图、X陪伴默认背景、音频等资源路径，减少部署后丢图的问题'],
          ['首页首屏加载优化', '优化了首页背景首次打开时的加载顺序，减少图片跑偏和灰屏的情况'],
          ['移动端细节调整', '针对手机端页面、弹窗、按钮和布局做了一些适配，让使用时更顺手'],
          ['更新记录弹窗优化', '新增简约版更新记录弹窗，后续每次更新后，都可以更清楚地看到网站变化'],
          ['细节体验优化', '修复了一些已知的小问题，让 SHE.X 使用起来更稳定、更完整']
        ];

        const overlay = document.createElement('div');
        overlay.className = 'update-notice-overlay';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-labelledby', 'updateNoticeTitle');
        overlay.innerHTML = `
          <section class="update-notice-modal">
            <button class="update-notice-close" type="button" aria-label="关闭更新记录">×</button>
            <header class="update-notice-header">
              <h3 class="update-notice-title" id="updateNoticeTitle">SHE.X 更新记录</h3>
              <p class="update-notice-subtitle">这次做了一些小优化</p>
            </header>
            <div class="update-notice-body">
              <div class="update-timeline">
                <span class="update-timeline-line" aria-hidden="true"></span>
                ${updates.map(([title, desc]) => `
                  <div class="update-timeline-item">
                    <span class="update-timeline-dot" aria-hidden="true"></span>
                    <div class="update-timeline-content">
                      <strong class="update-timeline-title">${title}</strong>
                      <p class="update-timeline-desc">${desc}</p>
                    </div>
                  </div>
                `).join('')}
              </div>
            </div>
            <div class="update-notice-footer">
              <p>如果页面显示异常，可以刷新后再试一次</p>
              <button class="update-notice-confirm" type="button">知道啦</button>
            </div>
          </section>
        `;

        const closeNotice = () => {
          try {
            localStorage.setItem(UPDATE_NOTICE_STORAGE_KEY, UPDATE_NOTICE_VERSION);
          } catch (error) {
            console.warn('[UpdateNotice] failed to write localStorage', error);
          }
          unlockUpdateNoticeScroll();
          overlay.classList.remove('show');
          window.setTimeout(() => overlay.remove(), 220);
        };

        overlay.querySelector('.update-notice-close')?.addEventListener('click', closeNotice);
        overlay.querySelector('.update-notice-confirm')?.addEventListener('click', closeNotice);
        const updateNoticeScroll = window.SHEXModalScroll?.create?.(overlay, {
          scrollTarget: '.update-notice-body'
        });
        let updateNoticeScrollY = 0;
        const lockUpdateNoticeScroll = () => {
          if (updateNoticeScroll) {
            updateNoticeScroll.open();
            return;
          }
          updateNoticeScrollY = window.scrollY || document.documentElement.scrollTop || 0;
          document.body.classList.add('update-notice-open');
          document.body.style.top = `-${updateNoticeScrollY}px`;
        };
        const unlockUpdateNoticeScroll = () => {
          if (updateNoticeScroll) {
            updateNoticeScroll.close();
            return;
          }
          document.body.classList.remove('update-notice-open');
          document.body.style.top = '';
          window.scrollTo(0, updateNoticeScrollY);
        };

        let attempts = 0;
        const showWhenReady = () => {
          attempts += 1;
          const landingReady = document.querySelector('#home')?.classList.contains('is-hero-ready');
          const pageBusy = document.body.classList.contains('x-clean-page') || document.body.classList.contains('ix-chat-page');
          if ((!landingReady || pageBusy || isImportantModalVisible()) && attempts < 10) {
            window.setTimeout(showWhenReady, 500);
            return;
          }
          if (!document.body.contains(overlay)) document.body.appendChild(overlay);
          lockUpdateNoticeScroll();
          requestAnimationFrame(() => overlay.classList.add('show'));
        };

        window.setTimeout(showWhenReady, 900);
      }

      // setupUpdateNotice(); // 已停用更新弹窗，如需恢复删掉这行前面的注释符号即可

function enterSite(target = '#site') {
        document.body.classList.add('entered');
        const studio = document.getElementById('studio');
        const transmission = document.getElementById('transmission');
        const about = document.getElementById('about');
        if (target === '#studio') {
          if (studio) studio.style.removeProperty('display');
          if (about) about.style.removeProperty('display');
          if (transmission) transmission.style.setProperty('display', 'none');
        } else if (target === '#transmission') {
          if (transmission) transmission.style.removeProperty('display');
          if (studio) studio.style.setProperty('display', 'none');
          if (about) about.style.setProperty('display', 'none');
        }
        const targetElement = document.querySelector(target);
        if (targetElement) targetElement.scrollIntoView({ behavior: 'smooth' });
      }
      document.querySelectorAll('a[href^="#"]').forEach((link) => {
        link.addEventListener('click', (event) => {
          const target = link.getAttribute('href');
          if (!target || target === '#home' || link.classList.contains('js-wechat')) return;
          const targetElement = document.querySelector(target);
          if (!targetElement) return;
          event.preventDefault();
          enterSite(target);
          history.pushState(null, '', target);
        });
      });
      let signatureTimer;
      let touchStartY = null;
      function peekSignature() {
        if (document.body.classList.contains('entered')) return;
        document.body.classList.add('signature-peek');
        window.clearTimeout(signatureTimer);
        signatureTimer = window.setTimeout(() => {
          document.body.classList.remove('signature-peek');
        }, 1500);
      }
      window.addEventListener('wheel', (event) => {
        if (event.deltaY > 8 && !document.body.classList.contains('entered')) {
          event.preventDefault();
          peekSignature();
        }
      }, { passive: false });
      window.addEventListener('touchstart', (event) => {
        touchStartY = event.touches[0]?.clientY ?? null;
      }, { passive: true });
      window.addEventListener('touchmove', (event) => {
        if (document.body.classList.contains('entered') || touchStartY === null) return;
        const currentY = event.touches[0]?.clientY ?? touchStartY;
        if (touchStartY - currentY > 18) {
          event.preventDefault();
          peekSignature();
        }
      }, { passive: false });

