  const currentChatProactiveCooldownMs = 20 * 60 * 1000;
  const currentChatProactiveAfterUserPauseMs = 1 * 60 * 1000;
  const currentChatProactiveChance = 0.32;
  const currentChatProactiveCooldownKey = 'shex_x_message_current_proactive_cooldown_v1';
  const proactiveAwayNextMinDelayMs = 3 * 60 * 1000;
  const proactiveAwayNextMaxDelayMs = 12 * 60 * 1000;
  const proactiveSingleChatNextMinDelayMs = 5 * 60 * 1000;
  const proactiveSingleChatNextMaxDelayMs = 15 * 60 * 1000;
  const proactiveRetryMinDelayMs = 5 * 60 * 1000;
  const proactiveRetryMaxDelayMs = 15 * 60 * 1000;
  const proactiveTestMinDelayMs = 30 * 1000;
  const proactiveTestMaxDelayMs = 60 * 1000;
