  function classifyRepeatedIntent(text) {
    const value = String(text || '').trim();
    if (!value) return '';
    return Object.entries(repeatedIntentPatterns).find(([, pattern]) => pattern.test(value))?.[0] || '';
  }

  function repeatedIntentDreamKey(dream = null) {
    const state = readState();
    const active = requireActiveConversation(state);
    const chatId = conversationKey(active) || 'chat:default';
    const dreamId = dream?.id || (active?.kind === 'single' ? active.dream?.id : '') || 'default';
    return `${chatId}|dream:${dreamId}`;
  }

  function repeatedIntentReply(text, dream = null) {
    if (mode.value === 'english' || mode.value === 'tarot' || mode.value === 'lenormand') return '';
    const intent = classifyRepeatedIntent(text);
    if (!intent) return '';
    const nowTime = Date.now();
    const key = repeatedIntentDreamKey(dream);
    const history = readJson(repeatedIntentHistoryKey, {});
    const list = Array.isArray(history[key]) ? history[key] : [];
    const fresh = list.filter((item) => item && nowTime - Number(item.createdAt || 0) <= repeatedIntentKeepMs);
    const recentFive = fresh.slice(0, 5);
    const sameRecent = recentFive.filter((item) => item.intent === intent);
    const sameWithinWindow = sameRecent.filter((item) => nowTime - Number(item.createdAt || 0) <= repeatedIntentWindowMs);
    const repeatCount = sameRecent.length + 1;
    const repeated = sameWithinWindow.length >= 1 || sameRecent.length >= 2;
    const nextItem = { intent, text: String(text || '').trim().slice(0, 24), createdAt: nowTime };
    history[key] = [nextItem, ...fresh].slice(0, repeatedIntentMaxItems);
    writeJson(repeatedIntentHistoryKey, history);
    if (!repeated) return '';
    const pool = repeatedIntentReplies[intent] || [];
    const useSpecialIntentReply = Math.random() < 0.4;
    const reply = useSpecialIntentReply
      ? (pool[Math.floor(Math.random() * pool.length)] || pickUnknownIntentReply(text))
      : pickUnknownIntentReply(text);
    if (reply) {
      const active = requireActiveConversation();
      shexDebugLog('log', '[XChat] repeated intent detected', {
        chatId: conversationKey(active),
        dreamId: dream?.id || '',
        intent,
        repeatCount,
        route: useSpecialIntentReply ? 'repeated_intent_reply' : 'unknown_intent_reply'
      });
    }
    return reply;
  }

