  const softReplyHighFrequencyCategories = new Set(['goodnight', 'care', 'missing', 'love_confirm', 'current_state', 'relationship_security']);
  const softReplyEmotionalCategories = new Set(['comfort', 'care', 'relationship_security', 'self_worth_reassure', 'protective_care', 'emotional_checkin']);
