  function normalizeGenericRepeatText(text) {
    return String(text || '')
      .trim()
      .replace(/[，。！？!?,.、~～…\s]+/g, '')
      .replace(/[呀啦呢嘛啊哦哈嘿哇]{1,}$/g, '')
      .replace(/(.)\1{2,}/g, '$1$1')
      .slice(0, 30);
  }

  function genericRepeatSimilarGroup(text, normalizedText = '') {
    const value = String(text || '').trim();
    const compact = normalizedText || normalizeGenericRepeatText(value);
    return Object.entries(genericRepeatGroups).find(([, pattern]) => pattern.test(value) || pattern.test(compact))?.[0] || '';
  }

  function pickUnknownIntentReplyChoice(text, options = {}) {
    const routeKey = options.routeKey || softReplyKey(options.dream || null);
    const active = requireActiveConversation();
    const chatKind = active?.kind === 'group' ? 'group' : 'single';
    const reply = softenIxReply(pickFallbackReplyLine(chatKind), text, { forceQuestion: Math.random() < .25 });
    rememberSoftReplyRoute(routeKey, { route: 'unknown_intent_reply', text: reply, category: 'fallback' });
    return {
      text: reply,
      route: 'unknown_intent_reply',
      category: 'fallback'
    };
  }

  function pickUnknownIntentReply(text, options = {}) {
    return pickUnknownIntentReplyChoice(text, options).text;
  }

  function softReplyKey(dream = null) {
    return repeatedIntentDreamKey(dream);
  }

  function readSoftRouteHistory(key) {
    const history = readJson(softReplyRouteHistoryKey, {});
    return {
      history,
      list: Array.isArray(history[key]) ? history[key] : []
    };
  }

  function rememberSoftReplyRoute(key, item = {}) {
    if (!key || !item.route) return;
    const { history, list } = readSoftRouteHistory(key);
    history[key] = [{ ...item, createdAt: Date.now() }, ...list].slice(0, softReplyMaxHistory);
    writeJson(softReplyRouteHistoryKey, history);
  }

  function availableUserCardLines(routeKey = '', dreamId = '') {
    const customCards = (dreamId ? readDreamReplyCards(dreamId) : [])
      .map(stripIxPeriods)
      .filter(Boolean);
    if (!customCards.length) return [];
    const recent = routeKey ? readSoftRouteHistory(routeKey).list : [];
    const recentCardTexts = new Set(recent.filter((item) => item.route === 'user_card_reply').slice(0, 10).map((item) => stripIxPeriods(item.text)).filter(Boolean));
    const available = customCards.filter((line) => !recentCardTexts.has(stripIxPeriods(line)));
    return available.length ? available : customCards;
  }

  function totalUserCardCount(dreamId = '') {
    return (dreamId ? readDreamReplyCards(dreamId) : [])
      .map(stripIxPeriods)
      .filter(Boolean).length;
  }

  function userCardReplyWeight(count = totalUserCardCount()) {
    const value = Number(count || 0);
    if (value <= 0) return 0;
    if (value <= 2) return 0.04;
    if (value <= 5) return 0.08;
    if (value <= 12) return 0.12;
    if (value <= 30) return 0.16;
    return 0.20;
  }

  function getUserCardReplyChance(count = totalUserCardCount(), chatKind = 'single') {
    const value = Number(count || 0);
    if (value <= 0) return 0;
    const isGroup = chatKind === 'group';
    if (value === 1) return isGroup ? 0.04 : 0.08;
    if (value <= 3) return isGroup ? 0.08 : 0.12;
    if (value <= 8) return isGroup ? 0.12 : 0.18;
    if (value <= 20) return isGroup ? 0.16 : 0.24;
    if (value <= 50) return isGroup ? 0.20 : 0.30;
    return isGroup ? 0.24 : 0.35;
  }

  function pickUserCardReply(text, options = {}) {
    const cards = availableUserCardLines(options.routeKey || '', options.dreamId || '');
    if (!cards.length) return '';
    return softenIxReply(cards[Math.floor(Math.random() * cards.length)], text);
  }

  function hasRecentSoftRoute(routeKey, route, count) {
    return readSoftRouteHistory(routeKey).list.slice(0, count).some((item) => item.route === route);
  }

  function consecutiveSoftRouteCount(routeKey, route) {
    let count = 0;
    for (const item of readSoftRouteHistory(routeKey).list) {
      if (item.route !== route) break;
      count += 1;
    }
    return count;
  }

  function canonicalSoftCategory(category = '', text = '') {
    const value = String(category || '').trim();
    if (['goodnight', 'care', 'missing', 'love_confirm', 'lover_jealousy', 'current_state', 'comfort', 'relationship_security', 'playful', 'possessive'].includes(value)) return value;
    if (/晚安|睡觉|睡了|好梦|困了|早点睡/.test(text)) return 'goodnight';
    if (/吃饭|饿|喝水|胃|休息|熬夜/.test(text)) return 'care';
    if (/想你|想我|惦记|见你/.test(text)) return 'missing';
    if (/喜欢|爱|亲亲|抱抱|贴贴|恋爱/.test(text)) return 'love_confirm';
    if (/吃醋|醋|别人|不理|冷落/.test(text)) return 'lover_jealousy';
    if (/在干嘛|干嘛|做什么|在吗|你呢|去哪/.test(text)) return 'current_state';
    if (/难过|委屈|哭|崩|撑不住|不开心|烦|焦虑|害怕|累|困/.test(text)) return 'comfort';
    return value || 'fallback';
  }

  function previousSoftContextCategory() {
    try {
      const context = typeof getIxContext === 'function' ? getIxContext() : {};
      return canonicalSoftCategory(context.category || '', '');
    } catch (_) {
      return '';
    }
  }

  function isSoftShortInput(text) {
    return softReplyShortPattern.test(normalizeGenericRepeatText(text));
  }

  function isSoftSubjectivityAllowed(text, category, routeKey) {
    if (mode.value === 'english' || mode.value === 'tarot' || mode.value === 'lenormand') return false;
    if (hasRecentSoftRoute(routeKey, 'subjectivity_reply', 5)) return false;
    if (softReplySensitivePattern.test(text)) return false;
    if (softReplyQuestionPattern.test(String(text || '').trim())) return false;
    if (softReplyFunctionalCategories.has(category)) return false;
    return true;
  }

  function softCategoryPool(category) {
    const pool = getRepliesByCategory(category);
    return Array.isArray(pool) && pool.length ? pool : getRepliesByCategory('fallback');
  }

  function pickSoftCategoryLine(category, text, routeKey = '') {
    const pool = softCategoryPool(category).map(stripIxPeriods).filter(Boolean);
    if (!pool.length) return '';
    let recentTexts = [];
    try {
      recentTexts = chatHistory().slice(-24).map((item) => stripIxPeriods(item.text)).filter(Boolean);
    } catch (_) {}
    const routeTexts = readSoftRouteHistory(routeKey).list.slice(0, 10).map((item) => stripIxPeriods(item.text)).filter(Boolean);
    const blocked = new Set([...recentTexts, ...routeTexts]);
    const available = pool.filter((line) => !blocked.has(stripIxPeriods(line)));
    return softenIxReply(pickIxLine(available.length ? available : pool), text, { forceQuestion: Math.random() < .22 });
  }

  function pickAdjacentSoftCategory(category) {
    const candidates = adjacentCategoryMap[category] || adjacentCategoryMap.fallback || ['fallback'];
    const available = candidates.filter((item) => softCategoryPool(item).length);
    return (available.length ? available : ['fallback'])[Math.floor(Math.random() * (available.length || 1))];
  }

  function weightedSoftRoutePick(items) {
    const available = items.filter((item) => item.weight > 0);
    const total = available.reduce((sum, item) => sum + item.weight, 0);
    if (!available.length || total <= 0) return 'category_reply';
    let cursor = Math.random() * total;
    for (const item of available) {
      cursor -= item.weight;
      if (cursor <= 0) return item.route;
    }
    return available[0].route;
  }

  function chooseSoftReplyRoute(text, dream = null, category = 'fallback', context = {}) {
    if (mode.value === 'tarot' || mode.value === 'lenormand') return null;
    void category;
    void context;
    const routeKey = softReplyKey(dream);
    const active = requireActiveConversation();
    const chatKind = active?.kind === 'group' ? 'group' : 'single';
    const rawText = String(text || '').trim();
    const reply = softenIxReply(pickFallbackReplyLine(chatKind), rawText, { forceQuestion: Math.random() < .25 });
    rememberSoftReplyRoute(routeKey, { route: 'fallback_reply', text: reply, category: 'fallback' });
    shexDebugLog('log', '[XChat] slim fallback route selected', {
      chatId: conversationKey(active),
      dreamId: dream?.id || '',
      chatType: chatKind,
      category: 'fallback',
      route: 'fallback_reply'
    });
    return { text: reply, route: 'fallback_reply', category: 'fallback', hasUserCards: false };
  }

  function genericRepeatReply(text, dream = null) {
    if (mode.value === 'english' || mode.value === 'tarot' || mode.value === 'lenormand') return null;
    if (classifyRepeatedIntent(text)) return null;
    const normalizedText = normalizeGenericRepeatText(text);
    if (!normalizedText || normalizedText.length > 30) return null;
    const similarGroup = genericRepeatSimilarGroup(text, normalizedText);
    if (!similarGroup && normalizedText.length > 10) return null;
    const nowTime = Date.now();
    const key = repeatedIntentDreamKey(dream);
    const history = readJson(genericRepeatHistoryKey, {});
    const list = Array.isArray(history[key]) ? history[key] : [];
    const fresh = list.filter((item) => item && nowTime - Number(item.createdAt || 0) <= genericRepeatKeepMs);
    const recentFive = fresh.slice(0, 5);
    const sameText = recentFive.filter((item) => item.normalizedText && item.normalizedText === normalizedText);
    const sameGroup = similarGroup ? recentFive.filter((item) => item.similarGroup === similarGroup) : [];
    const sameGroupWindow = sameGroup.filter((item) => nowTime - Number(item.createdAt || 0) <= genericRepeatWindowMs);
    const repeatCount = Math.max(sameText.length + 1, sameGroup.length + 1);
    const repeated = sameText.length >= 1 || sameGroup.length >= 1 || sameGroupWindow.length >= 1;
    const nextItem = { normalizedText, similarGroup, createdAt: nowTime };
    let reply = '';
    let route = '';
    if (repeated) {
      const active = requireActiveConversation();
      const chatKind = active?.kind === 'group' ? 'group' : 'single';
      const userCards = availableUserCardLines(key, dream?.id || '');
      const hasUserCards = userCards.length > 0;
      const userCardChance = hasUserCards && consecutiveSoftRouteCount(key, 'user_card_reply') < 1
        ? getUserCardReplyChance(userCards.length, chatKind)
        : 0;
      const recentGenericRoutes = fresh.slice(0, 2).filter((item) => item.route === 'generic_repeated_reply');
      const canUseGeneric = recentGenericRoutes.length === 0;
      const roll = Math.random();
      if (canUseGeneric && roll < .3) {
        reply = softenIxReply(pickIxLine(genericRepeatedReplies), text);
        route = 'generic_repeated_reply';
      } else if (userCardChance > 0 && Math.random() < userCardChance) {
        reply = pickUserCardReply(text, { routeKey: key, dreamId: dream?.id || '' });
        route = 'user_card_reply';
      } else {
        const unknownChoice = pickUnknownIntentReplyChoice(text, { routeKey: key, dream });
        reply = unknownChoice.text;
        route = unknownChoice.route || 'unknown_intent_reply';
      }
      nextItem.route = route;
      if (reply) rememberSoftReplyRoute(key, { route, text: reply, category: 'generic_repeat' });
    }
    history[key] = [nextItem, ...fresh].slice(0, genericRepeatMaxItems);
    writeJson(genericRepeatHistoryKey, history);
    if (!reply) return null;
    const active = requireActiveConversation();
      shexDebugLog('log', '[XChat] generic repeat detected', {
      chatId: conversationKey(active),
      dreamId: dream?.id || '',
      normalizedText,
      similarGroup,
      repeatCount,
      route
    });
    return { text: reply, route };
  }

  function xDataStatus() {
    return window.SHEXAuth?.getDataLoadStatus?.() || window.SHEXAuth?.dataLoadStatus?.() || 'idle';
  }

  function xCloudSnapshotMeta() {
    try {
      return typeof window.SHEXAuth?.cloudSnapshotMeta === 'function'
        ? window.SHEXAuth.cloudSnapshotMeta()
        : { keyCount: 0, hasXIdentity: false, hasXState: false, hasLegacyXChat: false, loaded: false };
    } catch (_) {
      return { keyCount: 0, hasXIdentity: false, hasXState: false, hasLegacyXChat: false, loaded: false };
    }
  }

  function xHasLoggedInUser() {
    return Boolean(window.SHEXAuth?.current?.()?.userId);
  }

  function xIsAdminUser() {
    if (typeof window.SHEXIsAdminUser === 'function') return window.SHEXIsAdminUser();
    return Boolean(window.SHEXAuth?.isAdmin?.());
  }

  // X103：loadSnapshot 不带套餐；登录后若套餐缓存为空，补拉一次 getMyPlan，
  // 成功后由 shex:plan-updated 刷新模型面板，避免 Plus/Pro/Ultra 被按 Free 判定。
  let characterPlanHydrateAt = 0;
  function hydrateCharacterPlanOnce() {
    const auth = window.SHEXAuth;
    if (typeof auth?.getMyPlan !== 'function' || !auth?.current?.()) return;
    if (Date.now() - characterPlanHydrateAt < 15000) return;
    characterPlanHydrateAt = Date.now();
    Promise.resolve().then(() => auth.getMyPlan()).catch(() => {});
  }

  function cachedCharacterPlan() {
    const plan = window.SHEXAuth?.getCachedPlan?.() || null;
    if (!plan) hydrateCharacterPlanOnce();
    return plan;
  }

  function characterAIModelAllowed(modelId) {
    const api = window.SHEXCharacterAI;
    if (!api?.isModelAllowed) return xIsAdminUser();
    return api.isModelAllowed(modelId, cachedCharacterPlan() || {}, xIsAdminUser());
  }

  function characterCapabilityEnabled(field) {
    if (xIsAdminUser()) return true;
    const latestPlan = cachedCharacterPlan();
    if (latestPlan && Object.prototype.hasOwnProperty.call(latestPlan, field)) {
      return latestPlan[field] === true;
    }
    const snapshotCapabilities = window.SHEXAuth?.getCachedCharacterCapabilities?.();
    if (snapshotCapabilities && Object.prototype.hasOwnProperty.call(snapshotCapabilities, field)) {
      return snapshotCapabilities[field] === true;
    }
    return false;
  }

  const characterGalleryAccessible = () => xHasLoggedInUser();
  const characterCreatorAccessible = () => xHasLoggedInUser();
  const characterGalleryEntryVisible = () => xHasLoggedInUser();

  const X_ADMIN_INJECTION_VIEWER_KEY = 'shex_admin_injection_viewer_v1';
  const X_ADMIN_STREAM_PROBE_KEY = 'shex_admin_stream_probe_v1';

  function characterAIInjectionViewerEnabled() {
    if (!xIsAdminUser()) return false;
    try {
      return localStorage.getItem(X_ADMIN_INJECTION_VIEWER_KEY) === '1';
    } catch (_) {
      return false;
    }
  }

  function setCharacterAIInjectionViewerEnabled(enabled) {
    if (!xIsAdminUser()) return false;
    try {
      localStorage.setItem(X_ADMIN_INJECTION_VIEWER_KEY, enabled === true ? '1' : '0');
      return true;
    } catch (_) {
      return false;
    }
  }

  function characterAIStreamProbeEnabled() {
    if (!xIsAdminUser()) return false;
    try {
      return localStorage.getItem(X_ADMIN_STREAM_PROBE_KEY) === '1';
    } catch (_) {
      return false;
    }
  }

  function setCharacterAIStreamProbeEnabled(enabled) {
    if (!xIsAdminUser()) return false;
    try {
      localStorage.setItem(X_ADMIN_STREAM_PROBE_KEY, enabled === true ? '1' : '0');
      return true;
    } catch (_) {
      return false;
    }
  }

  function xIsAIModelTierPreview() {
    try {
      const host = String(window.location.hostname || '').toLowerCase();
      const isLocalPreview = host === '127.0.0.1' || host === 'localhost';
      return isLocalPreview && new URLSearchParams(window.location.search).get('preview') === 'ai-model-tiers';
    } catch (_) {
      return false;
    }
  }

  function characterAIAccessForDream(dream = null) {
    const isAdmin = xIsAdminUser();
    const isGuest = Boolean(window.SHEXAuth?.current?.()?.guest);
    const isGalleryCharacter = window.SHEXCharacterAI?.isGalleryCharacter?.(dream) === true;
    const hasCharacterAI = characterCapabilityEnabled('characterAIEnabled');
    const isOwnedPrivate = Boolean(dream?.id) && !isGalleryCharacter;
    return Object.freeze({
      canUseAI: isGuest || isAdmin || isGalleryCharacter || (hasCharacterAI && isOwnedPrivate),
      canUseDualMode: isOwnedPrivate && (isGuest || isAdmin || hasCharacterAI),
      canConfigureAIModes: isGalleryCharacter || (isOwnedPrivate && (isGuest || isAdmin || hasCharacterAI)),
      canSelectModel: isGuest || isGalleryCharacter || isAdmin || hasCharacterAI,
      isGalleryCharacter
    });
  }

  function characterAIEnabledForDream(dream = null) {
    return characterAIAccessForDream(dream).canUseAI;
  }

  function shouldTrackSourceMode(active = requireActiveConversation()) {
    return active?.kind === 'single' && characterAIAccessForDream(active.dream).canUseDualMode;
  }

  function characterAIReplyMode(active = requireActiveConversation(), chatMode = mode.value, media = null) {
    const api = window.SHEXCharacterAI;
    if (active?.kind === 'world_run' && active.worldRun?.runId) return 'ai';
    if (!api || active?.kind !== 'single' || !active?.dream) return 'library';
    const access = characterAIAccessForDream(active.dream);
    const aiEnabled = access.canUseAI;
    const effective = api.effectiveReplyMode(active.dream, aiEnabled);
    // 广场角色的有效模式固定为 AI。即使客户端残留了字卡专属状态，也不得落入字卡链路。
    if (access.isGalleryCharacter && effective === 'ai') return 'ai';
    return api.shouldUseAI({
      isAdmin: xIsAdminUser(),
      aiEnabled,
      replyMode: effective,
      conversationKind: active.kind,
      chatMode,
      media
    }) ? 'ai' : 'library';
  }

  function isCardReplyTimingConversation(active = requireActiveConversation()) {
    if (active?.kind === 'world_run') return false;
    if (active?.kind !== 'single' || !active?.dream) return true;
    const api = window.SHEXCharacterAI;
    const access = characterAIAccessForDream(active.dream);
    const effective = api && access.canUseAI
      ? api.effectiveReplyMode(active.dream, true)
      : 'library';
    return effective !== 'ai';
  }

  function xRestoringFromCloud() {
    return Boolean(window.SHEXAuth?.isRestoringFromCloud?.());
  }

  function xShouldWaitForCloudRestore() {
    if (!xHasLoggedInUser()) return false;
    return xRestoringFromCloud() || !['success', 'failed'].includes(xDataStatus());
  }

  function renderXRestoreWaitingNotice(notice, reason = 'data_loading') {
    if (!notice) return;
    const labelText = reason === 'restore_failed' ? '云端还在同步，请稍等一下' : '正在链接专属于你的世界';
    // X103：已经是新版加载页（含 index.html 里的静态开机加载页）就只接管、只改文案，不重建节点，动画不中断。
    if (notice.querySelector('.x-scene')) {
      delete notice.dataset.boot;
      notice.setAttribute('role', 'status');
      notice.setAttribute('aria-live', 'polite');
      const label = notice.querySelector('.x-scene__status');
      if (label && label.textContent !== labelText) label.textContent = labelText;
      window.SHEXLoadingScene?.(notice);
      return;
    }
    // X103：整屏加载画面：深紫星空、蜿蜒路径，发光方块沿路径向远方前进；数据就绪后整体淡出。
    notice.setAttribute('role', 'status');
    notice.setAttribute('aria-live', 'polite');
    notice.innerHTML = '<canvas class="x-scene" aria-hidden="true"></canvas><div class="x-scene__logo" aria-hidden="true">SHEX</div><div class="x-scene__status"></div>';
    notice.querySelector('.x-scene__status').textContent = labelText;
    window.SHEXLoadingScene?.(notice);
    shexDebugLog('log', '[XLINK_LOADING_DEBUG]', {
      action: 'show_restore_waiting',
      dataLoadStatus: xDataStatus(),
      restoringFromCloud: xRestoringFromCloud(),
      reason
    });
  }

  function xScopedStorageKey(key) {
    try {
      return typeof window.SHEXAuth?.scopedKey === 'function' ? window.SHEXAuth.scopedKey(key) : key;
    } catch (_) {
      return key;
    }
  }

  function logXLinkIdentityCheck(extra = {}) {
    const key = 'shex_x_link_identity';
    const scopedKey = xScopedStorageKey(key);
    const scopedValue = localStorage.getItem(scopedKey);
    const rawValue = localStorage.getItem(key);
    shexDebugLog('log', '[XLINK_IDENTITY_CHECK]', {
      userId: currentXUser()?.userId || '',
      dataLoadStatus: xDataStatus(),
      restoringFromCloud: xRestoringFromCloud(),
      xIdentityKey: key,
      scopedKey,
      scopedValueExists: Boolean(scopedValue),
      unscopedValueExists: Boolean(rawValue),
      hasIdentity: Boolean(localStorage.getItem(key)),
      rawValue: rawValue || scopedValue || '',
      ...extra
    });
  }

  function logXLinkRestoreDebug(extra = {}) {
    const key = 'shex_x_link_identity';
    const scopedKey = xScopedStorageKey(key);
    shexDebugLog('log', '[XLINK_RESTORE_DEBUG]', {
      userId: currentXUser()?.userId || '',
      ownerId: window.SHEXAuth?.ownerId?.() || '',
      dataLoadStatus: xDataStatus(),
      restoringFromCloud: xRestoringFromCloud(),
      rawIdentityValue: localStorage.getItem(key) || localStorage.getItem(scopedKey) || '',
      scopedIdentityKey: scopedKey,
      disclaimerState: JSON.stringify(readXDisclaimerState()),
      willShowIdentityForm: false,
      willShowXHome: false,
      reason: '',
      ...extra
    });
  }

  function redirectToAuthForCloudFeature() {
    showChatToast('请先登录后使用 SHE.X 云端功能');
    window.setTimeout(() => {
      window.location.href = './auth.html?login=1&notice=login_required';
    }, 650);
  }

  function xCanUseFirstSetup() {
    if (!xHasLoggedInUser()) return false;
    return xDataStatus() === 'success';
  }

  function showXDataLoadingNotice(status = xDataStatus()) {
    if (!xHasLoggedInUser()) {
      window.SHEXLogXLinkAccessDebug?.('not_logged_in', false, { dataStatus: status });
      redirectToAuthForCloudFeature();
      return;
    }
    showXRestoreWaitingPanel(status === 'failed' ? 'restore_failed' : 'data_loading');
    window.SHEXLogXLinkAccessDebug?.(`data_${status || 'idle'}`, false, { dataStatus: status });
    if (status === 'failed') showChatToast('数据加载失败，请刷新或重新登录');
    else showChatToast(FIRST_SETUP_BLOCK_MESSAGE);
  }

  function showXRestoreWaitingPanel(reason = 'data_loading') {
    const panel = $('#xIdentityPanel');
    if (!panel) return;
    setXLinkView('loading', 'show_restore_waiting');
    let notice = $('#xRestoreWaitingNotice');
    if (!notice) {
      notice = document.createElement('div');
      notice.id = 'xRestoreWaitingNotice';
      notice.className = 'x-restore-waiting';
      notice.innerHTML = '<strong>正在恢复你的 X链接数据，请稍等</strong><p>正在读取云端已有的梦角、聊天和连接资料，不会覆盖你的旧数据。</p>';
      panel.prepend(notice);
    }
    renderXRestoreWaitingNotice(notice, reason);
    const form = $('#xIdentityForm');
    if (form) form.style.display = 'none';
    logXLinkRestoreDebug({
      step: 'show_restore_waiting_panel',
      reason,
      hasIdentityBeforeRestore: Boolean(localStorage.getItem('shex_x_link_identity')),
      willShowIdentityForm: false,
      willShowXHome: false
    });
  }

  // X103：加载画面淡出后再移除（移除后 canvas 绘制循环自动停止）。立即改掉 id，所有“是否仍在加载”的判断马上生效，不因动画多等。
  function retireXRestoreWaitingNotice() {
    const notice = document.querySelector('#xRestoreWaitingNotice');
    if (!notice) return;
    notice.id = 'xRestoreWaitingNoticeLeaving';
    notice.classList.add('is-leaving');
    window.setTimeout(() => notice.remove(), 650);
  }

  // X103：静态开机加载页的兜底收起。正常情况由 X链接的加载流程接管（去掉 data-boot）并在数据就绪后散开；
  // 没被接管时（未登录、不在 X链接页等），只要不再需要等云端恢复就散开；整页 reload 期间保持遮挡。
  function settleXBootCover(force = false) {
    const notice = document.querySelector('#xRestoreWaitingNotice[data-boot]');
    if (!notice || window.SHEX_RELOADING_FOR_RESTORE) return;
    if (!force && xShouldWaitForCloudRestore()) return;
    retireXRestoreWaitingNotice();
  }
  ['shex:data-load-status', 'shex:user-data-restored', 'shex:user-data-restore-failed'].forEach((name) => {
    document.addEventListener(name, () => window.setTimeout(() => settleXBootCover(), 0));
  });
  window.setTimeout(() => settleXBootCover(), 0);
  // 免登录访客的数据恢复是同步完成的，可能早于上面的监听注册，这里补两次兜底收起。
  window.setTimeout(() => settleXBootCover(), 600);
  window.setTimeout(() => settleXBootCover(), 1600);
  window.setTimeout(() => settleXBootCover(true), 15000);
  // 免登录访客的数据恢复可能在 X世界入口绑定前就完成，导致入口停在加载态；多次兜底重试进入。
  const retryGuestXWorldEntry = () => {
    const session = window.SHEXAuth?.current?.();
    if (!session?.guest || window.location.hash !== '#x-world') return;
    if (!document.querySelector('#xRestoreWaitingNotice')) return;
    document.getElementById('showXWorld')?.click();
  };
  document.addEventListener('DOMContentLoaded', () => window.setTimeout(retryGuestXWorldEntry, 200));
  window.setTimeout(retryGuestXWorldEntry, 1000);
  window.setTimeout(retryGuestXWorldEntry, 2600);
  window.addEventListener('load', () => window.setTimeout(retryGuestXWorldEntry, 0));

  function clearXRestoreWaitingPanel() {
    retireXRestoreWaitingNotice();
    const form = $('#xIdentityForm');
    if (form) form.style.display = '';
  }

  function currentXUser() {
    try {
      return window.SHEXAuth?.current?.() || JSON.parse(localStorage.getItem('shex_auth_session_v1') || 'null');
    } catch (_) {
      return null;
    }
  }

