      logXLinkEntryChainDebug({ step: 'openPage_blocked', targetPage: page, blockedAt: 'ensure_ready_failed', nextAction: 'wait_or_notice' });
      window.SHEXLogXLinkAccessDebug?.('ensure_ready_failed', false, { page });
