      const inviteLevelId = playInviteLevelId;
      playInviteLevelId = '';
      void window.SHEXPlay?.enter?.(route, { origin:playOrigin, ...(inviteLevelId ? { levelId:inviteLevelId } : {}) });
      if (push) history.replaceState(null, '', route === 'choice' ? '#x-play/choice' : route === 'ludo' ? '#x-play/ludo' : '#x-play');
