  function returnToXLinkHome(options = {}) {
    const fromView = document.body.dataset.xPage || 'unknown';
    const currentHashBefore = location.hash;
    const root = document.documentElement;
    const body = document.body;
    const previousRootScrollBehavior = root.style.scrollBehavior;
    const previousBodyScrollBehavior = body.style.scrollBehavior;
    const restoreScrollBehavior = () => {
      root.style.scrollBehavior = previousRootScrollBehavior;
      body.style.scrollBehavior = previousBodyScrollBehavior;
    };
    root.style.scrollBehavior = 'auto';
    body.style.scrollBehavior = 'auto';
    body.classList.add('entered');
    window.__SHEX_RETURNING_TO_XLINK_HOME_UNTIL = Date.now() + 900;
    shexDebugLog('log', '[XLINK_RETURN_CLICK]', {
      fromView,
      currentHashBefore,
      scrollYBefore: window.scrollY,
      target: '#transmission'
    });
    leaveConversation('return_to_xlink_home');
    setXLinkView('home', 'close_page');
    if (options.pushHash !== false && location.hash !== '#transmission') history.replaceState(null, '', '#transmission');
    const jumpToTransmission = () => {
      const target = $('#transmission');
      if (target) {
        const targetTop = target.getBoundingClientRect().top + window.pageYOffset;
        window.scrollTo({ top: targetTop, left: 0, behavior: 'auto' });
      }
      shexDebugLog('log', '[XLINK_RETURN_DEBUG]', {
        fromView,
        targetHash: '#transmission',
        currentHashBefore,
        currentHashAfter: location.hash,
        scrollYAfter: window.scrollY,
        targetTop: target?.getBoundingClientRect?.().top,
        usedSmoothScroll: false,
        bodyEntered: body.classList.contains('entered'),
        visiblePanels: visibleXPanels(),
        scrollTargetExists: Boolean(target)
      });
      if (location.hash !== '#transmission') {
        console.warn('[XLINK_RETURN_WRONG_TARGET]', {
          fromView,
          currentHash: location.hash,
          scrollY: window.scrollY,
          reason: 'hash_not_transmission_after_return'
        });
      }
    };
    window.requestAnimationFrame(() => {
      jumpToTransmission();
      window.requestAnimationFrame(jumpToTransmission);
      window.setTimeout(() => {
        jumpToTransmission();
        ensureXDisclaimerAccepted();
        restoreScrollBehavior();
        window.__SHEX_RETURNING_TO_XLINK_HOME_UNTIL = 0;
      }, 180);
    });
  }

  function returnToXWorldHome(options = {}) {
    const fromView = document.body.dataset.xPage || 'unknown';
    const currentHashBefore = location.hash;
    const root = document.documentElement;
    const body = document.body;
    const previousRootScrollBehavior = root.style.scrollBehavior;
    const previousBodyScrollBehavior = body.style.scrollBehavior;
    const restoreScrollBehavior = () => {
      root.style.scrollBehavior = previousRootScrollBehavior;
      body.style.scrollBehavior = previousBodyScrollBehavior;
    };
    root.style.scrollBehavior = 'auto';
    body.style.scrollBehavior = 'auto';
    body.classList.add('entered');
    window.__SHEX_RETURNING_TO_XLINK_HOME_UNTIL = Date.now() + 900;
    shexDebugLog('log', '[XLINK_RETURN_CLICK]', {
      fromView,
      currentHashBefore,
      scrollYBefore: window.scrollY,
      target: '#x-world'
    });
    leaveConversation('return_to_x_world');
    openPage('world', false);
    if (options.pushHash !== false && location.hash !== hashes.world) history.replaceState(null, '', hashes.world);
    lastXLinkRouteSignature = '';
    const jumpToTransmission = () => {
      const target = $('#transmission');
      if (target) {
        const targetTop = target.getBoundingClientRect().top + window.pageYOffset;
        window.scrollTo({ top: targetTop, left: 0, behavior: 'auto' });
      }
      shexDebugLog('log', '[XLINK_RETURN_DEBUG]', {
        fromView,
        targetHash: hashes.world,
        currentHashBefore,
        currentHashAfter: location.hash,
        scrollYAfter: window.scrollY,
        targetTop: target?.getBoundingClientRect?.().top,
        usedSmoothScroll: false,
        bodyEntered: body.classList.contains('entered'),
        visiblePanels: visibleXPanels(),
        scrollTargetExists: Boolean(target)
      });
      if (location.hash !== hashes.world) {
        console.warn('[XLINK_RETURN_WRONG_TARGET]', {
          fromView,
          currentHash: location.hash,
          scrollY: window.scrollY,
          reason: 'hash_not_world_after_return'
        });
      }
    };
    window.requestAnimationFrame(() => {
      jumpToTransmission();
      window.requestAnimationFrame(jumpToTransmission);
      window.setTimeout(() => {
        jumpToTransmission();
        ensureXDisclaimerAccepted();
        restoreScrollBehavior();
        window.__SHEX_RETURNING_TO_XLINK_HOME_UNTIL = 0;
      }, 180);
    });
  }

  window.SHEXReturnToXWorldHome = returnToXWorldHome;

  function closePage() {
    if (returnDatingChatSource()) return;
    returnToXWorldHome();
  }

  function showInitializationForm() {
    logXLinkShowStateDebug({
      step: 'show_identity_form_requested',
      caller: 'showInitializationForm',
      willShowIdentityForm: true,
      reason: 'first_setup'
    });
    if (isXLinkResourceLimitActive()) {
      window.SHEXLogXLinkAccessDebug?.('resource_limit_setup', false);
      warnXLinkEnterBlocked('resource_limit_setup', 'X链接资源限制开启，普通用户被拦截');
      redirectXLinkLimitToStudio();
      showXLinkResourceLimitNotice();
      return false;
    }
    if (!xCanUseFirstSetup()) {
      window.SHEXLogXLinkAccessDebug?.('first_setup_blocked', false, { dataStatus: xDataStatus() });
      warnXLinkEnterBlocked('first_setup_blocked', '登录状态或云端数据还没有准备好', { dataStatus: xDataStatus() });
      showXDataLoadingNotice();
      return false;
    }
    const meta = xCloudSnapshotMeta();
    const hasCurrentXLinkData = Boolean(meta.hasXIdentity || meta.hasXState);
    const hasLegacyOnlyXChat = Boolean(meta.hasLegacyXChat && !hasCurrentXLinkData);
    const localState = persistLegacyEmptyDreamState(readState());
    if (hasIntentionallyEmptyDreams(localState)) {
      clearXRestoreWaitingPanel();
      return renderEmptyDreamState('world');
    }
    if (meta.loaded && hasCurrentXLinkData) {
      logXLinkShowStateDebug({
        step: 'block_identity_form_cloud_data_exists',
        caller: 'showInitializationForm',
        willShowIdentityForm: false,
        reason: 'cloud_snapshot_has_data_without_local_state',
        snapshotMeta: meta
      });
      showXRestoreWaitingPanel('cloud_data_without_local_state');
      showChatToast('数据还没同步好，请重新登录一下');
      return false;
    }
    if (meta.loaded && hasLegacyOnlyXChat) {
      logXLinkShowStateDebug({
        step: 'legacy_chat_without_current_state',
        caller: 'showInitializationForm',
        willShowIdentityForm: true,
        reason: 'legacy_chat_key_only',
        snapshotMeta: meta
      });
      showChatToast('\u68c0\u6d4b\u5230\u65e7\u7248\u804a\u5929\u8bb0\u5f55\uff0c\u4e0d\u4f1a\u6e05\u7a7a\u6216\u8986\u76d6\u65e7\u6570\u636e');
    }
    window.SHEXLogXLinkAccessDebug?.('allow_setup', true, { dataStatus: xDataStatus() });
    setXLinkView('identity', 'show_initialization_form');
    clearXRestoreWaitingPanel();
    const taInput = $('#xTaName');
    const userInput = $('#xUserCode');
    const title = $('#xIdentityForm h3');
    const copy = $('#xIdentityForm .sub');
    const button = $('#xIdentityForm button[type="submit"]');
    if (title) title.textContent = '初始化 X链接';
    if (copy) copy.textContent = '请先填写你的名字和第一个梦角的名字。之后可以在 X传讯里继续添加梦角。';
    if (taInput) {
      taInput.value = '';
      taInput.closest('label')?.childNodes.forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE) node.nodeValue = '第一个梦角的名字';
      });
    }
    if (userInput) {
      userInput.value = '';
      userInput.closest('label')?.childNodes.forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE) node.nodeValue = '你的名字';
      });
    }
    if (button) button.textContent = '保存并进入 X链接';
    const panel = $('#xIdentityPanel');
    ensureXFirstEntryChoiceUi();
    panel?.classList.remove('x-first-entry-creating');
    panel?.classList.add('x-first-entry-choices-active');
    history.replaceState(null, '', '#transmission');
    logXLinkShowStateDebug({
      step: 'show_identity_form',
      caller: 'showInitializationForm',
      willShowIdentityForm: true,
      reason: 'confirmed_new_user'
    });
    window.requestAnimationFrame(() => panel?.scrollIntoView({ behavior: 'auto', block: 'center' }));
    return true;
  }

  function saveIdentityFromForm(event) {
    event.preventDefault();
    event.stopImmediatePropagation?.();
    logXLinkEnterDebug({ nextAction: 'validate_entry' });
    if (isXLinkResourceLimitActive()) {
      logXLinkEnterDebug({ blockedAt: 'resource_limit', nextAction: 'show_resource_limit_notice' });
      warnXLinkEnterBlocked('resource_limit', 'X链接资源限制开启，普通用户被拦截');
      redirectXLinkLimitToStudio();
      showXLinkResourceLimitNotice();
      return;
    }
    if (!xCanUseFirstSetup()) {
      logXLinkEnterDebug({ blockedAt: 'first_setup_blocked', nextAction: 'show_data_loading_notice' });
      warnXLinkEnterBlocked('first_setup_blocked', '登录状态或云端数据还没有准备好', { dataStatus: xDataStatus() });
      showXDataLoadingNotice();
      return;
    }
    const existing = readState();
    if (existing.dreams.length) {
      shexDebugLog('log', '[SAVE_GUARD_DEBUG]', {
        userId: currentXUser()?.userId || '',
        dataLoadStatus: xDataStatus(),
        restoringFromCloud: xRestoringFromCloud(),
        rawDataKeyCount: Object.keys(existing || {}).length,
        hasLocalXIdentity: Boolean(localStorage.getItem('shex_x_link_identity')),
        hasCloudXData: true,
        allowSave: false,
        blockedReason: 'existing_cloud_x_data'
      });
      logXLinkEnterDebug({ blockedAt: 'existing_data', nextAction: 'show_existing_data_notice' });
      warnXLinkEnterBlocked('existing_data', '已有梦角数据，阻止初始化覆盖', { dreamCount: existing.dreams.length });
      showChatToast('检测到云端已有数据，已暂停本次保存，请刷新或重新登录');
      ensureXHomeChrome();
      return;
    }
    if (!validateXDisclaimerBeforeSubmit()) {
      logXLinkEnterDebug({ blockedAt: 'disclaimer', nextAction: 'open_disclaimer' });
      warnXLinkEnterBlocked('disclaimer', '免责声明还没有确认');
      return;
    }
    const dreamName = $('#xTaName')?.value.trim();
    const userName = $('#xUserCode')?.value.trim();
    if (!dreamName || !userName) {
      logXLinkEnterDebug({ blockedAt: 'missing_signature', nextAction: 'show_missing_signature_notice' });
      warnXLinkEnterBlocked('missing_signature', '连接署名没有填写完整', { dreamName, userName });
      showChatToast('请填写你的名字和第一个梦角的名字');
      return;
    }
    const dreamId = createXId('dream');
    const saved = writeState({
      ...defaultMultiState(),
      userName,
      currentDreamId: dreamId,
      currentDreamChangedAt: Date.now(),
      migratedFromSingle: true,
      dreams: [{
        id: dreamId,
        name: dreamName,
        userNickname: userName,
        userCall: userName,
        avatar: '',
        backgroundPhotoId: '',
        albumDisplayPhotoId: '',
        worldAvatarCaption: '',
        createdAt: Date.now()
      }],
      singleChats: { [dreamId]: [] },
      letters: { [dreamId]: {} },
      replies: { [dreamId]: [] },
      companions: { [dreamId]: {} }
    });
    if (!saved) {
      logXLinkEnterDebug({ blockedAt: 'save_state_failed', nextAction: 'show_save_failed_notice' });
      warnXLinkEnterBlocked('save_state_failed', '连接资料没有保存成功');
      showChatToast('连接资料还没有保存好，请稍后再试');
      return;
    }
    logXLinkEnterDebug({ nextAction: 'show_message_list', blockedAt: '', allowXLink: true });
    ensureXHomeChrome();
    openPage('message');
    showChatToast('连接署名已保存，已进入 X传讯');
  }

  function ensureXReady({ allowEmptyWorld = false } = {}) {
    window.SHEXLogAdminCheckDebug?.('ensureXReady');
    logXLinkEntryChainDebug({ step: 'ensure_ready_start', nextAction: 'check_access' });
    if (isXLinkResourceLimitActive()) {
      logXLinkEntryChainDebug({ step: 'ensure_ready_blocked', blockedAt: 'resource_limit', nextAction: 'show_resource_limit_notice' });
      window.SHEXLogXLinkAccessDebug?.('resource_limit_ready', false);
      redirectXLinkLimitToStudio();
      showXLinkResourceLimitNotice();
      return false;
    }
    if (!xHasLoggedInUser()) {
      logXLinkEntryChainDebug({ step: 'ensure_ready_blocked', blockedAt: 'not_logged_in', nextAction: 'auth' });
      window.SHEXLogXLinkAccessDebug?.('not_logged_in_ready', false);
      window.location.href = './auth.html?login=1';
      return false;
    }
    if (xDataStatus() !== 'success') {
      const localState = ensureStateFromIdentity('ensure_ready_restore_failed_local_state');
      if (xDataStatus() === 'failed' && (localState.dreams.length || hasIntentionallyEmptyDreams(localState))) {
        ensureXHomeChrome();
        logXLinkEntryChainDebug({ step: 'ensure_ready_allow_local_after_restore_failed', nextAction: 'show_x_home', allowXLink: true, dreamCount: localState.dreams.length, intentionalEmpty: hasIntentionallyEmptyDreams(localState) });
        window.SHEXLogXLinkAccessDebug?.('allow_ready_local_after_restore_failed', true, { dreamCount: localState.dreams.length, intentionalEmpty: hasIntentionallyEmptyDreams(localState), dataStatus: xDataStatus() });
        return true;
      }
      logXLinkEntryChainDebug({
        step: 'ensure_ready_blocked',
        blockedAt: xDataStatus() === 'failed' ? 'data_failed' : 'data_not_ready',
        nextAction: 'show_restore_waiting'
      });
      window.SHEXLogXLinkAccessDebug?.('data_not_ready', false, { dataStatus: xDataStatus() });
      showXDataLoadingNotice();
      showChatToast(xDataStatus() === 'failed' ? '数据还没同步好，请重新登录一下' : 'X链接数据还在恢复，请稍等几秒后再点一次');
      return false;
    }
    const state = persistLegacyEmptyDreamState(ensureStateFromIdentity('ensure_ready_repair_from_identity'));
    if (state.dreams.length || hasIntentionallyEmptyDreams(state)) {
      ensureXHomeChrome();
      logXLinkEntryChainDebug({ step: 'ensure_ready_allow', nextAction: 'show_x_home', allowXLink: true, dreamCount: state.dreams.length });
      window.SHEXLogXLinkAccessDebug?.('allow_ready_existing_data', true, { dreamCount: state.dreams.length, dataStatus: xDataStatus() });
      return true;
    }
    if (!xCanUseFirstSetup()) {
      logXLinkEntryChainDebug({ step: 'ensure_ready_blocked', blockedAt: 'first_setup_denied', nextAction: 'show_restore_waiting' });
      window.SHEXLogXLinkAccessDebug?.('first_setup_denied', false, { dataStatus: xDataStatus() });
      showXDataLoadingNotice();
      return false;
    }
    if (allowEmptyWorld) {
      ensureXHomeChrome();
      logXLinkEntryChainDebug({ step: 'ensure_ready_new_user_gallery', nextAction: 'show_requested_page', allowXLink: true });
      return true;
    }
    logXLinkEntryChainDebug({ step: 'ensure_ready_new_user_setup', nextAction: 'show_first_entry_choices' });
    showInitializationForm();
    return false;
  }

  const _avatarUrlCache = new Map();
  const CLOUD_IMAGE_EMPTY_SRC = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==';
  const CLOUD_IMAGE_LOAD_TIMEOUT_MS = 15000;
  let _cloudImageRequestSequence = 0;

  function cloudFileErrorDetail(error) {
    if (!error) return '';
    if (typeof error === 'string') return error;
    return error.detail || error.message || error.code || String(error);
  }

  function makeCloudFileUrlError(code, message, extra = {}) {
    const error = new Error(message || code || 'CloudBase 临时链接获取失败');
    error.code = code || 'CLOUD_FILE_URL_FAILED';
    Object.assign(error, extra);
    return error;
  }

  function cloudFileIdLogToken(fileID) {
    const value = String(fileID || '');
    let hash = 2166136261;
    for (let index = 0; index < value.length; index += 1) {
      hash ^= value.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return `${value.length}:${(hash >>> 0).toString(16).padStart(8, '0')}`;
  }

  function cloudFileLookupDetails(file = null, error = null) {
    return {
      status: String(file?.status ?? file?.state ?? error?.status ?? '').slice(0, 80),
      code: String(file?.errcode ?? file?.errCode ?? file?.code ?? error?.errcode ?? error?.errCode ?? error?.code ?? '').slice(0, 80),
      message: String(file?.errmsg ?? file?.errMsg ?? file?.message ?? error?.errmsg ?? error?.errMsg ?? error?.message ?? '')
        .replace(/[\r\n]+/g, ' ').slice(0, 240)
    };
  }

  function classifyCloudFileLookup(file = null, error = null) {
    const details = cloudFileLookupDetails(file, error);
    const signal = `${details.status} ${details.code} ${details.message}`.toLowerCase();
    if (/(?:permission|forbidden|unauthori[sz]ed|access.denied|auth|401|403)/i.test(signal)) {
      return { code: 'CLOUD_FILE_FORBIDDEN', message: '没有权限读取这个文件，请重新登录或联系管理员', permanent: true };
    }
    if (/(?:not.?found|no.?such|non.?exist|file.?missing|404)/i.test(signal)) {
      return { code: 'CLOUD_FILE_NOT_FOUND', message: '没有找到这个文件，请重新上传', permanent: true };
    }
    if (/(?:invalid|malformed|bad.?request|400)/i.test(signal)) {
      return { code: 'INVALID_FILE_ID', message: '文件标识无效，请重新上传', permanent: true };
    }
    if (/(?:timeout|timed.?out|etimedout|econnreset|eai_again|enetunreach|socket.?hang|network|429|too.?many|5\d\d)/i.test(signal)) {
      return { code: 'CLOUD_FILE_TEMP_URL_TRANSIENT', message: '文件访问服务暂时繁忙，请稍后重试', permanent: false };
    }
    return { code: 'CLOUD_FILE_TEMP_URL_UNAVAILABLE', message: 'CloudBase 没有返回可用的文件链接，请重新上传或联系管理员核查', permanent: true };
  }

  function logCloudImageLoadFailure(fileID, error, stage = 'final') {
    const detail = cloudFileErrorDetail(error);
    console.error('[SHEX_CLOUD_IMAGE_LOAD_FAILED]', {
      stage,
      fileIdToken: cloudFileIdLogToken(fileID),
      code: error?.code || '',
      step: error?.step || '',
      detail,
      authCode: error?.authError?.code || error?.authCode || '',
      authStep: error?.authError?.step || error?.authStep || '',
      authDetail: cloudFileErrorDetail(error?.authError) || error?.authDetail || '',
      errorName: String(error?.name || 'Error')
    });
  }

  function clearCloudImageRetryPlaceholder(imgEl) {
    const role = imgEl?.matches?.('.ix-avatar, .x-thread-row > .x-dream-avatar') ? 'avatar' : 'media';
    const placeholder = Array.from(imgEl?.parentElement?.children || []).find((item) => (
      item?.classList?.contains?.('x-cloud-image-retry')
      && String(item?.dataset?.cloudImageRole || 'media') === role
    ));
    if (placeholder && placeholder.dataset.cloudFileId === String(imgEl?.dataset?.cloudRetryFileId || '')) {
      placeholder.remove();
    }
    if (!imgEl?.parentElement?.querySelector?.('.x-cloud-image-retry')) {
      imgEl?.parentElement?.classList?.remove('x-cloud-image-retry-host');
    }
    if (imgEl?.dataset) delete imgEl.dataset.cloudRetryFileId;
  }

  function showCloudImageRetryPlaceholder(imgEl, fileID, error, options = {}) {
    const cloudFileID = String(fileID || '').trim();
    if (!imgEl || !imgEl.isConnected || !cloudFileID) return;
    if (imgEl.dataset?.cloudFileId && imgEl.dataset.cloudFileId !== cloudFileID) return;
    const parent = imgEl.parentElement;
    if (!parent) return;
    const role = imgEl.matches?.('.ix-avatar, .x-thread-row > .x-dream-avatar') ? 'avatar' : 'media';
    imgEl.src = CLOUD_IMAGE_EMPTY_SRC;
    imgEl.classList.remove('x-cloud-image-loading', 'x-cloud-image-loaded', 'is-loaded');
    imgEl.classList.add('x-cloud-image-error', 'is-load-error');
    imgEl.removeAttribute('aria-busy');
    imgEl.dataset.cloudRetryFileId = cloudFileID;
    parent.classList.add('x-cloud-image-retry-host');
    let placeholder = Array.from(parent.children || []).find((item) => (
      item?.classList?.contains?.('x-cloud-image-retry')
      && String(item?.dataset?.cloudImageRole || 'media') === role
    ));
    if (!placeholder || placeholder.dataset.cloudFileId !== cloudFileID) {
      placeholder?.remove();
      placeholder = document.createElement('span');
      placeholder.className = `x-cloud-image-retry${role === 'avatar' ? ' is-avatar-retry' : ''}`;
      placeholder.setAttribute('role', 'button');
      placeholder.setAttribute('tabindex', '0');
      placeholder.setAttribute('aria-label', '图片加载失败，点击重试');
      placeholder.dataset.cloudFileId = cloudFileID;
      placeholder.dataset.cloudImageRole = role;
      placeholder.innerHTML = role === 'avatar'
        ? '<span aria-hidden="true">↻</span>'
        : '<strong>加载失败</strong><small>点击重试</small>';
      const retry = (event) => {
        event?.preventDefault?.();
        event?.stopPropagation?.();
        placeholder.classList.add('is-retrying');
        placeholder.innerHTML = role === 'avatar'
          ? '<span aria-hidden="true">…</span>'
          : '<strong>正在重试</strong><small>请稍候</small>';
        void loadCloudImageElement(imgEl, cloudFileID, options);
      };
      placeholder.addEventListener('click', retry);
      placeholder.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' || event.key === ' ') retry(event);
      });
      parent.appendChild(placeholder);
    }
    placeholder.title = cloudFileErrorDetail(error) || '图片加载失败，点击重试';
  }

  function invalidateCloudFileUrlCache(fileID, options = {}, failedUrl = '') {
    const cloudFileID = String(fileID || '').trim();
    const rejectedUrl = String(failedUrl || '').trim();
    if (!cloudFileID) return false;
    let invalidated = false;
    const invalidate = (cache) => {
      if (!cache?.get || !cache?.delete) return;
      const current = cache.get(cloudFileID);
      if (current === undefined) return;
      if (rejectedUrl && String(current || '') !== rejectedUrl) return;
      cache.delete(cloudFileID);
      if (cache === _cloudFileUrlCache) _cloudFileUrlCachedAt.delete(cloudFileID);
      invalidated = true;
    };
    invalidate(options.cache);
    if (options.cache !== _cloudFileUrlCache) invalidate(_cloudFileUrlCache);
    return invalidated;
  }

  function loadCloudImageElement(imgEl, fileID, options = {}) {
    const cloudFileID = String(fileID || '').trim();
    if (!imgEl || !cloudFileID) return Promise.resolve(false);
    const requestToken = `${cloudFileID}:${Date.now()}:${++_cloudImageRequestSequence}`;
    const ownerRow = imgEl.closest?.('[data-thread-type][data-thread-id]');
    const requestOwnerToken = ownerRow
      ? `${String(ownerRow.dataset.threadType || '')}:${String(ownerRow.dataset.threadId || '')}`
      : '';
    imgEl.dataset.cloudFileId = cloudFileID;
    imgEl.dataset.cloudImageRequestToken = requestToken;
    // 聊天 reconciliation 会先在离屏节点中创建头像，再于同一任务内把节点
    // 放回真实聊天。离屏只代表“尚未挂载”，不能被当成缓存损坏并删除 IndexedDB。
    const isCurrentRequest = () => Boolean(
      imgEl.dataset?.cloudFileId === cloudFileID
      && imgEl.dataset?.cloudImageRequestToken === requestToken
      && (!requestOwnerToken || (() => {
        const currentOwner = imgEl.closest?.('[data-thread-type][data-thread-id]');
        return currentOwner
          && `${String(currentOwner.dataset.threadType || '')}:${String(currentOwner.dataset.threadId || '')}` === requestOwnerToken;
      })())
    );
    const mediaScope = options.publicCharacterInstanceId ? publicCharacterMediaScope() : cloudMediaCacheScope();
    const applyResolvedUrl = (url) => new Promise((resolve) => {
      if (!url || !isCurrentRequest()) {
        resolve(false);
        return;
      }
      let settled = false;
      let timeoutId = null;
      const finish = (loaded) => {
        if (settled) return;
        settled = true;
        if (timeoutId !== null) window.clearTimeout(timeoutId);
        imgEl.onload = null;
        imgEl.onerror = null;
        if (!isCurrentRequest()) {
          resolve(false);
          return;
        }
        imgEl.classList.remove('x-cloud-image-loading');
        imgEl.classList.toggle('x-cloud-image-loaded', loaded);
        imgEl.classList.toggle('x-cloud-image-error', !loaded);
        imgEl.classList.toggle('is-loaded', loaded);
        imgEl.classList.toggle('is-load-error', !loaded);
        imgEl.removeAttribute('aria-busy');
        resolve(loaded);
      };
      imgEl.onload = () => finish(Number(imgEl.naturalWidth || 0) > 0);
      imgEl.onerror = () => finish(false);
      timeoutId = window.setTimeout(() => finish(false), CLOUD_IMAGE_LOAD_TIMEOUT_MS);
      if (String(imgEl.getAttribute('src') || '') === String(url)) {
        if (imgEl.complete) finish(Number(imgEl.naturalWidth || 0) > 0);
        return;
      }
      imgEl.src = url;
    });
    const cachedUrl = window.SHEXMediaCache?.peek?.(cloudFileID, mediaScope)
      || options.cache?.get?.(cloudFileID)
      || '';
    if (cachedUrl) {
      clearCloudImageRetryPlaceholder(imgEl);
      imgEl.classList.remove('x-cloud-image-loading', 'x-cloud-image-error', 'is-load-error');
      imgEl.classList.add('x-cloud-image-loading');
      imgEl.setAttribute('aria-busy', 'true');
      return applyResolvedUrl(cachedUrl).then(async (loaded) => {
        if (loaded) {
          clearCloudImageRetryPlaceholder(imgEl);
          return true;
        }
        if (!isCurrentRequest()) return false;
        invalidateCloudFileUrlCache(cloudFileID, options, cachedUrl);
        imgEl.src = CLOUD_IMAGE_EMPTY_SRC;
        await window.SHEXMediaCache?.remove?.(cloudFileID, mediaScope);
        if (!isCurrentRequest()) return false;
        imgEl.classList.remove('x-cloud-image-loaded', 'is-loaded');
        imgEl.classList.add('x-cloud-image-loading');
        return loadCloudImageElement(imgEl, cloudFileID, { ...options, bypassPersistentCache: true });
      });
    }
    clearCloudImageRetryPlaceholder(imgEl);
    imgEl.classList.remove('x-cloud-image-loaded', 'x-cloud-image-error', 'is-load-error');
    imgEl.classList.add('x-cloud-image-loading');
    imgEl.setAttribute('aria-busy', 'true');
    const attempt = async (stage = 'initial') => {
      const url = options.publicCharacterInstanceId
        ? await resolvePublicCharacterMediaUrl(cloudFileID, options.publicCharacterInstanceId, { forceRefresh: stage !== 'initial' })
        : await resolveCloudImageUrl(cloudFileID, {
          forceRefresh: stage !== 'initial',
          bypassPersistentCache: Boolean(options.bypassPersistentCache) || stage !== 'initial'
        });
      if (url && options.cache?.set && !/^blob:/i.test(url)) options.cache.set(cloudFileID, url);
      const loaded = await applyResolvedUrl(url);
      if (!isCurrentRequest()) return false;
      if (!loaded) {
        invalidateCloudFileUrlCache(cloudFileID, options, url);
        await window.SHEXMediaCache?.remove?.(cloudFileID, mediaScope);
        throw makeCloudFileUrlError('IMAGE_DECODE_FAILED', '图片临时链接已返回，但浏览器加载失败', { fileID: cloudFileID, stage });
      }
      clearCloudImageRetryPlaceholder(imgEl);
      return true;
    };
    return attempt('initial').catch((firstError) => new Promise((resolve) => {
      const retryDelay = Number(options.retryDelayMs || 1200);
      window.setTimeout(() => {
        attempt('auto_retry').then(resolve).catch((finalError) => {
          finalError.firstError = firstError;
          logCloudImageLoadFailure(cloudFileID, finalError, 'auto_retry_failed');
          showCloudImageRetryPlaceholder(imgEl, cloudFileID, finalError, options);
          resolve(false);
        });
      }, Math.max(0, retryDelay));
    }).catch((finalError) => {
      finalError.firstError = firstError;
      logCloudImageLoadFailure(cloudFileID, finalError, 'retry_handler_failed');
      showCloudImageRetryPlaceholder(imgEl, cloudFileID, finalError, options);
      return false;
    }));
  }

  window.SHEXCloudImages = {
    resolve: resolveCloudImageUrl,
    load: loadCloudImageElement
  };

  function retryVisibleFailedCloudImages() {
    document.querySelectorAll('img.x-cloud-image-error[data-cloud-file-id]').forEach((imgEl) => {
      const cloudFileID = String(imgEl.dataset?.cloudFileId || '').trim();
      if (!cloudFileID || !imgEl.isConnected || imgEl.offsetParent === null) return;
      void loadCloudImageElement(imgEl, cloudFileID, imgEl.dataset.publicCharacterInstanceId
        ? { publicCharacterInstanceId: imgEl.dataset.publicCharacterInstanceId }
        : {});
    });
  }

  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) retryVisibleFailedCloudImages();
  });

  function setCloudBackgroundLoading(targets, loading, token = '') {
    (Array.isArray(targets) ? targets : [targets]).filter(Boolean).forEach((target) => {
      if (!loading && token && target.dataset.xCloudBackgroundLoadingToken !== token) return;
      target.classList.toggle('x-cloud-background-loading', Boolean(loading));
      if (loading) {
        if (token) target.dataset.xCloudBackgroundLoadingToken = token;
        target.setAttribute('aria-busy', 'true');
      } else {
        delete target.dataset.xCloudBackgroundLoadingToken;
        target.removeAttribute('aria-busy');
      }
    });
  }

  function publicCharacterAvatarInstanceId(dream, src) {
    const sourceAvatar = String(dream?.templateMetadata?.avatarAssetId || '').trim();
    return dream?.origin === 'template_derived' && sourceAvatar && sourceAvatar === String(src || '').trim()
      ? String(dream.characterInstanceId || dream.id || '').trim()
      : '';
  }

  function setAvatarImgSrc(imgEl, src, dream = null) {
    if (!imgEl || !src) return;
    if (/^cloud:\/\//i.test(src)) {
      const instanceId = dream
        ? publicCharacterAvatarInstanceId(dream, src)
        : String(imgEl.dataset?.publicCharacterInstanceId || '').trim();
      if (instanceId) imgEl.dataset.publicCharacterInstanceId = instanceId;
      else delete imgEl.dataset.publicCharacterInstanceId;
      void loadCloudImageElement(imgEl, src, instanceId
        ? { publicCharacterInstanceId: instanceId }
        : { cache: _avatarUrlCache });
    } else {
      imgEl.src = src;
    }
  }

  function dreamAvatarMarkup(dream = {}, className = 'x-dream-avatar', editKind = '') {
    const safeName = safeStringValue(dream?.name, '').trim() || '梦';
    const safeAvatar = safeStringValue(dream?.avatar, '').trim();
    const editAttributes = editKind ? ` data-world-avatar-pick="${editKind}" role="button" tabindex="0" aria-label="点击修改当前梦角头像"` : '';
    if (!safeAvatar) return `<span class="${className}"${editAttributes}>${escapeHtml(safeName.slice(0, 1))}</span>`;
    const isCloud = /^cloud:\/\//i.test(safeAvatar);
    const escapedAvatar = escapeHtml(safeAvatar);
    const publicInstanceId = isCloud ? publicCharacterAvatarInstanceId(dream, safeAvatar) : '';
    const srcAttribute = isCloud ? '' : ` src="${escapedAvatar}"`;
    return `<img class="${className}${isCloud ? ' x-cloud-image-loading' : ''}"${srcAttribute} data-avatar-cloud-src="${isCloud ? escapedAvatar : ''}"${publicInstanceId ? ` data-public-character-instance-id="${escapeHtml(publicInstanceId)}"` : ''} alt="${escapeHtml(safeName)}头像"${editAttributes}${isCloud ? ' aria-busy="true"' : ''}>`;
  }

  function resolveDreamAvatarImages(root = document) {
    (root.querySelectorAll ? root.querySelectorAll('img[data-avatar-cloud-src]') : []).forEach((img) => {
      const cloudSrc = img.dataset.avatarCloudSrc;
      if (cloudSrc) setAvatarImgSrc(img, cloudSrc);
    });
  }

  function xWorldAvatarSourceMarkup(source = '', label = '', className = '', editKind = '') {
    const safeLabel = String(label || '我').trim() || '我';
    const editAttributes = editKind ? ` data-world-avatar-pick="${editKind}" role="button" tabindex="0" aria-label="点击修改我在当前梦角关系中的头像"` : '';
    if (!source) return `<span class="${className}"${editAttributes}>${escapeHtml(safeLabel.slice(0, 1))}</span>`;
    const isCloud = /^cloud:\/\//i.test(source);
    return `<img class="${className}${isCloud ? ' x-cloud-image-loading' : ''}" src="${isCloud ? '' : escapeHtml(source)}" data-avatar-cloud-src="${isCloud ? escapeHtml(source) : ''}" alt="${escapeHtml(safeLabel)}头像"${editAttributes}${isCloud ? ' aria-busy="true"' : ''}>`;
  }

  function xWorldAvatarDisplayMarkup(state, dream, variant = 'hero', editable = false) {
    if(dream?.__officialStageVisual)state={...state,userAvatar:dream.__officialStageVisual.userAvatar};
    const display = normalizeXWorldAvatarDisplay(dream?.worldAvatarDisplay);
    const itemClass = variant === 'settings'
      ? 'x-settings-avatar x-world-avatar-display-image'
      : variant === 'page'
        ? 'x-avatar-display-preview-avatar x-world-avatar-display-image'
        : 'x-world-hero-avatar x-world-avatar-display-image';
    const rootClass = `x-world-avatar-display x-world-avatar-display-${variant} is-${display.shape} is-${display.mode} order-${display.order}`;
    const userPositionClass = display.order === 'user-first' ? 'is-left-avatar' : 'is-right-avatar';
    const dreamPositionClass = display.order === 'user-first' ? 'is-right-avatar' : 'is-left-avatar';
    const dreamMarkup = dream
      ? dreamAvatarMarkup(dream, `${itemClass} is-dream-avatar ${dreamPositionClass}`, editable ? 'dream' : '')
      : `<span class="${itemClass} is-dream-avatar ${dreamPositionClass}">梦</span>`;
    const userMarkup = xWorldAvatarSourceMarkup(
      resolveSingleChatUserAvatar(dream, state),
      state?.userName || '我',
      `${itemClass} is-user-avatar ${userPositionClass}`,
      editable && dream && display.mode === 'double' ? 'user' : ''
    );
    return `
      <span class="${rootClass}" data-avatar-shape="${display.shape}" data-avatar-mode="${display.mode}" aria-label="${display.mode === 'double' ? '用户与当前梦角头像' : '当前梦角头像'}">
        ${display.mode === 'double' ? userMarkup : ''}
        ${dreamMarkup}
      </span>
    `;
  }

  let xCallMicOn = true;
  let xCallTimer = null;
  let xCallResolved = false;
  let xCallStartTime = 0;
  let xCallIntervalTimer = null;
  let xCallHangupCheckTimer = null;
  let xCallConfirmTimer = null;
  let xCallConfirmPending = false;
  let xCallRingtoneAudio = null;
  let xCallDreamId = '';
  let xCallOwnerId = '';
  function reportCallOverlayDiagnostic(stage, error, dream, direction = 'incoming', extra = {}) {
    const detail = String(error?.stack || error?.message || error || 'unknown_error').slice(0, 1800);
    const safeDirection = direction === 'incoming' ? 'incoming' : 'outgoing';
    const payload = {
      kind: 'call_overlay_diagnostic',
      stage: String(stage || 'unknown'),
      direction: safeDirection,
      dreamId: safeStringValue(dream?.id, ''),
      dreamName: safeStringValue(dream?.name, ''),
      detail,
      userAgent: navigator.userAgent || '',
      page: location.href,
      ...extra
    };
    console.error('[SHEX_CALL_OVERLAY_ERROR]', payload);
  }

  function safelyPlayCallAudio(audio, stage, dream, direction) {
    try {
      const playback = audio?.play?.();
      // Older embedded browsers may return undefined rather than a Promise.
      if (playback && typeof playback.catch === 'function') {
        playback.catch((error) => reportCallOverlayDiagnostic(stage, error, dream, direction));
      }
      return true;
    } catch (error) {
      reportCallOverlayDiagnostic(stage, error, dream, direction);
      return false;
    }
  }

  function playCallRingtone(dream, direction = 'incoming') {
    try {
      stopCallRingtone();
      xCallRingtoneAudio = new Audio('./audio/call-ringtone.mp3');
      xCallRingtoneAudio.loop = true;
      xCallRingtoneAudio.volume = 0.7;
      return safelyPlayCallAudio(xCallRingtoneAudio, 'ringtone_play', dream, direction);
    } catch (error) {
      reportCallOverlayDiagnostic('ringtone_setup', error, dream, direction);
      return false;
    }
  }

  function stopCallRingtone() {
    if (xCallRingtoneAudio) {
      xCallRingtoneAudio.pause();
      xCallRingtoneAudio.currentTime = 0;
      xCallRingtoneAudio = null;
    }
  }

  function playCallSound(name, dream, direction = 'incoming') {
    try {
      const audio = new Audio(`./audio/${name}`);
      audio.volume = 0.8;
      safelyPlayCallAudio(audio, `sound_play:${name}`, dream, direction);
    } catch (error) {
      reportCallOverlayDiagnostic(`sound_setup:${name}`, error, dream, direction);
    }
  }

  function normalizeCallDreamData(dream) {
    return {
      ...(dream && typeof dream === 'object' ? dream : {}),
      id: safeStringValue(dream?.id, '').trim(),
      name: safeStringValue(dream?.name, '').trim() || '梦',
      avatar: safeStringValue(dream?.avatar, '').trim()
    };
  }

  function ensureCallOverlayNode() {
    if (window.SHEXCallOverlayView) return window.SHEXCallOverlayView.ensure();
    let overlay = document.querySelector('#xCallOverlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'xCallOverlay';
      overlay.className = 'x-call-overlay';
      document.body.appendChild(overlay);
    }
    overlay.style.zIndex = '2147483647';
    return overlay;
  }

  function renderCallOverlayFallback(overlay, direction, error, dream) {
    const callDirection = direction === 'incoming' ? 'incoming' : 'outgoing';
    reportCallOverlayDiagnostic('overlay_fallback', error, dream, callDirection);
    if (xCallTimer) window.clearTimeout(xCallTimer);
    xCallTimer = null;
    xCallResolved = true;
    stopCallRingtone();
    const fallbackOverlay = overlay || ensureCallOverlayNode();
    fallbackOverlay.id = 'xCallOverlay';
    fallbackOverlay.className = 'x-call-overlay';
    if (!fallbackOverlay.isConnected) document.body.appendChild(fallbackOverlay);
    fallbackOverlay.innerHTML = `
      <div class="x-call-modal">
        <span class="x-call-avatar-fallback">梦</span>
        <p class="x-call-status">通话界面加载异常，请关闭后重试</p>
        <div class="x-call-actions">
          <button class="x-call-action x-call-action-cancel x-call-fallback-close" type="button">
            <span class="x-call-action-icon">✕</span>
            <span class="x-call-action-label">关闭</span>
          </button>
        </div>
      </div>
    `;
    fallbackOverlay.querySelector('.x-call-fallback-close')?.addEventListener('click', () => {
      stopCallRingtone();
      closeCallOverlay();
    });
    showCallOverlaySafely(fallbackOverlay, dream, callDirection);
  }

  function openCallOverlay(dream, aiCallInteraction = null) {
    let overlay = null;
    try {
      const safeDream = normalizeCallDreamData(dream);
      const callOwnerId = String(currentXUser()?.userId || '');
      overlay = ensureCallOverlayNode();
      xCallMicOn = true;
      xCallResolved = false;
      if (xCallTimer) window.clearTimeout(xCallTimer);
      xCallTimer = null;
      const avatarHtml = safeDream.avatar
        ? dreamAvatarMarkup(safeDream, 'x-call-avatar')
        : `<span class="x-call-avatar-fallback">${escapeHtml(safeDream.name.slice(0, 1))}</span>`;
      overlay.innerHTML = `
      <div class="x-call-modal">
        ${avatarHtml}
        <p class="x-call-status">等待对方接受邀请</p>
        <div class="x-call-actions">
          <button class="x-call-action x-call-action-mic" type="button">
            <span class="x-call-action-icon" id="xCallMicIcon">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
                <rect x="9" y="2" width="6" height="12" rx="3"></rect>
                <path d="M5 10v1a7 7 0 0 0 14 0v-1"></path>
                <line x1="12" y1="18" x2="12" y2="22"></line>
                <line x1="8" y1="22" x2="16" y2="22"></line>
              </svg>
              <span class="x-call-mic-slash" id="xCallMicSlash"></span>
            </span>
            <span class="x-call-action-label" id="xCallMicLabel">麦克风已开</span>
          </button>
          <button class="x-call-action x-call-action-cancel" type="button">
            <span class="x-call-action-icon">✕</span>
            <span class="x-call-action-label">取消</span>
          </button>
        </div>
      </div>
    `;
      resolveDreamAvatarImages(overlay);
      overlay.querySelector('.x-call-action-mic')?.addEventListener('click', () => {
        xCallMicOn = !xCallMicOn;
        const label = overlay.querySelector('#xCallMicLabel');
        const icon = overlay.querySelector('#xCallMicIcon');
        if (label) label.textContent = xCallMicOn ? '麦克风已开' : '麦克风已关闭';
        if (icon) icon.classList.toggle('is-muted', !xCallMicOn);
      });
      overlay.querySelector('.x-call-action-cancel')?.addEventListener('click', () => {
        if (xCallResolved) return;
        xCallResolved = true;
        if (xCallTimer) window.clearTimeout(xCallTimer);
        xCallTimer = null;
        stopCallRingtone();
        closeCallOverlay();
        if (String(currentXUser()?.userId || '') !== callOwnerId) return;
        if (!dreamById(safeDream.id)) return;
        playCallSound('call-end.mp3', safeDream, 'outgoing');
        const cancelledMessage = {
          type: 'notice',
          noticeKind: 'call',
          text: '你取消了呼叫',
          ...(aiCallInteraction ? {
            sourceMode: 'ai',
            interactionType: 'call',
            interactionData: { event: 'cancelled', initiatedMessageId: aiCallInteraction.initiatedMessageId || '' }
          } : {})
        };
        if (aiCallInteraction?.conversationKey) addMessageToConversation(aiCallInteraction.conversationKey, cancelledMessage);
        else addMessageToDream(safeDream.id, cancelledMessage);
      });
      const judgeDelay = Math.floor(Math.random() * 30000);
      xCallTimer = window.setTimeout(() => {
        if (xCallResolved) return;
        xCallResolved = true;
        xCallTimer = null;
        stopCallRingtone();
        if (String(currentXUser()?.userId || '') !== callOwnerId) { closeCallOverlay(); return; }
        if (!dreamById(safeDream.id)) { closeCallOverlay(); return; }
        const accepted = Math.random() < 0.8;
        closeCallOverlay();
        const resultText = accepted ? '通话已接通' : '对方拒接了你的电话';
        const resultEvent = accepted ? 'accepted' : 'rejected';
        const resultMessage = {
          type: 'notice',
          noticeKind: 'call',
          text: resultText,
          ...(aiCallInteraction ? {
            sourceMode: 'ai',
            interactionType: 'call',
            interactionData: {
              event: resultEvent,
              result: resultEvent,
              initiatedMessageId: aiCallInteraction.initiatedMessageId || ''
            }
          } : {})
        };
        const sentResult = aiCallInteraction?.conversationKey
          ? addMessageToConversation(aiCallInteraction.conversationKey, resultMessage)
          : addMessageToDream(safeDream.id, resultMessage);
        if (aiCallInteraction && !aiCallInteraction.aiTaskCreated && sentResult && !sentResult.localSaveFailed) {
          aiCallInteraction.aiTaskCreated = true;
          startCharacterAIInteractionReply({
            sent: sentResult,
            conversationKeyValue: aiCallInteraction.conversationKey,
            dreamId: aiCallInteraction.dreamId,
            eventText: characterAIInteractionPrompt('call', { result: resultEvent }),
            interactionType: 'call',
            chatMode: aiCallInteraction.chatMode
          });
        }
        if (accepted) {
          playCallSound('call-connect.mp3', safeDream, 'outgoing');
          startCallWidget(safeDream.id);
        } else {
          playCallSound('call-end.mp3', safeDream, 'outgoing');
        }
      }, judgeDelay);
      if (showCallOverlaySafely(overlay, safeDream, 'outgoing')) playCallRingtone(safeDream, 'outgoing');
    } catch (error) {
      renderCallOverlayFallback(overlay, 'outgoing', error, dream);
    }
  }

  function closeCallOverlay() {
    const overlay = document.querySelector('#xCallOverlay');
    if (!overlay) return;
    stopCallRingtone();
    if (window.SHEXCallOverlayView) window.SHEXCallOverlayView.dismiss(overlay);
    else overlay.classList.remove('show');
    window.setTimeout(() => overlay.remove(), 220);
  }

  function callAvatarFallbackMarkup(dream) {
    return `<span class="x-call-avatar-fallback">${escapeHtml(safeStringValue(dream?.name, '梦').slice(0, 1) || '梦')}</span>`;
  }

  function renderCallAvatarSafely(overlay, dream, direction) {
    const slot = overlay?.querySelector?.('[data-call-avatar-slot]');
    if (!slot) return;
    try {
      slot.innerHTML = dream?.avatar
        ? dreamAvatarMarkup(dream, 'x-call-avatar')
        : callAvatarFallbackMarkup(dream);
      try {
        resolveDreamAvatarImages(slot);
      } catch (error) {
        reportCallOverlayDiagnostic('avatar_resolve', error, dream, direction);
      }
    } catch (error) {
      // The fallback avatar was rendered with the buttons, so an avatar error
      // never replaces the incoming-call controls.
      slot.innerHTML = callAvatarFallbackMarkup(dream);
      reportCallOverlayDiagnostic('avatar_render', error, dream, direction);
    }
  }

  function showCallOverlaySafely(overlay, dream, direction) {
    try {
      if (window.SHEXCallOverlayView) {
        const visible = window.SHEXCallOverlayView.present(overlay);
        if (!visible) {
          xCallResolved = true;
          if (xCallTimer) window.clearTimeout(xCallTimer);
          xCallTimer = null;
          stopCallRingtone();
          reportCallOverlayDiagnostic('overlay_not_visible', new Error('call_controls_not_visible'), dream, direction);
          if (typeof showChatToast === 'function') showChatToast('通话界面暂未显示，请稍后重试');
        }
        return visible;
      }
      overlay.classList.add('show');
      return Boolean(overlay.isConnected && overlay.getBoundingClientRect().width > 0);
    } catch (error) {
      reportCallOverlayDiagnostic('overlay_show', error, dream, direction);
      return false;
    }
  }

  function openIncomingCallOverlay(dream) {
    let overlay = null;
    try {
      const safeDream = normalizeCallDreamData(dream);
      const callOwnerId = String(currentXUser()?.userId || '');
      overlay = ensureCallOverlayNode();
      xCallResolved = false;
      // Render the controls first. Avatar resolving and ringtone playback are
      // intentionally separate best-effort steps below.
      overlay.innerHTML = `
      <div class="x-call-modal">
        <span data-call-avatar-slot>${callAvatarFallbackMarkup(safeDream)}</span>
        <p class="x-call-status">${escapeHtml(safeDream.name || 'TA')} 邀请你通话</p>
        <div class="x-call-actions">
          <button class="x-call-action x-call-action-cancel x-call-action-decline" type="button">
            <span class="x-call-action-icon">✕</span>
            <span class="x-call-action-label">拒接</span>
          </button>
          <button class="x-call-action x-call-action-accept" type="button">
            <span class="x-call-action-icon" style="background:#4caf7d;">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor">
                <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z"></path>
              </svg>
            </span>
            <span class="x-call-action-label">接听</span>
          </button>
        </div>
      </div>
    `;
      const declineButton = overlay.querySelector('.x-call-action-decline');
      const acceptButton = overlay.querySelector('.x-call-action-accept');
      if (!declineButton || !acceptButton) {
        throw new Error('incoming_call_controls_missing');
      }
      declineButton.addEventListener('click', () => {
        if (xCallResolved) return;
        xCallResolved = true;
        stopCallRingtone();
        closeCallOverlay();
        if (String(currentXUser()?.userId || '') !== callOwnerId) return;
        if (!dreamById(safeDream.id)) return;
        playCallSound('call-end.mp3', safeDream, 'incoming');
        addMessageToDream(safeDream.id, { type: 'notice', noticeKind: 'call', text: '你拒接了对方的来电' });
      });
      acceptButton.addEventListener('click', () => {
        if (xCallResolved) return;
        xCallResolved = true;
        stopCallRingtone();
        closeCallOverlay();
        if (String(currentXUser()?.userId || '') !== callOwnerId) return;
        if (!dreamById(safeDream.id)) return;
        playCallSound('call-connect.mp3', safeDream, 'incoming');
        addMessageToDream(safeDream.id, { type: 'notice', noticeKind: 'call', text: '通话已接通' });
        startCallWidget(safeDream.id);
      });
      // These steps must not be able to fall into renderCallOverlayFallback.
      renderCallAvatarSafely(overlay, safeDream, 'incoming');
      if (showCallOverlaySafely(overlay, safeDream, 'incoming')) playCallRingtone(safeDream, 'incoming');
    } catch (error) {
      renderCallOverlayFallback(overlay, 'incoming', error, dream);
    }
  }

  function formatCallDuration(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  }

  function ensureCallWidget() {
    let widget = document.querySelector('#xCallWidget');
    if (!widget) {
      widget = document.createElement('div');
      widget.id = 'xCallWidget';
      widget.className = 'x-call-widget';
      widget.setAttribute('role', 'button');
      widget.setAttribute('tabindex', '0');
      widget.setAttribute('aria-label', '通话中，点击准备挂断');
      widget.innerHTML = `
        <span class="x-call-widget-icon">
          <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
            <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z"></path>
          </svg>
        </span>
        <span class="x-call-widget-time" id="xCallWidgetTime">00:00</span>
      `;
      widget.addEventListener('click', () => {
        const timeLabel = widget.querySelector('#xCallWidgetTime');
        if (!xCallConfirmPending) {
          xCallConfirmPending = true;
          widget.classList.add('confirm-hangup');
          if (timeLabel) timeLabel.textContent = '挂断';
          if (xCallConfirmTimer) window.clearTimeout(xCallConfirmTimer);
          xCallConfirmTimer = window.setTimeout(() => {
            xCallConfirmPending = false;
            widget.classList.remove('confirm-hangup');
            xCallConfirmTimer = null;
            const elapsed = Math.floor((Date.now() - xCallStartTime) / 1000);
            if (timeLabel) timeLabel.textContent = formatCallDuration(elapsed);
          }, 3000);
        } else {
          xCallConfirmPending = false;
          widget.classList.remove('confirm-hangup');
          if (xCallConfirmTimer) {
            window.clearTimeout(xCallConfirmTimer);
            xCallConfirmTimer = null;
          }
          hangUpCall();
        }
      });
      widget.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); widget.click(); }
      });
    }
    // The connected-call indicator belongs to the whole site rather than the
    // chat panel. Keeping it directly under body prevents panel rerenders and
    // route changes from hiding or removing an active call.
    if (widget.parentElement !== document.body) document.body.appendChild(widget);
    return widget;
  }

  function startCallWidget(dreamId = '') {
    if (dreamId) xCallDreamId = dreamId;
    xCallOwnerId = String(currentXUser()?.userId || '');
    const widget = ensureCallWidget();
    xCallStartTime = Date.now();
    xCallConfirmPending = false;
    if (xCallConfirmTimer) {
      window.clearTimeout(xCallConfirmTimer);
      xCallConfirmTimer = null;
    }
    widget.classList.remove('confirm-hangup');
    widget.classList.add('show');
    window.SHEXCallOverlayView?.presentWidget(widget);
    const timeLabel = widget.querySelector('#xCallWidgetTime');
    if (timeLabel) timeLabel.textContent = '00:00';
    if (xCallIntervalTimer) window.clearInterval(xCallIntervalTimer);
    xCallIntervalTimer = window.setInterval(() => {
      const elapsed = Math.floor((Date.now() - xCallStartTime) / 1000);
      if (timeLabel && !xCallConfirmPending) timeLabel.textContent = formatCallDuration(elapsed);
    }, 1000);
    function scheduleNextHangupCheck() {
      if (xCallHangupCheckTimer) window.clearTimeout(xCallHangupCheckTimer);
      const minMs = 20 * 60 * 1000;
      const maxMs = 40 * 60 * 1000;
      const nextDelay = minMs + Math.floor(Math.random() * (maxMs - minMs));
      xCallHangupCheckTimer = window.setTimeout(() => {
        if (Math.random() < 0.05) {
          hangUpCall('对方挂断了通话，时长');
        } else {
          scheduleNextHangupCheck();
        }
      }, nextDelay);
    }
    scheduleNextHangupCheck();
  }

  function hangUpCall(reasonText = '通话时长') {
    const widget = document.querySelector('#xCallWidget');
    if (!widget || !widget.classList.contains('show')) return;
    const callDreamId = String(xCallDreamId || '').trim();
    const elapsed = Math.max(0, Math.floor((Date.now() - xCallStartTime) / 1000));
    const noticeText = `${reasonText} ${formatCallDuration(elapsed)}`;
    const noticeMessage = { type: 'notice', noticeKind: 'call', text: noticeText };
    xCallConfirmPending = false;
    if (xCallConfirmTimer) {
      window.clearTimeout(xCallConfirmTimer);
      xCallConfirmTimer = null;
    }
    widget.classList.remove('confirm-hangup');
    if (xCallIntervalTimer) {
      window.clearInterval(xCallIntervalTimer);
      xCallIntervalTimer = null;
    }
    if (xCallHangupCheckTimer) {
      window.clearTimeout(xCallHangupCheckTimer);
      xCallHangupCheckTimer = null;
    }
    let resultEntry = null;
    try {
      if (String(currentXUser()?.userId || '') === xCallOwnerId && (!callDreamId || dreamById(callDreamId))) {
        resultEntry = callDreamId
          ? addMessageToDream(callDreamId, noticeMessage)
          : addMessage(noticeMessage);
      }
    } catch (error) {
      console.error('[SHEX_CALL_END_RESULT_ERROR]', {
        dreamId: callDreamId,
        noticeText,
        detail: String(error?.stack || error?.message || error || 'unknown_error').slice(0, 1800)
      });
    }
    const targetConversationKey = callDreamId ? `single:${callDreamId}` : activeConversationKey();
    if (activeConversationKey() === targetConversationKey) {
      scrollChatLogToBottom($('#ixLog'));
      forceChatLogRepaint($('#ixLog'), 'call_end');
    }
    showChatToast(resultEntry?.localSaveFailed ? `${noticeText}；记录暂未保存` : noticeText);
    widget.classList.remove('show');
    window.SHEXCallOverlayView?.dismissWidget(widget);
    playCallSound('call-end.mp3');
    xCallDreamId = '';
    xCallOwnerId = '';
  }

  const xIncomingCallCooldownKey = 'shex_x_incoming_call_cooldown_v1';

  function isIncomingCallOnCooldown(dreamId) {
    try {
      const map = JSON.parse(localStorage.getItem(xIncomingCallCooldownKey) || '{}');
      const last = Number(map[dreamId] || 0);
      return (Date.now() - last) < 45 * 60 * 1000;
    } catch (_) {
      return false;
    }
  }

  function markIncomingCallCooldown(dreamId) {
    try {
      const map = JSON.parse(localStorage.getItem(xIncomingCallCooldownKey) || '{}');
      map[dreamId] = Date.now();
      localStorage.setItem(xIncomingCallCooldownKey, JSON.stringify(map));
    } catch (_) {}
  }

  function isAnyCallActive() {
    const overlay = document.querySelector('#xCallOverlay');
    const widget = document.querySelector('#xCallWidget');
    return (overlay && overlay.classList.contains('show')) || (widget && widget.classList.contains('show'));
  }

  function maybeTriggerIncomingCall(text, dream) {
    if (!dream || !dream.id) return;
    if (isAnyCallActive()) return;
    if (isIncomingCallOnCooldown(dream.id)) return;
    const category = replyCategoryFor(text);
    const boostedCategories = ['missing', 'love_confirm', 'relationship_security'];
    const chance = boostedCategories.includes(category) ? 0.025 : 0.01;
    if (Math.random() > chance) return;
    markIncomingCallCooldown(dream.id);
    const callOwnerId = String(currentXUser()?.userId || '');
    window.setTimeout(() => {
      if (String(currentXUser()?.userId || '') !== callOwnerId) return;
      if (!dreamById(dream.id)) return;
      if (!isAnyCallActive()) openIncomingCallOverlay(dream);
    }, randomBetween(1500, 4000));
  }

  function groupAvatarMarkup(group = {}, className = 'x-group-avatar') {
    return group.avatar
      ? `<img class="${className}" src="${group.avatar}" alt="${escapeHtml(group.name || '群聊')}头像">`
      : `<span class="${className}">群</span>`;
  }

