  function openDreamSwitcher() {
    const state = ensureStateFromIdentity('dream_switcher_repair_from_identity');
    const worldContexts = [...ownedWorldRunContexts.values()];
    if (!state.dreams.length && !worldContexts.length) return showInitializationForm();
    closeModal();
    const mask = document.createElement('div');
    mask.className = 'x-modal-mask show';
    mask.id = 'xDreamSwitchMask';
    mask.innerHTML = `
      <section class="x-modal-sheet">
        <div class="x-modal-head"><h3>切换 X世界</h3><button type="button" data-close-modal>×</button></div>
        <div class="x-switch-list">
          ${state.dreams.map((dream) => `
            <button class="x-switch-row${!selectedXWorldRunId && dream.id === state.currentDreamId ? ' is-current' : ''}" type="button" data-switch-dream="${dream.id}">
              ${dreamAvatarMarkup(dream)}
              <span>${escapeHtml(dream.name)}</span>
              <small>${!selectedXWorldRunId && dream.id === state.currentDreamId ? '当前 X世界' : '切换到此人物'}</small>
            </button>
          `).join('')}
          ${worldContexts.map((context) => `
            <button class="x-switch-row${context.runId === selectedXWorldRunId ? ' is-current' : ''}" type="button" data-switch-world-run="${escapeHtml(context.runId)}">
              ${worldRunContactAvatarMarkup(context.contact, 'x-dream-avatar')}
              <span>${escapeHtml(context.title || '未命名世界')}</span>
              <small>${context.runId === selectedXWorldRunId ? '当前 X世界' : '切换到此世界'}</small>
            </button>
          `).join('')}
        </div>
      </section>
    `;
    document.body.appendChild(mask);
    resolveDreamAvatarImages(mask);
    mask.addEventListener('click', (event) => {
      if (event.target === mask || event.target.closest('[data-close-modal]')) closeModal();
      const worldButton = event.target.closest('[data-switch-world-run]');
      if (worldButton) {
        const currentView = document.body.dataset.xPage || 'home';
        const context = selectXWorldRun(worldButton.dataset.switchWorldRun);
        if (!context) return;
        closeModal();
        ensureXHomeChrome();
        applyXWorldAccentColor(DEFAULT_X_WORLD_ACCENT_COLOR);
        applyXWorldWidgetVisibility(null);
        if (currentView === 'settings') installSettings();
        else if (currentView === 'world') installWorldHome();
        else setXLinkView('world', 'world_run_switch');
        refreshWorldAlbumDisplay();
        showChatToast('已切换当前 X世界');
        return;
      }
      const button = event.target.closest('[data-switch-dream]');
      if (!button) return;
      const beforeVisiblePanels = visibleXPanels();
      const currentView = document.body.dataset.xPage || 'home';
      if (currentView === 'companion') {
        const companionStage = $('#xCompanionStage');
        const companionAudio = $('#xCleanAudio', companionStage);
        if (companionStage && companionAudio) updateCompanionListenClock(companionStage, companionAudio);
        persistCompanionListenSeconds({ force: true, dreamId: companionListenDreamId });
      }
      updateState((draft) => {
        draft.currentDreamId = button.dataset.switchDream;
        draft.currentDreamChangedAt = Date.now();
      });
      selectXWorldRun('');
      const switchedState = readState();
      const switchedDream = currentWorldDream(switchedState);
      window.dispatchEvent(new CustomEvent('shex:dream-changed', { detail: { dreamId: switchedDream?.id || button.dataset.switchDream } }));
      void syncUserDataAfterResourceChange();
      closeModal();
      ensureXHomeChrome();
      applyXWorldAccentColor(switchedDream?.xWorldAccentColor);
      applyXWorldWidgetVisibility(switchedDream?.xWorldWidgetVisibility);
      if (['message', 'letter', 'letters-v1', 'ta-status', 'link-status', 'settings', 'avatar-display', 'album', 'reply', 'companion', 'world'].includes(currentView)) {
        setXLinkView(currentView, 'dream_switch_keep_view');
      } else {
        setXLinkView('home', 'dream_switch_return_home');
      }
      if (currentView === 'message') installChat();
      if (currentView === 'letter') installLetter();
      if (currentView === 'letters-v1') installXLettersV1();
      if (currentView === 'ta-status') installTaStatus();
      if (currentView === 'link-status') installLinkStatus();
      if (currentView === 'settings') installSettings();
      if (currentView === 'avatar-display') installAvatarDisplay();
      if (currentView === 'album') installAlbum();
      if (currentView === 'reply') installReply();
      if (currentView === 'companion') installCompanion();
      if (currentView === 'world') installWorldHome();
      const afterVisiblePanels = visibleXPanels();
      shexDebugLog('log', '[DREAM_SWITCH_DEBUG]', {
        dreamId: switchedDream?.id || button.dataset.switchDream,
        dreamName: switchedDream?.name || '',
        currentView,
        currentHash: location.hash,
        beforeVisiblePanels,
        afterVisiblePanels,
        calledShowIdentityForm: false
      });
      if (afterVisiblePanels.identity && ['message', 'letter', 'letters-v1', 'ta-status', 'link-status', 'settings', 'avatar-display', 'album', 'reply', 'companion', 'world'].includes(currentView)) {
        shexDebugLog('warn', '[XLINK_PANEL_CONFLICT]', {
          reason: 'identity_panel_visible_after_dream_switch',
          currentHash: location.hash,
          visiblePanels: afterVisiblePanels
        });
        setXLinkView(currentView, 'repair_identity_visible_after_dream_switch');
      }
      showChatToast('已切换当前服务梦角');
    });
  }

