    const worldIcon = worldButton.querySelector('.x-tab-icon-wrap');
    if (messageIcon) {
      messageIcon.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14.5 6.5-5.5 5.5 5.5 5.5"/></svg>';
    }
    messageButton.setAttribute('aria-label', '上一页软件图标');
    messageButton.title = '上一页';
    if (worldIcon) {
      worldIcon.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9.5 6.5 5.5 5.5-5.5 5.5"/></svg>';
    }
