  function isXLinkRuneClick(grid, event) {
    if (!grid || !event) return false;
    const pseudo = window.getComputedStyle(grid, '::before');
    if (!pseudo || pseudo.content === 'none' || pseudo.display === 'none') return false;
    const rect = grid.getBoundingClientRect();
    const toPx = (value) => Number(String(value || '').replace('px', '')) || 0;
    const matrix = String(pseudo.transform || '').match(/matrix\(([^)]+)\)/);
    const transformParts = matrix ? matrix[1].split(',').map((part) => Number(part.trim()) || 0) : [];
    const translateX = transformParts[4] || 0;
    const translateY = transformParts[5] || 0;
    const fontSize = toPx(pseudo.fontSize);
    const centerX = rect.left + toPx(pseudo.left) + translateX + fontSize / 2;
    const centerY = rect.top + toPx(pseudo.top) + translateY + fontSize / 2;
    const hitSize = Math.max(40, fontSize * 1.6);
    return Math.abs(event.clientX - centerX) <= hitSize && Math.abs(event.clientY - centerY) <= hitSize;
  }

  function routeFromHash(options = {}) {
    if (datingChatReturnSource && !datingChatReturnSource.opening && location.hash === datingChatReturnSource.hash && returnDatingChatSource()) return;
    // The room route uses the same front-end admin gate as its home entry.
    if (location.hash === hashes.pet) {
      stopCurrentChatProactiveTimer();
      lastXLinkRouteSignature = '';
      openPage('pet', false);
      return;
    }
    const gallerySearch = window.SHEXCharacterGallery?.readGallerySearchRoute?.(location.hash);
    if (gallerySearch) {
      pendingGallerySearch = gallerySearch.keyword;
      pendingGallerySearchSequence += 1;
      pendingGallerySection = 'plaza';
      history.replaceState(null, '', hashes['character-gallery']);
      lastXLinkRouteSignature = '';
    }
    // Preserve the requested public search destination across the ordinary login gate.
    if (pendingGallerySearch !== null && xHasLoggedInUser()
      && location.hash !== hashes['character-gallery']) {
      history.replaceState(null, '', hashes['character-gallery']);
      lastXLinkRouteSignature = '';
    }
    if (!location.hash || location.hash === '#home' || location.hash === '#studio') {
      history.replaceState(null, '', hashes.world);
      lastXLinkRouteSignature = '';
    }
    if (location.hash !== '#x-message-chat') stopCurrentChatProactiveTimer();
    if (isXLinkResourceLimitActive() && isXLinkResourceLimitedHash()) {
      redirectXLinkLimitToStudio();
      return;
    }
    if (!isXLinkHash()) {
      lastXLinkRouteSignature = '';
      unlockPage();
      syncXTabbarVisibility();
      return;
    }
    if (shouldDelayXLinkRouteUntilRestore()) {
      lastXLinkRouteSignature = '';
      showPendingXLinkRestore('route_waiting_for_restore');
      return;
    }
    const signature = xLinkRouteSignature();
    if (signature === lastXLinkRouteSignature) {
      shexDebugLog('log', '[XLINK_ROUTE_SKIP]', {
        reason: 'same_signature',
        hash: location.hash,
        dataLoadStatus: xDataStatus(),
        restoringFromCloud: xRestoringFromCloud()
      });
      return;
    }
    lastXLinkRouteSignature = signature;
    if (location.hash === '#transmission') {
      if (ensureXReady()) openPage('message', false);
      return;
    }
    const page = hashPages[location.hash];
    if (page === 'message' && !(options.preserveActiveThread && activeThread.type)) leaveConversation('message_route_reset');
    if (page) openPage(page, false);
  }

  function bindEntryButtons() {
    installXTabbarRuneEntry();
    document.querySelectorAll('[data-x-home-back]').forEach((button) => {
      button.setAttribute('aria-label', '返回 X世界');
    });
    ['#showMessage', '#showLetter'].forEach((selector) => {
      const button = $(selector);
      if (!button || button.dataset.xCleanEntryFresh === 'true') return;
      const fresh = button.cloneNode(true);
      fresh.dataset.xCleanEntryFresh = 'true';
      button.parentNode?.replaceChild(fresh, button);
    });
    document.addEventListener('click', (event) => {
      const link = event.target.closest?.('a[href="#transmission"]');
      if (!link) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      document.body.classList.add('entered');
      // 进入X链接模式：显示transmission，隐藏studio和about
      const studioEl = document.getElementById('studio');
      const transmissionEl = document.getElementById('transmission');
      const aboutEl = document.getElementById('about');
      if (transmissionEl) transmissionEl.style.removeProperty('display');
      if (studioEl) studioEl.style.setProperty('display', 'none');
      if (aboutEl) aboutEl.style.setProperty('display', 'none');
      logXLinkEntryChainDebug({
        step: 'xlink_home_anchor_click',
        nextAction: xDataStatus() === 'success' ? 'ensure_ready' : 'show_restore_waiting'
      });
      if (!xHasLoggedInUser()) {
        showXDataLoadingNotice();
        return;
      }
      if (xDataStatus() !== 'success' || xRestoringFromCloud()) {
        showXDataLoadingNotice();
      } else if (ensureXReady()) {
        openPage('message');
      }
      window.requestAnimationFrame(() => {
        $('#transmission')?.scrollIntoView({ behavior: 'auto', block: 'start' });
      });
    }, true);
    document.addEventListener('click', (event) => {
      const grid = event.target.closest?.('#xLinkHome .x-entry-grid');
      if (!grid) return;
      if (event.target.closest('.x-entry-card, button, a, input, textarea, select, label')) return;
      if (!isXLinkRuneClick(grid, event)) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      playXLinkRuneEffect(grid);
    }, true);
    const bindings = [
      ['#showMessage', 'message'],
      ['#showWorldMessage', 'message'],
      ['#showXWorld', 'world'],
      ['#showLetter', 'letter'],
      ['#showXLettersV1', 'letters-v1'],
      ['#showTaStatus', 'ta-status'],
      ['#showLinkStatus', 'link-status'],
      ['#showDivination', 'divination'],
      ['#showDating', 'dating'],
      ['#showPersona', 'character-profile'],
      ['#showCreatorWorkbench', 'creator-workbench'],
      ['#showCharacterGallery', 'character-gallery'],
      ['#showCalendar', 'calendar'],
      ['#showAstrology', 'astrology'],
      ['#showSettings', 'settings'],
      ['#showSReply', 'reply'],
      ['#showCompanion', 'companion'],
      ['#showPet', 'pet']
    ];
    document.addEventListener('click', (event) => {
      const match = bindings.find(([selector]) => event.target.closest(selector));
      if (!match) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      logXLinkEntryDebug({
        targetEntry: match[1],
        allowXLink: xIsAdminUser() || (!isXLinkResourceLimitActive() && xHasLoggedInUser()),
        nextAction: `open_${match[1]}`
      });
      if (selectedXWorldRunContext() && !creatorExperienceForXWorld().allowsWorldEntry(match[1])) {
        showChatToast('当前世界仅提供 X传讯、设置和广场');
        return;
      }
      if (creatorExperienceForXWorld().sessionKind === 'gallery_single' && match[1] === 'character-profile') return;
      if (match[1] === 'message') leaveConversation('message_entry_opened');
      if (match[1] === 'character-profile') {
        const dream = currentWorldDream(readState());
        characterProfileOpenOptions = { dreamId: dream?.id || '', tab: 'ta', backTarget: 'world' };
        openPage('character-profile');
        return;
      }
      openPage(match[1]);
    }, true);
    document.addEventListener('click', (event) => {
      if (!event.target.closest('[data-x-home-back], .x-subpage-back, #ixBackHome')) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      if (event.target.closest('#xAlbumPanel [data-x-album-back]')) {
        if (albumPageReturnView === 'settings') openPage('settings');
        else if (albumPageReturnView === 'companion') openPage('companion');
        else returnToXWorldHome();
        return;
      }
      if (event.target.closest('#xWorldHome [data-x-home-back]')) {
        returnToXWorldHome();
        return;
      }
      if (event.target.closest('#xCompanionPanel .x-subpage-back') && returnCompanionToSetup()) {
        return;
      }
      if (event.target.closest('#ixBackHome') && activeThread.type) {
        if (returnDatingChatSource()) return;
        if (activeThread.type === 'world_run') {
          exitActiveWorldRunConversation();
          return;
        }
        renderConversationList();
        return;
      }
      returnToXWorldHome();
    }, true);
    document.addEventListener('click', (event) => {
      if (!event.target.closest('#xEditIdentity')) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      openDreamSwitcher();
    }, true);
    $('#xIdentityForm')?.addEventListener('submit', saveIdentityFromForm, true);
    document.getElementById('xTabMessage')?.addEventListener('click', () => {
      setXWorldAppPage(xWorldAppPage - 1);
    });
    document.getElementById('xTabRune')?.addEventListener('click', () => {
      playXLinkRuneEffect(document.getElementById('xTabbar'));
    });
    document.getElementById('xTabWorld')?.addEventListener('click', () => {
      setXWorldAppPage(xWorldAppPage + 1);
    });
  }

  function chatHistory() {
    const state = readState();
    const active = requireActiveConversation(state);
    if (active?.kind === 'group' && active.group) return state.groupChats[active.group.id] || [];
    if (active?.kind === 'single' && active.dream) return state.singleChats[active.dream.id] || [];
    if (active?.kind === 'world_run' && active.worldRun) return (active.worldRun.messages || []).filter(message => !message.deletedAt);
    return [];
  }

  function localChatSaveFailureKey(conversationId, messageId) {
    return `${String(conversationId || '')}:${String(messageId ?? '')}`;
  }

  function localFailedMessagesForConversation(conversationId) {
    return Array.from(localChatSaveFailures.values())
      .filter((item) => item?.conversationId === conversationId && item?.message)
      .map((item) => item.message)
      .sort((left, right) => chatMessageTimestamp(left) - chatMessageTimestamp(right));
  }

  function localFailedMessageForDeliveryItem(conversationId, deliveryItemId) {
    if (!conversationId || !deliveryItemId) return null;
    return Array.from(localChatSaveFailures.values())
      .find((item) => item?.conversationId === conversationId
        && item?.message?.deliveryItemId === deliveryItemId) || null;
  }

  function mergeChatMessagesById(currentMessages = [], incomingMessages = [], options = {}) {
    const byId = new Map();
    const add = (message, preferIncoming) => {
      if (!message || typeof message !== 'object') return;
      const id = message.id === undefined || message.id === null ? '' : String(message.id);
      const identity = id || `legacy:${JSON.stringify([message.role || '', message.time || 0, message.text || '', message.type || ''])}`;
      const previous = byId.get(identity);
      if (!previous || preferIncoming) byId.set(identity, message);
    };
    currentMessages.forEach((message) => add(message, false));
    incomingMessages.forEach((message) => add(message, true));
    const merged = Array.from(byId.values());
    // WorldRun 历史由服务端 sequence 排好；恢复的消息没有逐条时间。
    // 用普通单聊的时间排序会把最近恢复的消息移到最前面，随后被最近 100 条窗口遮住。
    return options.preserveSourceOrder === true
      ? merged
      : merged.sort((left, right) => chatMessageTimestamp(left) - chatMessageTimestamp(right));
  }

  function rememberLocalChatSaveFailure(conversationId, message) {
    if (!conversationId || !message?.id) return;
    localChatSaveFailures.set(localChatSaveFailureKey(conversationId, message.id), {
      conversationId,
      message,
      error: lastLocalStorageWriteError || new Error('local chat storage write failed')
    });
  }

  function clearLocalChatSaveFailure(conversationId, messageId) {
    localChatSaveFailures.delete(localChatSaveFailureKey(conversationId, messageId));
  }

  function saveChatForKey(key, messages) {
    const [kind, id] = String(key || '').split(':');
    if (kind === 'world_run') {
      const current = String(activeWorldRunContext?.runId || '') === id ? activeWorldRunContext : ownedWorldRunContext(id);
      if (!current) return false;
      const next = {
        ...current,
        messages: window.SHEXWorldRunXMessageContext?.mergeMessages?.(current.messages || [], messages || [])
          || mergeChatMessagesById(current.messages || [], messages || [])
      };
      rememberOwnedWorldRunContext(next);
      return true;
    }
    const saved = updateState((draft) => {
      if (kind === 'group' && id) {
        const merged = mergeChatMessagesById(draft.groupChats[id] || [], messages || []);
        draft.groupChats[id] = filterChatMessagesByWatermark(merged, draft.groupChatCleanupWatermarks?.[id]);
      }
      if (kind === 'single' && id) {
        const merged = mergeChatMessagesById(draft.singleChats[id] || [], messages || []);
        draft.singleChats[id] = filterChatMessagesByWatermark(merged, draft.singleChatCleanupWatermarks?.[id]);
      }
    });
    if (!saved) {
      showChatToast('本地存储空间不足，聊天可能无法保存，请清理一些图片或表情包');
    } else if (kind === 'single' && id) {
      const ownerUserId = String(window.SHEXAuth?.current?.()?.userId || '');
      window.SHEXCalendarMoodActivity?.recordMessages?.(ownerUserId, kind, id, messages || []);
    }
    if (saved) notifyLightChat(key);
    return saved;
  }

  const CHAT_CLEANUP_DAY_MS = 24 * 60 * 60 * 1000;

  function clearRemovedChatDeliveries(conversationId, messages = []) {
    messages.forEach((message) => clearXMessageReplyDelivery(conversationId, message?.id));
  }

  async function deleteCurrentChatHistory(option) {
    const active = requireActiveConversation();
    const conversationId = conversationKey(active);
    if (!conversationId || !(active?.kind === 'single' || active?.kind === 'group')) {
      showChatToast('请先进入一个聊天');
      return;
    }
    flushPendingChatSave();
  const now = Date.now();
  const requestedWatermark = option?.days == null ? now : now - option.days * CHAT_CLEANUP_DAY_MS;
  let removedMessages = [];
  const saved = updateState((draft) => {
      const isGroup = active.kind === 'group';
      const chatId = isGroup ? active.group?.id : active.dream?.id;
      if (!chatId) return;
      const watermarks = isGroup ? draft.groupChatCleanupWatermarks : draft.singleChatCleanupWatermarks;
    const chats = isGroup ? draft.groupChats : draft.singleChats;
    const previousWatermark = Number(watermarks?.[chatId] || 0);
    const nextWatermark = Math.max(previousWatermark, requestedWatermark);
    watermarks[chatId] = nextWatermark;
    const messages = Array.isArray(chats[chatId]) ? chats[chatId] : [];
    removedMessages = messages.filter((message) => chatMessageTimestamp(message) < nextWatermark);
    chats[chatId] = filterChatMessagesByWatermark(messages, nextWatermark);
    });
    if (!saved) {
      showChatToast('删除失败，请稍后再试');
      return;
    }
    clearRemovedChatDeliveries(conversationId, removedMessages);
    hideTaTyping();
    requestFullChatRender({ reason: 'history-cleanup' });
    const synced = await syncUserDataAfterResourceChange('');
    if (synced) {
      const label = option?.days == null ? '已清空当前聊天记录' : `已删除 ${removedMessages.length} 条聊天记录`;
      showChatToast(label);
    }
  }

  function openCurrentChatHistoryCleanup(option) {
    const active = requireActiveConversation();
    if (!(active?.kind === 'single' || active?.kind === 'group')) {
      showChatToast('请先进入一个聊天');
      return;
    }
    const label = option?.days == null ? '全部聊天记录' : `${option.label}的聊天记录`;
    openCustomCardConfirm({
      title: '删除聊天记录',
      body: `将删除当前${active.kind === 'group' ? '群聊' : '单聊'}中${label}。删除后不可恢复，确定删除吗？`,
      confirmText: '删除',
      onConfirm: () => void deleteCurrentChatHistory(option)
    });
  }

  function saveChatNow(messages) {
    return saveChatForKey(activeConversationKey(), messages);
  }

  function flushPendingChatSave() {
    const pending = pendingChatSave;
    pendingChatSave = null;
    if (!pending) return true;
    if (pending.timer) window.clearTimeout(pending.timer);
    return saveChatForKey(pending.key, pending.messages || []);
  }

  function flushXMessageData() {
    try {
      return flushPendingChatSave();
    } catch (error) {
      console.warn('[XChat] flush pending chat failed', error);
      return false;
    }
  }

  window.SHEXFlushXMessageData = flushXMessageData;
  window.addEventListener('pagehide', flushXMessageData);
  window.addEventListener('beforeunload', flushXMessageData);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) flushXMessageData();
  });

  function scheduleChatSave(key, messages) {
    // Do not retain an old array for a later whole-conversation overwrite.
    // saveChatForKey unions it with the latest state by message ID.
    return key ? saveChatForKey(key, messages || []) : saveChatNow(messages || []);
  }

  function saveChat(messages) {
    const key = activeConversationKey();
    if (pendingChatSave?.key === key) {
      if (pendingChatSave.timer) window.clearTimeout(pendingChatSave.timer);
      pendingChatSave = null;
    }
    return saveChatNow(messages);
  }

  function persistChatEntry(key, entry, previousMessage, isActiveTarget) {
    // Pet controls are private reply metadata, never saved/displayed prose.
    const petCleaned = window.SHEXPetCommands?.cleanEntry(entry);
    if (petCleaned) Object.assign(entry, petCleaned);
    // 整条回复只有音乐指令时不落成聊天消息：指令照常执行，只用轻提示告诉用户。
    maybeAttachCardQuestions(key, entry);
    captureQuestionAnswerFromReply(key, entry);
    captureLinkCardGoalFromReply(key, entry);
    const music = extractSharedMusicCommands(key, entry);
    if (music?.kind === 'command_only') {
      // Pet controls require a readable committed reply; keep the existing
      // music-only shortcut for the other shared-player entry points.
      if (!music.petRequest) music.execute();
      return false;
    }
    const saved = saveChatForKey(key, [entry]);
    if (!saved) {
      finishSharedMusicCommandSave(key, entry, music, false);
      entry.localSaveFailed = true;
      rememberLocalChatSaveFailure(key, entry);
      if (isActiveTarget) appendChatEntry(entry, previousMessage);
      return false;
    }
    clearLocalChatSaveFailure(key, entry.id);
    finishSharedMusicCommandSave(key, entry, music, true);
    const appended = isActiveTarget ? appendChatEntry(entry, previousMessage) : false;
    if (isActiveTarget && !appended) requestFullChatRender({ reason: 'append-recovery' });
    return true;
  }

  function retryLocalChatSave(conversationId, messageId) {
    const failed = localChatSaveFailures.get(localChatSaveFailureKey(conversationId, messageId));
    if (!failed?.message) return false;
    const retryMessage = { ...failed.message, localSaveFailed: false };
    const saved = saveChatForKey(conversationId, [retryMessage]);
    if (!saved) return false;
    clearLocalChatSaveFailure(conversationId, messageId);
    finishSharedMusicCommandSave(conversationId, retryMessage, null, true);
    failed.message.localSaveFailed = false;
    if (activeConversationKey() === conversationId) {
      requestChatMessageReconciliation(conversationId, [messageId], 'local-save-retry');
    }
    showChatToast('消息已保存，正在同步');
    return true;
  }

  function addMessageToDream(dreamId, message) {
    const id = String(dreamId || '').trim();
    if (!id) return addMessage(message);
    const key = `single:${id}`;
    const state = readState();
    if (!state.dreams.some((dream) => String(dream?.id || '') === id)) return addMessage(message);
    const sourceMessages = Array.isArray(state.singleChats?.[id]) ? state.singleChats[id] : [];
    const entry = { ...message, id: message?.id || createXId('msg'), time: Date.now() };
    const previousMessage = sourceMessages[sourceMessages.length - 1] || null;
    const isActiveTarget = activeConversationKey() === key;
    const saved = persistChatEntry(key, entry, previousMessage, isActiveTarget);
    if (saved) (window.queueMicrotask || ((task) => window.setTimeout(task, 0)))(() => window.SHEXVoice?.onMessageCommitted?.({ conversationKey: key, message: entry, dreamId: id }));
    return entry;
  }

  function addMessageToConversation(key, message) {
    const target = conversationForKey(key);
    const targetId = target.kind === 'group' ? target.group?.id : target.dream?.id;
    if (!targetId) return null;
    const sourceMessages = target.kind === 'group'
      ? (readState().groupChats[targetId] || [])
      : (readState().singleChats[targetId] || []);
    const entry = { ...message, id: message?.id || createXId('msg'), time: Date.now() };
    const previousMessage = sourceMessages[sourceMessages.length - 1] || null;
    const isActiveTarget = activeConversationKey() === key;
    const saved = persistChatEntry(key, entry, previousMessage, isActiveTarget);
    if (!isActiveTarget && $('#xMessagePanel')?.classList.contains('x-message-list-mode')) {
      renderConversationList();
    }
    if (entry.role === 'ta' && entry.text && !entry.sticker && !entry.image && !entry.media && entry.type !== 'notice') {
      recordRecentReplyForDream(entry.text, target.dream || null, entry);
    }
    if (saved) (window.queueMicrotask || ((task) => window.setTimeout(task, 0)))(() => window.SHEXVoice?.onMessageCommitted?.({ conversationKey: key, message: entry, dreamId: target.kind === 'single' ? target.dream?.id || '' : '' }));
    return entry;
  }

  function addMessage(message, options = {}) {
    const key = activeConversationKey();
    const target = conversationForKey(key);
    if (!key || !(target.kind === 'single' || target.kind === 'group' || target.kind === 'world_run')) return null;
    const messages = chatHistory();
    const entry = { ...message, id: message?.id || createXId('msg'), time: Date.now() };
    const previousMessage = messages[messages.length - 1] || null;
    const saved = persistChatEntry(key, entry, previousMessage, true);
    if (target.kind !== 'world_run' && entry.role === 'ta' && entry.text && !entry.sticker && !entry.image && !entry.media && entry.type !== 'notice') {
      recordRecentReplyForDream(entry.text, null, entry);
    }
    if (saved && target.kind !== 'world_run' && !String(entry.linkCard?.kind || '').startsWith('dating_')) (window.queueMicrotask || ((task) => window.setTimeout(task, 0)))(() => window.SHEXVoice?.onMessageCommitted?.({ conversationKey: key, message: entry, dreamId: target.kind === 'single' ? target.dream?.id || '' : '' }));
    return entry;
  }

  function mergeAppearanceInstances(current = [], incoming = []) {
    const byId = new Map();
    [...(Array.isArray(current) ? current : []), ...(Array.isArray(incoming) ? incoming : [])].forEach((item) => {
      const instanceId = String(item?.instanceId || '').trim();
      if (instanceId) byId.set(instanceId, item);
    });
    const limit=Math.max(1,Number(window.SHEXBeautify?.hosts?.hostChat?.MAX_DYNAMIC_TURN_COMPONENTS||12));
    return [...byId.values()].slice(0,limit);
  }

  function captureBeautifyTurnPlan(turnMessageId, requestId) {
    try {
      return window.SHEXBeautify?.hosts?.hostChat?.captureTurnComponentPlan?.({ turnMessageId, requestId, createdAt:Date.now() }) || { before:[], after:[] };
    } catch (_) {
      return { before:[], after:[] };
    }
  }

  // X103：WorldRun 复用单聊的回复前/后组件链路（captureBeautifyTurnPlan → turnComponentTemplatesForDelivery
  // → targetTurnComponentInstances → appearanceInstances → renderChatTurnInstances），只补接线。
  // WorldRun 消息由服务端权威历史提供，不进入 singleChats；本机按 账号 + runId + messageId 保存组件关联。
  const WORLD_RUN_TURN_APPEARANCE_KEY_PREFIX = 'shex_world_run_turn_appearance_v1';
  const WORLD_RUN_TURN_APPEARANCE_MAX_MESSAGES = 300;
  function worldRunTurnAppearanceKey(runId) {
    const ownerId = String(window.SHEXAuth?.current?.()?.userId || '').trim();
    const run = String(runId || '').trim();
    return ownerId && run ? `${WORLD_RUN_TURN_APPEARANCE_KEY_PREFIX}:${ownerId}:${run}` : '';
  }
  function readWorldRunTurnAppearance(runId) {
    const key = worldRunTurnAppearanceKey(runId);
    if (!key) return {};
    try {
      const parsed = JSON.parse(localStorage.getItem(key) || '{}');
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) && parsed.messages && typeof parsed.messages === 'object' ? parsed.messages : {};
    } catch (_) { return {}; }
  }
  // 实时回复的消息 id 是 `${requestId}:reply:n`，历史回复是权威 id；两者共享 authoritativeReplyId + replyIndex。
  function worldRunTurnMessageKey(message = {}) {
    const authoritativeId = String(message?.authoritativeReplyId || '').trim();
    const index = Number(message?.replyIndex);
    return authoritativeId && Number.isInteger(index) && index >= 0 ? `reply:${authoritativeId}#${index}` : `id:${String(message?.id || '').trim()}`;
  }
  function persistWorldRunTurnAppearance(runId, attached) {
    const key = worldRunTurnAppearanceKey(runId);
    if (!key || !attached?.size) return false;
    try {
      const messages = readWorldRunTurnAppearance(runId);
      attached.forEach((instances, messageKey) => { messages[String(messageKey)] = mergeAppearanceInstances(messages[String(messageKey)], instances); });
      const entries = Object.entries(messages).slice(-WORLD_RUN_TURN_APPEARANCE_MAX_MESSAGES);
      localStorage.setItem(key, JSON.stringify({ version:1, messages:Object.fromEntries(entries) }));
      return true;
    } catch (_) { return false; }
  }
  function hydrateWorldRunTurnAppearance(context) {
    if (!context?.runId || !Array.isArray(context.messages) || !context.messages.length) return context;
    const saved = readWorldRunTurnAppearance(context.runId);
    if (!Object.keys(saved).length) return context;
    const retarget = window.SHEXBeautify?.hosts?.hostChat?.targetTurnComponentInstances;
    let changed = false;
    const messages = context.messages.map((message) => {
      if (message?.role !== 'ta') return message;
      const stored = saved[worldRunTurnMessageKey(message)] || saved[`id:${String(message?.id || '')}`];
      if (!Array.isArray(stored) || !stored.length) return message;
      const targeted = typeof retarget === 'function' ? retarget(stored, String(message.id)) : stored;
      const merged = mergeAppearanceInstances(message.appearanceInstances, targeted);
      if (merged.length === (message.appearanceInstances || []).length) return message;
      changed = true;
      return { ...message, appearanceInstances:merged };
    });
    return changed ? { ...context, messages } : context;
  }
  function attachWorldRunTurnAppearance(context, previousIds, plan) {
    const templates = [...(plan?.before || []), ...(plan?.after || [])];
    const host = window.SHEXBeautify?.hosts?.hostChat;
    if (!templates.length || !context?.runId || typeof host?.turnComponentTemplatesForDelivery !== 'function' || typeof host?.targetTurnComponentInstances !== 'function') return context;
    const fresh = (context.messages || []).filter((message) => message?.role === 'ta' && !previousIds.has(String(message?.id || '')));
    if (!fresh.length) return context;
    const items = fresh.map((message) => ({ deliveryItemId:String(message.id) }));
    const attached = new Map(), persisted = new Map();
    // X103：回合组件 = 当轮状态快照。按「本轮完成后的新状态」构造绑定输入并冻结进实例的
    // bindingSnapshot，随下面的 persistWorldRunTurnAppearance 一起落本地；此刻 active 仍是旧状态，
    // 所以不能用 runtimeBindingContext()，必须显式用 applyReply 的结果 context。
    const snapshotInput = {
      conversation:{ kind:'world_run', runId:String(context.runId || '') },
      statePresentation:context.statePresentation || null,
      worldVariables:window.SHEXWorldRunVariables?.publicProjection?.(context.variableDefinitions, context.variables) || null
    };
    fresh.forEach((message) => {
      const deliveryTemplates = host.turnComponentTemplatesForDelivery(templates, String(message.id), items);
      const targeted = deliveryTemplates.length ? host.targetTurnComponentInstances(deliveryTemplates, String(message.id)) : [];
      const instances = targeted.length && typeof host.captureTurnBindingSnapshots === 'function'
        ? host.captureTurnBindingSnapshots(targeted, snapshotInput)
        : targeted;
      if (!instances.length) return;
      attached.set(String(message.id), instances);
      persisted.set(worldRunTurnMessageKey(message), instances);
    });
    if (!attached.size) return context;
    persistWorldRunTurnAppearance(context.runId, persisted);
    return {
      ...context,
      messages:context.messages.map((message) => attached.has(String(message?.id || ''))
        ? { ...message, appearanceInstances:mergeAppearanceInstances(message.appearanceInstances, attached.get(String(message.id))) }
        : message)
    };
  }

  function attachAppearanceInstancesToMessage(conversationKeyValue, messageId, instances = []) {
    const limit=Math.max(1,Number(window.SHEXBeautify?.hosts?.hostChat?.MAX_DYNAMIC_TURN_COMPONENTS||12));
    const normalized = Array.isArray(instances) ? instances.filter((item) => item?.instanceId).slice(0,limit) : [];
    if (!normalized.length) return findConversationMessage(conversationKeyValue, messageId);
    const [kind,id] = String(conversationKeyValue || '').split(':');
    let updated = null;
    const saved = updateState((draft) => {
      const messages = kind === 'group' ? draft.groupChats?.[id] : draft.singleChats?.[id];
      if (!Array.isArray(messages)) return;
      const index = messages.findIndex((message) => String(message?.id || '') === String(messageId || ''));
      if (index < 0) return;
      const merged = mergeAppearanceInstances(messages[index]?.appearanceInstances, normalized);
      if (merged.length === (messages[index]?.appearanceInstances || []).length) {
        const previousIds = new Set((messages[index]?.appearanceInstances || []).map((item) => String(item?.instanceId || '')));
        if (merged.every((item) => previousIds.has(String(item.instanceId)))) { updated = messages[index]; return; }
      }
      updated = { ...messages[index], appearanceInstances:merged };
      messages[index] = updated;
    });
    if (saved && updated && activeConversationKey() === conversationKeyValue) requestChatMessageReconciliation(conversationKeyValue,[messageId],'beautify-turn-instance-attach');
    return updated;
  }

  function proactiveContextCategory(text = '') {
    const value = String(text || '').trim();
    if (!value) return '';
    if (/累|困|撑不住|熬夜|睡不着|没睡|疲惫|好累|想睡/.test(value)) return 'tired';
    if (/难过|委屈|哭|崩溃|不开心|烦|心情不好|失落|emo|破防/.test(value)) return 'sad';
    if (/想你|想见|想抱|喜欢你|爱你|亲|抱抱|贴贴/.test(value)) return 'miss';
    if (/没话|不知道说什么|随便|你说|安静|不想说|没什么/.test(value)) return 'quiet';
    if (/吃饭|喝水|胃|生病|不舒服|头疼|肚子疼|到家|回家/.test(value)) return 'care';
    if (/吃醋|别人|前任|他|她|理别人|不理我|偏心/.test(value)) return 'jealous';
    if (/撒娇|哄我|黏|亲亲|抱|贴|想要/.test(value)) return 'sweet';
    return '';
  }

  function messagesForProactiveDream(dreamId = '', state = readState()) {
    if (dreamId && Array.isArray(state.singleChats?.[dreamId])) return state.singleChats[dreamId];
    return chatHistory();
  }

  function latestUserTextForProactive(dreamId = '', state = readState()) {
    return messagesForProactiveDream(dreamId, state)
      .slice()
      .reverse()
      .find((item) => item?.role === 'user' && !item.revoked && String(item.text || '').trim())?.text || '';
  }

  const proactiveMessageSourcesByReplyMode = Object.freeze({
    library: 'library'
  });

  function proactiveMessageSourceForDream(dream) {
    const replyMode = characterAIReplyMode({ kind: 'single', dream }, '', null);
    // AI主动消息来源尚未实现；这里按有效replyMode选择已注册来源，不代表AI模式永久禁用主动消息。
    return proactiveMessageSourcesByReplyMode[replyMode] || '';
  }

  function pickProactiveMessage(dreamId = '', state = readState()) {
    const recentTexts = messagesForProactiveDream(dreamId, state)
      .slice(-30)
      .map((item) => stripIxPeriods(item?.text || item?.content || ''))
      .filter(Boolean);
    const recentSet = new Set(recentTexts);
    const customCards = readDreamReplyCards(dreamId)
      .map((line) => String(line || '').trim())
      .filter(Boolean);
    const customCardChance = customCards.length > 100 ? 0.4 : customCards.length > 30 ? 0.2 : 0;
    if (customCardChance > 0 && Math.random() < customCardChance) {
      const availableCards = customCards.filter((line) => !recentSet.has(stripIxPeriods(line)));
      if (availableCards.length) {
        return availableCards[Math.floor(Math.random() * availableCards.length)];
      }
    }
    const category = proactiveContextCategory(latestUserTextForProactive(dreamId, state));
    const contextual = ixContextProactiveMessages[category] || [];
    const pool = contextual.length && Math.random() < 0.7 ? contextual : ixProactiveMessages;
    return pool[Math.floor(Math.random() * pool.length)] || '';
  }

  function proactiveDreamKey(dream) {
    return dream?.id ? `single:${dream.id}` : '';
  }

  function readProactiveCooldowns(storageKey = proactiveCooldownKey) {
    return readJson(storageKey, {});
  }

  function writeProactiveCooldown(key, time = Date.now(), storageKey = proactiveCooldownKey) {
    if (!key) return;
    const cooldowns = readProactiveCooldowns(storageKey);
    cooldowns[key] = time;
    writeJson(storageKey, cooldowns);
  }

  function isInProactiveCooldown(key, nowTime = Date.now(), cooldownMs = proactiveCooldownMs, storageKey = proactiveCooldownKey) {
    const last = Number(readProactiveCooldowns(storageKey)[key] || 0);
    return last && nowTime - last < cooldownMs;
  }

  function randomBetween(min, max) {
    return min + Math.floor(Math.random() * Math.max(1, max - min + 1));
  }

  function isProactiveTestMode() {
    return localStorage.getItem(proactiveTestModeKey) === '1';
  }

  function proactiveDebugLog(label, payload = {}) {
    if (!isProactiveTestMode()) return;
    console.log(label, payload);
  }

  function isInSpecificSingleChat(state = readState()) {
    return requireActiveConversation(state)?.kind === 'single';
  }

  function nextProactiveDelay() {
    if (isProactiveTestMode()) return randomBetween(proactiveTestMinDelayMs, proactiveTestMaxDelayMs);
    if (isInSpecificSingleChat()) return randomBetween(proactiveSingleChatNextMinDelayMs, proactiveSingleChatNextMaxDelayMs);
    return randomBetween(proactiveAwayNextMinDelayMs, proactiveAwayNextMaxDelayMs);
  }

  function nextProactiveRetryDelay() {
    if (isProactiveTestMode()) return randomBetween(proactiveTestMinDelayMs, proactiveTestMaxDelayMs);
    return randomBetween(proactiveRetryMinDelayMs, proactiveRetryMaxDelayMs);
  }

  function readNextProactiveAt() {
    return Number(localStorage.getItem(proactiveNextAtKey) || 0);
  }

  function writeNextProactiveAt(delay = nextProactiveDelay()) {
    const nextAt = Date.now() + delay;
    localStorage.setItem(proactiveNextAtKey, String(nextAt));
    proactiveDebugLog('[PROACTIVE_NEXT]', {
      delaySeconds: Math.round(delay / 1000),
      nextAt
    });
    return nextAt;
  }

  function readLastProactiveDreamId() {
    return localStorage.getItem(proactiveLastDreamKey) || '';
  }

  function writeLastProactiveDreamId(dreamId) {
    if (dreamId) localStorage.setItem(proactiveLastDreamKey, dreamId);
  }

  function canRunCurrentChatProactiveCheck() {
    if (document.hidden) return false;
    if (document.body.dataset.xPage !== 'message') return false;
    if (!activeThread.type) return false;
    const state = readState();
    const active = requireActiveConversation(state);
    if (active?.kind !== 'single' || !active.dream) return false;
    const panel = $('#xMessagePanel');
    const chat = $('#ixChat');
    if (!panel?.classList.contains('show') && !panel?.classList.contains('x-clean-active')) return false;
    if (!chat || chat.style.display === 'none') return false;
    if (Date.now() - lastUserMessageAt < currentChatProactiveAfterUserPauseMs) return false;
    return true;
  }

  async function requestCloudProactiveReply(dream, state = readState(), trigger = 'current') {
    const cardReplyContext = createSingleCardReplyContext(
      { kind: 'single', dream },
      createXId('proactive'),
      Date.now(),
      state
    );
    if (!cardReplyContext) return null;
    const initialScope = validateLiveSingleCardReplyContext(cardReplyContext, {
      state,
      sourceMessageRequired: false
    });
    if (!initialScope.ok) return null;
    const dreamId = cardReplyContext.dreamId;
    const requestKey = `${cardReplyContext.ownerId}:${dreamId}`;
    if (proactiveReplyInFlight.has(requestKey)) return proactiveReplyInFlight.get(requestKey);
    const request = (async () => {
    try {
      const app = await getXChatCloudReplyApp();
      const result = await app.callFunction({
        name: 'shexXChatReply',
        data: {
          action: 'proactiveReply',
          userId: cardReplyContext.ownerId,
          dreamId,
          userName: cardReplyContext.userCall,
          recentMessages: messagesForProactiveDream(dreamId, state).slice(-30),
          trigger: trigger === 'background' ? 'background' : 'current',
          requestId: cardReplyContext.requestId,
          conversationKey: cardReplyContext.conversationKey,
          chatType: cardReplyContext.conversationType
        }
      });
      const data = result?.result || result;
      if (data?.ok && data?.sent && data?.content) {
        const liveScope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
        const responseScope = window.SHEXCardReplyContext.validateResponse(cardReplyContext, data);
        if (!liveScope.ok || !responseScope.ok) {
          proactiveDebugLog('[PROACTIVE_SKIP]', {
            reason: liveScope.ok ? responseScope.reason : liveScope.reason,
            dreamId,
            trigger
          });
          return null;
        }
        return Object.freeze({ ...data, cardReplyContext });
      }
      if (data?.ok && data?.code === 'PROACTIVE_COOLDOWN') {
        const liveScope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
        if (!liveScope.ok) return null;
        const key = proactiveDreamKey(dream);
        const cooldownUntil = Number(data.cooldownUntil || 0);
        const lastSentAt = cooldownUntil > Date.now()
          ? Math.max(0, cooldownUntil - proactiveCooldownMs)
          : Date.now();
        writeProactiveCooldown(key, lastSentAt);
        writeProactiveCooldown(key, lastSentAt, currentChatProactiveCooldownKey);
      }
      proactiveDebugLog('[PROACTIVE_SKIP]', { reason: data?.code || 'cloud-no-reply', dreamId, trigger });
      return null;
    } catch (error) {
      proactiveDebugLog('[PROACTIVE_SKIP]', { reason: 'cloud-error', dreamId, trigger, error: String(error?.message || error || '') });
      return null;
    }
    })();
    proactiveReplyInFlight.set(requestKey, request);
    try {
      return await request;
    } finally {
      if (proactiveReplyInFlight.get(requestKey) === request) proactiveReplyInFlight.delete(requestKey);
    }
  }

  async function confirmCloudProactiveDelivery(reply) {
    const cardReplyContext = window.SHEXCardReplyContext?.restore?.(reply?.cardReplyContext) || null;
    const scope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
    const dreamId = cardReplyContext?.dreamId || '';
    const requestId = String(reply?.requestId || '').trim();
    if (!scope.ok || !dreamId || !requestId) return false;
    try {
      const app = await getXChatCloudReplyApp();
      const result = await app.callFunction({
        name: 'shexXChatReply',
        data: {
          action: 'confirmProactiveDelivery',
          userId: cardReplyContext.ownerId,
          dreamId,
          trigger: reply?.trigger === 'background' ? 'background' : 'current',
          requestId
        }
      });
      const data = result?.result || result;
      if (data?.ok) return true;
      proactiveDebugLog('[PROACTIVE_DELIVERY_CONFIRM_SKIP]', { reason: data?.code || 'cloud-no-confirm', dreamId, requestId });
    } catch (error) {
      proactiveDebugLog('[PROACTIVE_DELIVERY_CONFIRM_SKIP]', {
        reason: 'cloud-error',
        dreamId,
        requestId,
        error: String(error?.message || error || '')
      });
    }
    return false;
  }

  async function sendCurrentChatProactiveMessage() {
    if (!canRunCurrentChatProactiveCheck()) return false;
    const state = readState();
    const active = requireActiveConversation(state);
    const dream = active?.dream;
    if (!dream) return false;
    const key = proactiveDreamKey(dream);
    const nowTime = Date.now();
    if (!key || isInProactiveCooldown(key, nowTime, currentChatProactiveCooldownMs, currentChatProactiveCooldownKey)) return false;
    if (Math.random() >= currentChatProactiveChance) return false;
    const reply = await requestCloudProactiveReply(dream, state, 'current');
    if (!reply || !addProactiveMessageToSingleChat(reply.cardReplyContext, reply)) return false;
    writeProactiveCooldown(key, Date.now(), currentChatProactiveCooldownKey);
    writeProactiveCooldown(key);
    void confirmCloudProactiveDelivery(reply);
    return true;
  }

  function runCurrentChatProactiveCheck() {
    const state = readState();
    const active = requireActiveConversation(state);
    if (!active?.dream || !proactiveMessageSourceForDream(active.dream)) return;
    void sendCurrentChatProactiveMessage();
  }

  function isXMessageListPage() {
    return location.hash === '#x-message-chat' && !activeThread.type;
  }

  function canRunBackgroundProactiveCheck() {
    if (document.hidden) return false;
    if (Date.now() < xMessageRouteTransitionUntil) return false;
    if (!xHasLoggedInUser()) return false;
    if (Date.now() - lastUserMessageAt < proactiveAfterUserPauseMs) return false;
    const state = readState();
    return Array.isArray(state.dreams) && state.dreams.some((dream) => dream?.id);
  }

  function proactiveBackgroundCandidates(state = readState()) {
    const active = requireActiveConversation(state);
    const activeSingleDreamId = active?.kind === 'single' && active.dream ? active.dream.id : '';
    const nowTime = Date.now();
    return (state.dreams || [])
      .filter((dream) => dream?.id)
      .filter((dream) => Boolean(proactiveMessageSourceForDream(dream)))
      .filter((dream) => dream.id !== activeSingleDreamId)
      .filter((dream) => !isInProactiveCooldown(proactiveDreamKey(dream), nowTime, proactiveCooldownMs));
  }

  function markProactiveUnread(dreamId) {
    const key = 'shex_x_message_proactive_unread_v1';
    const data = readJson(key, {});
    data[dreamId] = Date.now();
    writeJson(key, data);
  }

  function clearProactiveUnread(dreamId) {
    const key = 'shex_x_message_proactive_unread_v1';
    const data = readJson(key, {});
    delete data[dreamId];
    writeJson(key, data);
  }

  function getProactiveUnreadSet() {
    const key = 'shex_x_message_proactive_unread_v1';
    const data = readJson(key, {});
    return new Set(Object.keys(data));
  }

  function addProactiveMessageToSingleChat(contextValue, reply = {}) {
    const cardReplyContext = window.SHEXCardReplyContext?.restore?.(contextValue) || null;
    const scope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
    if (!scope.ok) return false;
    const state = readState();
    const dream = dreamById(cardReplyContext.dreamId, state);
    const sourceReply = typeof reply === 'string' ? { content: reply } : reply;
    if (!dream?.id || !String(sourceReply?.content || sourceReply?.text || '').trim()) return false;
    const delivery = prepareReplyForDelivery(sourceReply, cardReplyContext.conversationKey, cardReplyContext.dreamId);
    if (!delivery.reply) return delivery.blocked;
    const text = String(delivery.reply.content || delivery.reply.text || '').trim();
    const sticker = String(delivery.reply.sticker || '').trim();
    if (!text && !sticker) return delivery.blocked;
    const message = {
      id: createXId('proactive-message'),
      role: 'ta',
      senderId: dream.id,
      dreamCharacterId: dream.id,
      senderName: dream.name,
      text: text || '表情包',
      ...(sticker ? { sticker } : {}),
      ...replySourceFields(delivery.reply),
      messageType: 'proactive',
      time: Date.now(),
      createdAt: Date.now()
    };
    isWritingProactiveMessage = true;
    if (proactiveWriteProtectionTimer) window.clearTimeout(proactiveWriteProtectionTimer);
    updateState((draft) => {
      if (!draft.singleChats) draft.singleChats = {};
      if (!Array.isArray(draft.singleChats[dream.id])) draft.singleChats[dream.id] = [];
      draft.singleChats[dream.id].push(message);
    });
    markProactiveUnread(dream.id);
    proactiveWriteProtectionTimer = window.setTimeout(() => {
      isWritingProactiveMessage = false;
      proactiveWriteProtectionTimer = null;
    }, 1500);
    const active = requireActiveConversation();
    if (active?.kind === 'single' && active.dream?.id === dream.id) {
      requestChatMessageReconciliation(`single:${dream.id}`, [message.id], 'proactive-message');
    }
    return true;
  }

  async function sendBackgroundProactiveMessage(dream, state = readState()) {
    const key = proactiveDreamKey(dream);
    if (!key) return false;
    const reply = await requestCloudProactiveReply(dream, state, 'background');
    if (!reply || !addProactiveMessageToSingleChat(reply.cardReplyContext, reply)) {
      writeNextProactiveAt(nextProactiveRetryDelay());
      return false;
    }
    const nowTime = Date.now();
    writeProactiveCooldown(key, nowTime);
    writeProactiveCooldown(key, nowTime, currentChatProactiveCooldownKey);
    writeLastProactiveDreamId(dream.id);
    writeNextProactiveAt(nextProactiveDelay());
    void confirmCloudProactiveDelivery(reply);
    proactiveDebugLog('[PROACTIVE_SENT]', {
      dreamId: dream.id,
      dreamName: dream.name
    });
    return true;
  }

  async function runBackgroundProactiveMessageCheck() {
    if (!canRunBackgroundProactiveCheck()) {
      const dueAt = readNextProactiveAt();
      if (!dueAt || Date.now() >= dueAt) writeNextProactiveAt(nextProactiveRetryDelay());
      return false;
    }
    const dueAt = readNextProactiveAt();
    if (dueAt && Date.now() < dueAt) return false;
    const state = readState();
    const active = requireActiveConversation(state);
    if (active?.kind === 'single' && !isProactiveTestMode() && Math.random() >= 0.5) {
      writeNextProactiveAt(nextProactiveDelay());
      proactiveDebugLog('[PROACTIVE_SKIP]', { reason: 'single_chat_probability' });
      return true;
    }
    let candidates = proactiveBackgroundCandidates(state);
    const lastDreamId = readLastProactiveDreamId();
    if (candidates.length > 1 && lastDreamId) {
      const withoutLast = candidates.filter((dream) => dream.id !== lastDreamId);
      if (withoutLast.length) candidates = withoutLast;
    }
    if (!candidates.length) {
      writeNextProactiveAt(nextProactiveRetryDelay());
      proactiveDebugLog('[PROACTIVE_SKIP]', { reason: 'no_candidate' });
      return true;
    }
    const dream = candidates[Math.floor(Math.random() * candidates.length)];
    return await sendBackgroundProactiveMessage(dream, state);
  }

  function runProactiveMessageCheck() {
    runCurrentChatProactiveCheck();
    void runBackgroundProactiveMessageCheck();
  }

  function scheduleBackgroundProactiveTimer() {
    if (proactiveTimer) window.clearTimeout(proactiveTimer);
    let nextAt = readNextProactiveAt();
    if (!nextAt || nextAt < Date.now() - proactiveRetryMaxDelayMs) nextAt = writeNextProactiveAt(nextProactiveDelay());
    const delay = Math.max(1000, nextAt - Date.now());
    proactiveTimer = window.setTimeout(() => {
      proactiveTimer = null;
      void Promise.resolve(runBackgroundProactiveMessageCheck()).finally(scheduleBackgroundProactiveTimer);
    }, delay);
  }

  function stopCurrentChatProactiveTimer() {
    if (currentChatProactiveTimer) {
      window.clearInterval(currentChatProactiveTimer);
      currentChatProactiveTimer = null;
    }
  }

  function restartCurrentChatProactiveTimer() {
    stopCurrentChatProactiveTimer();
    if (location.hash === '#x-message-chat' && activeThread.type && !document.hidden) {
      ensureProactiveMessageTimer();
    }
  }

  function ensureBackgroundProactiveTimer() {
    if (!proactiveVisibilityListenerBound) {
      proactiveVisibilityListenerBound = true;
      document.addEventListener('visibilitychange', () => {
        if (document.hidden) {
          stopCurrentChatProactiveTimer();
          return;
        }
        ensureBackgroundProactiveTimer();
        if (location.hash === '#x-message-chat' && activeThread.type) ensureProactiveMessageTimer();
        window.setTimeout(runCurrentChatProactiveCheck, 1200);
        window.setTimeout(() => {
          if (!xHasLoggedInUser()) return;
          void Promise.resolve(runBackgroundProactiveMessageCheck()).finally(scheduleBackgroundProactiveTimer);
        }, 1600);
      });
    }
    if (document.hidden || !xHasLoggedInUser()) return;
    if (!proactiveTimer) scheduleBackgroundProactiveTimer();
  }

  function ensureProactiveMessageTimer() {
    ensureBackgroundProactiveTimer();
    if (document.hidden || location.hash !== '#x-message-chat' || !activeThread.type) return;
    if (!currentChatProactiveTimer) {
      currentChatProactiveTimer = window.setInterval(runCurrentChatProactiveCheck, currentChatProactiveIntervalMs);
    }
  }

  function formatDividerTime(value) {
    const timestamp = normalizeChatTimestampValue(value);
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return `${date.getMonth() + 1}月${date.getDate()}日 ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
  }

