    const expectedOwnerId=String(scope.ownerId||window.SHEXAuth?.current?.()?.userId||'');
    const current=activeChatAppearanceScope();if(!expectedOwnerId||!current||String(current.ownerId)!==expectedOwnerId||String(current.scopeType)!==String(scope.scopeType)||String(current.scopeId)!==String(scope.scopeId))return false;
    const background=normalizeBackgroundMedia(prepared.value?.background);if(!background){clearRenderedChatBackground();return true;}
    if(background.mediaType==='video'||!prepared.localBackgroundUrl||!prepared.decodedImage)return false;
    const target=$('#ixChat')||$('#ixLog');if(!target)return false;
    const mediaModule=window.SHEXBackgroundMedia;
    if(typeof mediaModule?.prepareReusableDecodedCandidate!=='function'||typeof mediaModule?.commitCandidate!=='function'||typeof mediaModule?.disposeCandidate!=='function')return false;
    const runtimeIdentity=chatBackgroundRuntimeIdentity(),chatKey=chatBackgroundKeyForActive(),requestIdentity=backgroundMediaIdentity(background);
    const existingLayer=target.querySelector(':scope > .shex-background-media-layer'),existingImage=existingLayer?.querySelector('img')||null;
    const existingSource=String(existingImage?.getAttribute?.('src')||existingImage?.currentSrc||'').trim();
