    const committedLayer=target.querySelector(':scope > .shex-background-media-layer'),committedImage=committedLayer?.querySelector('img')||null;
    const committedSource=String(committedImage?.getAttribute?.('src')||committedImage?.currentSrc||'').trim();
    if(!committedLayer||committed.layer!==committedLayer||!committedImage||!committedSource)return false;
