    if(navigationSerial!==chatAppearanceNavigationSerial)return false;
    const current=activeChatAppearanceScope();if(!current||String(current.ownerId)!==String(scope.ownerId)||String(current.scopeType)!==String(scope.scopeType)||String(current.scopeId)!==String(scope.scopeId))return false;
