      if(!snapshot||!completeAppearanceRevisionIsConfirmed(revision)){hot.remove(identity,'complete_runtime_unconfirmed');return false;}
      if(String(snapshot?.scope?.scopeType||'')!==String(scope.scopeType)||String(snapshot?.scope?.scopeId||'')!==String(scope.scopeId)){hot.remove(identity,'complete_runtime_scope_mismatch');return false;}
