  function syncCharacterAISettings(mask, active = requireActiveConversation()) {
    if (!mask) return;
    if (!active) {
      $('#xCharacterAIModeGroup', mask)?.remove();
      return;
    }
    syncReplyTimingSettingsVisibility(mask, active);
    syncCharacterAIInjectionViewerSettings(mask, active);
    syncCharacterAIMemberMemorySettings(mask, active);
    syncCharacterAIAdminManagerSettings(mask, active);
    syncCharacterAIStreamProbeSettings(mask, active);
    let group = $('#xCharacterAIModeGroup', mask);
    const api = window.SHEXCharacterAI;
    const modelTierPreview = xIsAIModelTierPreview();
    const isWorldRunChat = active.kind === 'world_run' && Boolean(active.worldRun?.runId);
    const access = characterAIAccessForConversation(active);
    const canUseCharacterAI = access.canUseAI;
    const selected = isWorldRunChat
      ? 'ai'
      : canUseCharacterAI && api
        ? modelTierPreview ? 'ai' : api.effectiveReplyMode(active.dream, true)
        : 'library';
    const canUseAIControls = !isWorldRunChat && access.canConfigureAIModes && selected === 'ai';
    const canUseModelControls = selected === 'ai' && (access.canSelectModel || modelTierPreview);
    const canUseImmersive = canUseChatImmersiveMode(active);
    const settingsId = chatImmersiveIdentity(active);
    const canRender = Boolean(api && settingsId && ['single', 'world_run'].includes(active.kind)
      && (isWorldRunChat || canUseImmersive || canUseAIControls || canUseModelControls));
    if (!canRender) {
      group?.remove();
      return;
    }
    if (!group) {
      group = document.createElement('div');
      group.className = 'ix-setting-group x-character-ai-mode-group';
      group.id = 'xCharacterAIModeGroup';
      group.innerHTML = `
        <div class="x-character-ai-setting-row" data-chat-immersive-row>
          <strong>沉浸式模式</strong>
          <div class="x-character-ai-mode-options" role="group" aria-label="沉浸式模式">
            <button type="button" data-chat-immersive-mode="on">开启</button>
            <button type="button" data-chat-immersive-mode="off">关闭</button>
          </div>
        </div>
        <div class="x-character-ai-setting-row x-character-ai-action-row" data-character-online-row hidden>
          <strong>线上模式</strong>
          <div class="x-character-ai-mode-options" role="group" aria-label="线上模式">
            <button type="button" data-character-online-mode="on">开</button>
            <button type="button" data-character-online-mode="off">关</button>
          </div>
        </div>
        <div class="x-character-ai-setting-row x-character-ai-action-row" data-character-longform-row hidden>
          <strong>长文模式</strong>
          <div class="x-character-ai-mode-options" role="group" aria-label="长文模式">
            <button type="button" data-character-longform-mode="on">开</button>
            <button type="button" data-character-longform-mode="off">关</button>
          </div>
        </div>
        <div class="x-character-ai-model-section" data-character-model-section hidden>
          <div class="x-character-ai-model-heading">
            <span class="x-character-ai-model-current-label">当前模型：<strong class="x-character-ai-model-current" data-character-model-current></strong></span>
            <button class="x-character-ai-model-toggle" type="button" data-character-model-toggle aria-label="切换模型" aria-expanded="false">切换</button>
          </div>
          <div class="x-character-ai-model-options-panel" data-character-model-options hidden>
            <div class="x-character-ai-model-page-heading">
              <strong data-character-model-page-title>推荐模型</strong>
              <span data-character-model-page-count>1/1</span>
            </div>
            <div class="x-character-ai-model-viewport" data-character-model-viewport tabindex="0" aria-label="模型选择，左右滑动查看下一页">
              <div class="x-character-ai-model-grid" data-character-model-grid></div>
            </div>
            <div class="x-character-ai-model-pager" aria-label="模型分页">
              <button type="button" data-character-model-page-direction="previous" aria-label="上一页">‹</button>
              <div class="x-character-ai-model-dots" data-character-model-page-dots></div>
              <button type="button" data-character-model-page-direction="next" aria-label="下一页">›</button>
            </div>
          </div>
        </div>
        <p class="x-character-ai-cost-note" data-character-ai-cost-note hidden></p>
      `;
      const dreamGroup = $('#xDreamManageGroup', mask);
      if (dreamGroup) dreamGroup.insertAdjacentElement('afterend', group);
      else mask.querySelector('.ix-settings-sheet')?.appendChild(group);
      group.addEventListener('click', async (event) => {
        const immersiveButton = event.target.closest?.('[data-chat-immersive-mode]');
        const onlineButton = event.target.closest?.('[data-character-online-mode]');
        const longformButton = event.target.closest?.('[data-character-longform-mode]');
        const modelButton = event.target.closest?.('[data-character-model-tier]');
        const modelToggle = event.target.closest?.('[data-character-model-toggle]');
        const modelPageDirection = event.target.closest?.('[data-character-model-page-direction]');
        const modelPageIndex = event.target.closest?.('[data-character-model-page-index]');
        if (!immersiveButton && !onlineButton && !longformButton && !modelButton && !modelToggle && !modelPageDirection && !modelPageIndex) return;
        const currentActive = requireActiveConversation();
        if (!currentActive) {
          mask.classList.remove('show');
          showChatToast('请先进入一个聊天');
          return;
        }
        if (immersiveButton && !canUseChatImmersiveMode(currentActive)) {
          group.remove();
          return;
        }
        // X103：模拟器强制长文（请求构造固定 promptContract 'L'）。设置项只展示“开”，点“关”只提示，不写任何设置。
        if (longformButton && currentActive.kind === 'world_run') {
          if (longformButton.dataset.characterLongformMode !== 'on') showChatToast('长文模式是模拟器必须开启的模式');
          syncCharacterAISettings(mask, currentActive);
          return;
        }
        const currentAccess = characterAIAccessForConversation(currentActive);
        const isModelControl = Boolean(modelButton || modelToggle || modelPageDirection || modelPageIndex);
        if (isModelControl && !currentAccess.canSelectModel && !xIsAIModelTierPreview()) return;
        if (!immersiveButton && !isModelControl && !currentAccess.canConfigureAIModes) return;
        // X103：模拟器存档没有梦角对象，必须按会话判断（否则非管理员在模拟器里点切换模型没有反应）。
        if (!immersiveButton && !currentAccess.canUseAI) return;
        if (longformButton && !xIsAdminUser()) return;
        const settingsId = String(group.dataset.settingsId || '');
        const dreamId = String(group.dataset.dreamId || '');
        if (!settingsId) return;
        if (modelToggle) {
          const expanded = modelToggle.getAttribute('aria-expanded') !== 'true';
          modelToggle.setAttribute('aria-expanded', expanded ? 'true' : 'false');
          modelToggle.setAttribute('aria-label', expanded ? '收起模型选择' : '切换模型');
          group.querySelector('[data-character-model-options]')?.toggleAttribute('hidden', !expanded);
          if (expanded) requestAnimationFrame(() => scrollCharacterAIModelPage(group, 0, 'auto'));
          return;
        }
        if (modelPageDirection || modelPageIndex) {
          const currentPage = Number(group.dataset.characterModelPage || 0);
          const nextPage = modelPageIndex
            ? Number(modelPageIndex.dataset.characterModelPageIndex || 0)
            : currentPage + (modelPageDirection.dataset.characterModelPageDirection === 'next' ? 1 : -1);
          scrollCharacterAIModelPage(group, nextPage);
          return;
        }
        // X103：模拟器七款开放模型可供普通用户选择；会员锁只保留在普通聊天。
        if (modelButton && !characterAIAccessForConversation(requireActiveConversation()).isWorldRun
          && !characterAIModelAllowed(modelButton.dataset.characterModelTier)) {
          showChatToast('该模型为会员专享，升级 Plus / Pro / Ultra 后可使用');
          return;
        }
        if (modelButton && xIsAIModelTierPreview() && !characterAIAccessForConversation(requireActiveConversation()).canSelectModel) {
          const previewTier = api.normalizeModelTier(modelButton.dataset.characterModelTier);
          group.dataset.previewModelTier = previewTier;
          syncCharacterAISettings(mask, requireActiveConversation());
          showChatToast(`预览：已切换为${api.modelTier(previewTier).name}`);
          return;
        }
        if (immersiveButton) {
          const enabled = immersiveButton.dataset.chatImmersiveMode === 'on';
          if (!writeChatImmersiveMode(settingsId, enabled)) {
            showChatToast('沉浸式模式保存失败，请稍后重试');
            return;
          }
          syncCharacterAISettings(mask, requireActiveConversation());
          requestFullChatRender({ reason: 'immersive-mode-toggle', preserveRenderLimit: true });
          await syncUserDataAfterResourceChange(enabled ? '沉浸式模式已开启' : '沉浸式模式已关闭');
          return;
        }
        const nextOnlineMode = onlineButton ? onlineButton.dataset.characterOnlineMode === 'on' : null;
        const nextLongformMode = longformButton ? longformButton.dataset.characterLongformMode === 'on' : null;
        const nextModelTier = modelButton && characterAIAccessForConversation(requireActiveConversation()).canSelectModel
          ? api.normalizeModelTier(modelButton.dataset.characterModelTier)
          : '';
        if (modelButton && currentActive.kind === 'world_run') {
          if (!writeWorldRunAIModelTier(currentActive.worldRun?.runId, nextModelTier)) {
            showChatToast('模型档位保存失败，请稍后重试');
            return;
          }
          syncCharacterAISettings(mask, requireActiveConversation());
          const toggle = group.querySelector('[data-character-model-toggle]');
          toggle?.setAttribute('aria-expanded', 'false');
          toggle?.setAttribute('aria-label', '切换模型');
          group.querySelector('[data-character-model-options]')?.setAttribute('hidden', '');
          await syncUserDataAfterResourceChange(`已切换为${api.modelTier(nextModelTier).name}，将从下一条新消息生效`);
          return;
        }
        const saved = updateState((draft) => {
          const dream = draft.dreams?.find((item) => String(item?.id || '') === dreamId);
          if (!dream) return draft;
          if (onlineButton) dream.aiOnlineMode = nextOnlineMode;
          if (longformButton) dream.aiLongformMode = nextLongformMode;
          if (nextModelTier) dream.aiModelTier = nextModelTier;
          dream.updatedAt = Date.now();
          window.SHEXCharacterProfileSync?.touchGroup?.(dream, 'instanceSettings', dream.updatedAt);
          return draft;
        });
        if (!saved) {
          const failureMessage = modelButton
              ? '模型档位保存失败，请稍后重试'
              : longformButton
                ? '长文模式保存失败，请稍后重试'
                : '线上模式保存失败，请稍后重试';
          showChatToast(failureMessage);
          return;
        }
        syncCharacterAISettings(mask, requireActiveConversation());
        if (modelButton) {
          const toggle = group.querySelector('[data-character-model-toggle]');
          toggle?.setAttribute('aria-expanded', 'false');
          toggle?.setAttribute('aria-label', '切换模型');
          group.querySelector('[data-character-model-options]')?.setAttribute('hidden', '');
        }
        const successMessage = modelButton ? `已切换为${api.modelTier(nextModelTier).name}，将从下一条新消息生效`
            : longformButton
              ? nextLongformMode ? '长文模式已开启' : '长文模式已关闭'
              : nextOnlineMode ? '线上模式已开启' : '线上模式已关闭';
        await syncUserDataAfterResourceChange(successMessage);
      });
    }
    group.dataset.settingsId = settingsId;
    group.dataset.dreamId = String(active.dream?.id || '');
    group.dataset.worldRunId = String(active.worldRun?.runId || '');
    const immersiveRow = group.querySelector('[data-chat-immersive-row]');
    if (immersiveRow) immersiveRow.hidden = !canUseImmersive;
    const immersiveMode = isChatImmersiveEnabled(active) ? 'on' : 'off';
    group.querySelectorAll('[data-chat-immersive-mode]').forEach((button) => {
      const activeButton = button.dataset.chatImmersiveMode === immersiveMode;
      button.classList.toggle('is-active', activeButton);
      button.setAttribute('aria-pressed', activeButton ? 'true' : 'false');
    });
    const onlineRow = group.querySelector('[data-character-online-row]');
    if (onlineRow) onlineRow.hidden = !canUseAIControls;
    const longformRow = group.querySelector('[data-character-longform-row]');
    if (longformRow) longformRow.hidden = isWorldRunChat ? false : (!canUseAIControls || !xIsAdminUser());
    // 模拟器顺序：长文模式 → 沉浸式模式 → 当前模型；普通聊天恢复原顺序（沉浸式 → 线上 → 长文）。
    if (longformRow && immersiveRow && onlineRow) {
      if (isWorldRunChat) { if (longformRow.nextElementSibling !== immersiveRow) group.insertBefore(longformRow, immersiveRow); }
      else if (onlineRow.nextElementSibling !== longformRow) onlineRow.insertAdjacentElement('afterend', longformRow);
    }
    const costNote = group.querySelector('[data-character-ai-cost-note]');
    const selectedTier = modelTierPreview && group.dataset.previewModelTier
      ? api.modelTier(group.dataset.previewModelTier)
      : isWorldRunChat ? worldRunAIModelTier(active) : characterAIModelTier(active.dream);
    const replyPricing = worldRunReplyPricing(active);
    if (costNote) {
      costNote.hidden = !canUseAIControls;
      costNote.textContent = replyPricing.priceReady
        ? `当前为${selectedTier.name}，每次文字回复消耗 ${api.modelReplyEnergy(selectedTier.id, replyPricing)} X能量`
        : '正在确认当前世界版本的回复价格';
    }
    const activeDream = active.dream || {};
    const onlineMode = Object.prototype.hasOwnProperty.call(activeDream, 'aiOnlineMode')
      ? activeDream.aiOnlineMode === true ? 'on' : 'off'
      : activeDream.aiActionMode === false ? 'on' : 'off';
    group.querySelectorAll('[data-character-online-mode]').forEach((button) => {
      const activeButton = button.dataset.characterOnlineMode === onlineMode;
      button.classList.toggle('is-active', activeButton);
      button.setAttribute('aria-pressed', activeButton ? 'true' : 'false');
    });
    const longformMode = isWorldRunChat || activeDream.aiLongformMode === true ? 'on' : 'off';
    group.querySelectorAll('[data-character-longform-mode]').forEach((button) => {
      const activeButton = button.dataset.characterLongformMode === longformMode;
      button.classList.toggle('is-active', activeButton);
      button.setAttribute('aria-pressed', activeButton ? 'true' : 'false');
    });
    const modelSection = group.querySelector('[data-character-model-section]');
    if (modelSection) {
      modelSection.hidden = !canUseModelControls;
      const currentModel = group.querySelector('[data-character-model-current]');
      if (currentModel) currentModel.textContent = selectedTier.modelLabel;
      const modelGrid = group.querySelector('[data-character-model-grid]');
      const modelListKind = isWorldRunChat ? 'world_run' : 'character';
      if (modelGrid && (!modelGrid.children.length || modelGrid.dataset.modelListKind !== modelListKind)) {
        modelGrid.dataset.modelListKind = modelListKind;
        const modelPages = api.modelSelectionPages({ worldRun: isWorldRunChat });
        modelGrid.innerHTML = modelPages.map((modelPage, pageIndex) => `
          <section class="x-character-ai-model-page" data-character-model-page="${pageIndex}" data-character-model-page-title="${escapeHtml(modelPage.title)}" aria-label="${escapeHtml(modelPage.title)}">
            <div class="x-character-ai-model-page-grid">
              ${modelPage.models.map((tier) => `
                <button type="button" data-character-model-tier="${escapeHtml(tier.id)}">
                  <span class="x-character-ai-model-title"><strong>${escapeHtml(tier.name)}</strong>${modelPage.kind === 'recommended' ? '<em>推荐</em>' : ''}<em class="x-character-ai-member-badge" data-character-model-member-badge hidden>会员</em><b data-character-model-price>${replyPricing.priceReady ? `${api.modelReplyEnergy(tier.id, replyPricing)} X` : '确认中'}</b></span>
                  <span class="x-character-ai-model-meta">${(tier.labels || []).map((label) => `<span>${escapeHtml(label)}</span>`).join('')}</span>
                </button>
              `).join('')}
            </div>
          </section>
        `).join('');
        const dots = group.querySelector('[data-character-model-page-dots]');
        if (dots) dots.innerHTML = modelPages.map((modelPage, pageIndex) => `
          <button type="button" data-character-model-page-index="${pageIndex}" aria-label="第${pageIndex + 1}页：${escapeHtml(modelPage.title)}"></button>
        `).join('');
        bindCharacterAIModelPager(group);
        syncCharacterAIModelPager(group, 0);
      }
      modelGrid?.querySelectorAll('[data-character-model-tier]').forEach((button) => {
        const price = button.querySelector('[data-character-model-price]');
        if (price) price.textContent = replyPricing.priceReady
          ? `${api.modelReplyEnergy(button.dataset.characterModelTier, replyPricing)} X` : '确认中';
        const modelAllowed = isWorldRunChat
          ? api.isWorldRunModelAllowed(button.dataset.characterModelTier)
          : characterAIModelAllowed(button.dataset.characterModelTier);
        const activeButton = modelAllowed && button.dataset.characterModelTier === selectedTier.id;
        button.classList.toggle('is-member-locked', !modelAllowed);
        button.setAttribute('aria-disabled', modelAllowed ? 'false' : 'true');
        button.classList.toggle('is-active', activeButton);
        button.setAttribute('aria-pressed', activeButton ? 'true' : 'false');
        const memberBadge = button.querySelector('[data-character-model-member-badge]');
        if (memberBadge) memberBadge.hidden = modelAllowed;
      });
    }
  }

