        const form = event.currentTarget;
        const note = String(form.elements.note?.value || '').trim();
        const submit = form.querySelector('[type="submit"]');
        if (!source || !note || !submit || submit.disabled) return;
        const api = characterRegistryClient();
        if (!api?.submitCharacterReport) { showChatToast('举报暂时不可用'); return; }
        submit.disabled = true;
        try {
          await api.submitCharacterReport({ ...source, category: form.elements.category?.value || 'other', note });
          form.reset();
          form.hidden = true;
          showChatToast('举报已提交，管理员会核对处理');
        } catch (error) { showChatToast(error?.message || '举报提交失败，请稍后重试'); }
        finally { submit.disabled = false; }
