  function buildActionGiftMessage(kind, itemId, sender, receiver) {
    const list = kind === 'gift' ? ixActionGiftItems.gifts : ixActionGiftItems.actions;
    const item = list.find((entry) => entry.id === itemId) || list[0];
    return item?.text(sender, receiver) || '';
  }

  async function pickReplyWithSourceMix(dreamId, exclusivePool, options = {}) {
    const pickFromExclusive = () => {
      const pool = Array.isArray(exclusivePool) ? exclusivePool : [];
      const line = pool.length ? pool[Math.floor(Math.random() * pool.length)] : '';
      return line ? { text: stripIxPeriods(line), ...systemReplySource(line, 'action_reply', 'action_reply') } : null;
    };
    const pickFromCards = () => {
      const cards = readDreamReplyCards(dreamId || '').map((line) => String(line || '').trim()).filter(Boolean);
      const line = cards.length ? cards[Math.floor(Math.random() * cards.length)] : '';
      return line ? { text: stripIxPeriods(line), ...userCardReplySource(line) } : null;
    };
    const pickFromCloud = async () => {
      try {
        const app = await getXChatCloudReplyApp();
        const result = await app.callFunction({
          name: 'shexXChatReply',
          data: {
            action: 'pickCategoryReply',
            userId: options.ownerId || currentXUser()?.userId || '',
            dreamId: dreamId || ''
          }
        });
        const data = result?.result || result;
        return (data?.ok && data?.reply)
          ? { text: stripIxPeriods(data.reply), ...systemReplySource(data.reply, data.category || 'fallback', 'pick_category_reply') }
          : null;
      } catch (_) {
        return null;
      }
    };
    const pickFromGeneralFallback = () => buildGeneralFallbackReply(options.sourceText || '', options.replyIdentity || null);
    const roll = Math.random();
    let reply = null;
    if (roll < 0.15) {
      reply = pickFromExclusive();
    } else if (roll < 0.7) {
      reply = pickFromCards() || pickFromGeneralFallback();
    } else {
      reply = (await pickFromCloud()) || pickFromGeneralFallback();
    }
    if (!reply) reply = pickFromGeneralFallback();
    if (!reply?.text || !options.replyIdentity) return reply;
    return {
      ...reply,
      text: personalizeConversationReplyText(
        reply.text,
        reply.sourceCategory || 'action_reply',
        options.replyIdentity
      )
    };
  }

  function buildGeneralFallbackReply(sourceText, replyIdentity = null) {
    const category = replyCategoryFor(sourceText || '');
    const line = pickFallbackReplyLine('single');
    const text = personalizeConversationReplyText(
      softenIxReply(line, sourceText || '', { forceQuestion: Math.random() < .25 }),
      category,
      replyIdentity
    );
    return { text, ...systemReplySource(line, category, 'local_fallback_reply') };
  }

  async function actionReplyForCurrentMode(itemId, sourceText, dream = null, fallbackPool = null, contextValue = null, requestScopeValue = null) {
    const cardReplyContext = window.SHEXCardReplyContext?.restore?.(contextValue) || null;
    const memberIdentity = window.SHEXCardReplyContext?.restoreIdentity?.(contextValue) || null;
    const groupReplyContext = window.SHEXCardReplyContext?.restoreGroup?.(requestScopeValue) || null;
    const replyIdentity = cardReplyContext?.identity || memberIdentity?.identity || null;
    if (mode.value === 'english' || mode.value === 'tarot' || mode.value === 'lenormand') {
      const text = stripIxPeriods(naturalReply(sourceText || '动作', cardReplyContext || memberIdentity));
      if (mode.value === 'tarot' || mode.value === 'lenormand') return { text };
      return { text, ...systemReplySource(text, 'english', 'english_action_reply') };
    }
    const exclusivePool = fallbackPool || ixActionReplies[itemId] || [];
    return await pickReplyWithSourceMix(dream?.id || '', exclusivePool, {
      sourceText,
      replyIdentity,
      ownerId: cardReplyContext?.ownerId || groupReplyContext?.ownerId || ''
    });
  }

  async function handleGroupActionClick(itemId, kind = 'action') {
    const active = requireActiveConversation();
    if (active?.kind !== 'group' || !active.group) return false;
    const state = readState();
    const groupReplyContext = createGroupCardReplyContext(active, createXId('group-interaction'), Date.now(), state);
    if (!groupReplyContext) return false;
    const members = groupReplyContext.members.map((member) => dreamById(member.dreamId, state)).filter(Boolean);
    if (!members.length) return false;
    const energyResult = await consumeXSendEnergy(kind === 'gift' ? 'x_message_gift' : 'x_message_action');
    if (!energyResult) return true;
    const scope = validateLiveGroupCardReplyContext(groupReplyContext, { sourceMessageRequired: false });
    if (!scope.ok) return true;
    const actionText = kind === 'gift'
      ? buildActionGiftMessage('gift', itemId, '我', '大家')
      : xGroupActionNormalReplies[itemId] || xGroupActionNormalReplies.hug;
    addMessageToConversation(groupReplyContext.conversationKey, {
      type: 'notice',
      noticeKind: kind === 'gift' ? 'gift' : 'gesture',
      text: actionText,
      sender: '我',
      receiver: '大家',
      itemId
    });
    if (kind !== 'action') return true;
    const normalReplies = ixActionReplies[itemId] || [];
    const jealousReplies = xGroupActionJealousReplies[itemId] || xGroupActionJealousReplies.hug;
    const pool = Math.random() < 0.65 ? normalReplies : jealousReplies;
    const replyCount = Math.max(1, Math.min(members.length, Math.floor(Math.random() * members.length) + 1));
    const selectedMembers = members.slice().sort(() => Math.random() - 0.5).slice(0, replyCount);
    const usedReplies = new Set();
    let delay = Math.max(360, getIxReplyDelayMs());
    showTaTyping(selectedMembers[0]);
    selectedMembers.forEach((dream, index) => {
      window.setTimeout(async () => {
        const liveScope = validateLiveGroupCardReplyContext(groupReplyContext, { sourceMessageRequired: false });
        const memberIdentity = window.SHEXCardReplyContext?.restoreIdentity?.(
          groupReplyContext.members.find((member) => member.dreamId === dream.id)
        ) || null;
        hideTaTyping();
        if (!liveScope.ok || !memberIdentity) return;
        const available = pool.map(stripIxPeriods).filter(Boolean).filter((line) => !usedReplies.has(line));
        const reply = await actionReplyForCurrentMode(
          itemId,
          actionText,
          dream,
          available.length ? available : pool,
          memberIdentity,
          groupReplyContext
        );
        const finalScope = validateLiveGroupCardReplyContext(groupReplyContext, { sourceMessageRequired: false });
        if (!finalScope.ok) return;
        const delivery = reply ? prepareReplyForDelivery(reply, groupReplyContext.conversationKey, dream.id) : null;
        if (delivery?.reply) {
          usedReplies.add(delivery.reply.text || '');
          addMessageToConversation(groupReplyContext.conversationKey, {
            role: 'ta',
            senderId: dream.id,
            dreamCharacterId: dream.id,
            senderName: dream.name,
            text: delivery.reply.text || '表情包',
            ...(delivery.reply.sticker ? { sticker: delivery.reply.sticker } : {}),
            ...replySourceFields(delivery.reply)
          });
        }
        const next = selectedMembers[index + 1];
        if (next) showTaTyping(next);
      }, delay);
      delay += getIxReplyDelayMs();
    });
    window.setTimeout(hideTaTyping, delay + 800);
    return true;
  }

  async function handleActionGiftClick(kind, itemId, direction = 'to-ta') {
    const active = requireActiveConversation();
    if (!active) {
      showChatToast('请先进入一个聊天');
      return;
    }
    const aiInteraction = kind === 'action' ? currentCharacterAIInteractionContext() : null;
    if (aiInteraction) {
      const { selfName, taName } = identity();
      const sender = direction === 'from-ta' ? taName : selfName;
      const receiver = direction === 'from-ta' ? selfName : taName;
      const displaySender = direction === 'from-ta' ? taName : '我';
      const displayReceiver = direction === 'from-ta' ? '我' : taName;
      const text = buildActionGiftMessage(kind, itemId, displaySender, displayReceiver);
      if (!text || active.kind !== 'single') return;
      const sent = addMessage({
        type: 'notice',
        noticeKind: 'gesture',
        text,
        sender,
        receiver,
        itemId,
        sourceMode: 'ai',
        interactionType: 'action',
        interactionData: { itemId, direction }
      });
      if (!sent || sent.localSaveFailed) {
        showChatToast('动作尚未保存，请稍后重试');
        return;
      }
      startCharacterAIInteractionReply({
        sent,
        conversationKeyValue: aiInteraction.conversationKey,
        dreamId: aiInteraction.dreamId,
        eventText: characterAIInteractionPrompt('action', { text }),
        interactionType: 'action',
        chatMode: aiInteraction.chatMode
      });
      return;
    }
    const cardReplyContext = active.kind === 'single' && active.dream
      ? createSingleCardReplyContext(active, createXId('single-interaction'), Date.now(), readState())
      : null;
    if (active.kind === 'group') {
      if (await handleGroupActionClick(itemId, kind)) return;
    }
    if (active.kind !== 'single' || !active.dream) return;
    if (!cardReplyContext) return;
    const { selfName, taName } = cardReplyContext.identity;
    const sender = direction === 'from-ta' ? taName : selfName;
    const receiver = direction === 'from-ta' ? selfName : (active.kind === 'group' ? '大家' : taName);
    const displaySender = direction === 'from-ta' ? taName : '我';
    const displayReceiver = direction === 'from-ta' ? '我' : (active.kind === 'group' ? '大家' : taName);
    const text = buildActionGiftMessage(kind, itemId, displaySender, displayReceiver);
    if (!text) return;
    const energyResult = await consumeXSendEnergy(kind === 'gift' ? 'x_message_gift' : 'x_message_action');
    if (!energyResult) return;
    const scope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
    if (!scope.ok) return;
    addMessageToConversation(cardReplyContext.conversationKey, {
      type: 'notice',
      noticeKind: kind === 'gift' ? 'gift' : 'gesture',
      text,
      sender,
      receiver,
      itemId
    });
    if (kind !== 'action') return;
    const reply = await actionReplyForCurrentMode(itemId, text, active.dream, null, cardReplyContext);
    const replyScope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
    if (!replyScope.ok) return;
    const delivery = reply ? prepareReplyForDelivery(reply, cardReplyContext.conversationKey, cardReplyContext.dreamId) : null;
    if (delivery?.reply) {
      window.setTimeout(() => {
        const delayedScope = validateLiveSingleCardReplyContext(cardReplyContext, { sourceMessageRequired: false });
        if (!delayedScope.ok) return;
        addMessageToConversation(cardReplyContext.conversationKey, {
          role: 'ta',
          text: delivery.reply.text || '表情包',
          ...(delivery.reply.sticker ? { sticker: delivery.reply.sticker } : {}),
          ...replySourceFields(delivery.reply)
        });
      }, 420);
    }
  }

  function maybeRandomTaActionGiftNotice(contextValue = null) {
    if (mode.value === 'tarot' || mode.value === 'lenormand') return null;
    if (Math.random() > 0.1) return null;
    const cardReplyContext = window.SHEXCardReplyContext?.restore?.(contextValue) || null;
    if (!cardReplyContext) return null;
    const { selfName, taName } = cardReplyContext.identity;
    const kind = Math.random() < 0.65 ? 'action' : 'gift';
    const list = kind === 'gift' ? ixActionGiftItems.gifts : ixActionGiftItems.actions;
    const item = list[Math.floor(Math.random() * list.length)];
    if (!item) return null;
    return {
      type: 'notice',
      noticeKind: kind === 'gift' ? 'gift' : 'gesture',
      text: buildActionGiftMessage(kind, item.id, taName, '我'),
      sender: taName,
      receiver: selfName,
      itemId: item.id
    };
  }

  function renderDirectionalChips(box, kind) {
    if (!box) return;
    const { selfName, taName } = identity();
    const items = kind === 'gift' ? ixActionGiftItems.gifts : ixActionGiftItems.actions;
    const groups = [{ label: '', direction: 'to-ta' }];
    box.innerHTML = groups.map((group) => `
      <div class="x-clean-chip-section">
        ${group.label ? `<div class="x-clean-chip-title">${group.label}</div>` : ''}
        <div class="x-clean-chip-row">
          ${items.map((item) => `<button class="x-clean-chip" type="button" data-${kind}-id="${item.id}" data-direction="${group.direction}">${item.label}</button>`).join('')}
        </div>
      </div>
    `).join('');
    box.querySelectorAll(`[data-${kind}-id]`).forEach((button) => {
      button.onclick = () => {
        void handleActionGiftClick(kind, button.dataset[`${kind}Id`], button.dataset.direction);
      };
    });
  }

  function showActionChips() {
    const box = $('[data-x-detail="action"] .x-clean-chip-grid');
    renderDirectionalChips(box, 'action');
    openDetail('action');
  }

  function showGiftChips() {
    const box = $('[data-x-detail="gift"] .x-clean-chip-grid');
    renderDirectionalChips(box, 'gift');
    openDetail('gift');
  }

  let activeStickerPage = STICKER_SCOPE_USER;

  function setStickerPage(scope) {
    const panel = $('#xCleanToolPanel');
    activeStickerPage = normalizeStickerScope(scope);
    panel?.classList.remove('is-deleting-stickers');
    panel?.querySelectorAll('[data-sticker-page]').forEach((button) => {
      const isActive = button.dataset.stickerPage === activeStickerPage;
      button.classList.toggle('is-active', isActive);
      button.setAttribute('aria-selected', String(isActive));
    });
    panel?.querySelectorAll('[data-sticker-page-panel]').forEach((page) => {
      const isActive = page.dataset.stickerPagePanel === activeStickerPage;
      page.classList.toggle('is-active', isActive);
      page.hidden = !isActive;
    });
    renderStickers();
  }

  function renderStickers() {
    migrateStickerScopesOnce();
    const stickers = readStickerLibrary();
    const deleting = $('#xCleanToolPanel')?.classList.contains('is-deleting-stickers');
    const removeSticker = async (deletedId) => {
      writeStickerLibrary(stickers.filter((item) => String(item.id) !== String(deletedId)));
      const tombstones = readJson('shex_x_stickers_deleted_v1', {});
      tombstones[deletedId] = Date.now();
      writeJson('shex_x_stickers_deleted_v1', tombstones);
      await syncUserDataAfterResourceChange('表情包已删除');
      renderStickers();
    };
    const renderScope = (list, scope, emptyText) => {
      if (!list) return;
      const scopedStickers = stickers.filter((item) => item.scope === scope);
      list.innerHTML = scopedStickers.map((item) => {
        const isCloud = /^cloud:\/\//i.test(item.src || '');
        const imgSrc = isCloud ? '' : (item.src || '');
        const scopeDeleting = deleting && activeStickerPage === scope;
        const action = scopeDeleting ? '删除' : scope === STICKER_SCOPE_USER ? '发送' : '预览';
        return `<button class="x-clean-chip x-clean-sticker-chip" type="button" data-sticker="${escapeHtml(String(item.id))}" data-sticker-scope="${scope}" aria-label="${action}表情包 ${escapeHtml(item.name)}"><img class="${isCloud ? 'x-cloud-image-loading' : ''}" src="${escapeHtml(imgSrc)}" data-cloud-src="${isCloud ? escapeHtml(item.src) : ''}" alt="${escapeHtml(item.name)}"${isCloud ? ' aria-busy="true"' : ''}${item.imageView ? ` style="${imageViewInlineStyle(item.imageView)}"` : ''}>${scopeDeleting ? '<span class="x-clean-sticker-remove">×</span>' : ''}</button>`;
      }).join('') || `<span class="x-clean-filename">${emptyText}</span>`;
      list.querySelectorAll('img[data-cloud-src]').forEach((img) => {
        const cloudSrc = img.dataset.cloudSrc;
        if (!cloudSrc) return;
        void loadCloudImageElement(img, cloudSrc);
      });
      list.querySelectorAll('[data-sticker]').forEach((button) => {
        button.onclick = async () => {
          const sticker = stickers.find((item) => String(item.id) === button.dataset.sticker);
          if (!sticker) return;
          if ($('#xCleanToolPanel')?.classList.contains('is-deleting-stickers') && activeStickerPage === scope) {
            await removeSticker(button.dataset.sticker);
            return;
          }
          if (scope === STICKER_SCOPE_DREAM) {
            showChatToast('梦角表情只会由梦角发送');
            return;
          }
          await sendStickerMessage(sticker);
        };
        button.oncontextmenu = async (event) => {
          event.preventDefault();
          await removeSticker(button.dataset.sticker);
        };
      });
    };
    renderScope($('#xCleanUserStickerList'), STICKER_SCOPE_USER, '还没有我的表情');
    renderScope($('#xCleanDreamStickerList'), STICKER_SCOPE_DREAM, '还没有梦角表情');
  }

  let statusModuleConfigured = false;

  function statusModule() {
    const module = window.SHEXStatusCore;
    if (!module) return null;
    if (!statusModuleConfigured) {
      module.configure({
        todayKey,
        identity,
        escapeHtml,
        currentDream: () => currentWorldDream(readState()),
        getPanel: (pageKey) => $(panels[pageKey]),
        readPaidEntry: paidFeatureEntry,
        readLegacyEntry: (dreamId, featureKind) => {
          const item = readState().letters[dreamId]?.[featureKind] || {};
          return item.date === todayKey() && item.html ? item : null;
        },
        writeLegacyEntry: (dreamId, featureKind, html) => updateState((draft) => {
          if (!draft.letters[dreamId]) draft.letters[dreamId] = {};
          draft.letters[dreamId] = {
            ...draft.letters[dreamId],
            [featureKind]: {
              date: todayKey(),
              html,
              paidAt: Date.now()
            }
          };
        }),
        savePaidEntry: savePaidFeatureEntry,
        businessKey: paidFeatureBusinessKey,
        consumeEnergy: consumeDiagnosedPaidFeatureEnergy,
        energyCost,
        showDiagnostic: showPaidFeatureDiagnostic,
        showToast: showChatToast,
        debugLog: shexDebugLog
      });
      statusModuleConfigured = true;
    }
    return module;
  }

  function installTaStatus() {
    const module = statusModule();
    if (!module) {
      showChatToast('状态模块加载失败，请刷新后重试');
      return;
    }
    module.install('hisStatus');
  }
  window.SHEXOfficialStageContext={
    setBackgroundSuppression:(identity,enabled)=>{
      if(identity.scope?.scopeType!=='user_dream'||identity.ownerId!==window.SHEXAuth.current()?.userId)return false;const key=identity.ownerId+':'+identity.scope.scopeId,value=enabled===true;
      if(Boolean(officialStageBackgroundSuppression.get(key))===value)return false;officialStageBackgroundSuppression.set(key,value);if(currentWorldDream(readState())?.id===identity.scope.scopeId)installWorldHome();return true;
    },
    captureNativeState:(state)=>{
      const owner=window.SHEXAuth.current()?.userId,contract=window.SHEXBeautify.official.contract,dreams=[];
      for(const dream of state.dreams||[])if(officialStageNativeVisuals.has(owner+':'+dream.id))dreams.push({id:dream.id,...contract.nativeBase(state,dream).dream});
      return dreams.length?{userAvatar:state.userAvatar,dreams}:null;
    },
    markNativeEdit:(dreamId,fields)=>{
      const ownerId=window.SHEXAuth.current()?.userId,key=ownerId+':'+dreamId,snapshot=officialStageNativeVisuals.get(key);if(!snapshot)return;
      const holds=officialNativeEditHolds.get(key)||new Set();for(const field of fields)if(window.SHEXBeautify.official.contract.NATIVE_FIELDS.includes(field)&&!snapshot.unfrozenFields?.includes(field))holds.add(field);
      if(!holds.size)return;officialNativeEditHolds.set(key,holds);officialNativePending.set(key,{ownerId,dreamId,fields:[...holds],baseRevision:snapshot.__documentRevision});
      persistOfficialNativePending(ownerId);
    },
    observeNativeEdit:(previous,next)=>{
      const contract=window.SHEXBeautify.official.contract,owner=window.SHEXAuth.current()?.userId;
      for(const dream of next.dreams||[]){if(!officialStageNativeVisuals.has(owner+':'+dream.id))continue;const before=contract.nativeBase(previous,previous.dreams?.find(d=>d.id===dream.id)||{}),after=contract.nativeBase(next,dream),changed=contract.NATIVE_FIELDS.filter(f=>JSON.stringify(f==='userAvatar'?before.userAvatar:before.dream[f])!==JSON.stringify(f==='userAvatar'?after.userAvatar:after.dream[f]));if(changed.length)window.SHEXOfficialStageContext.markNativeEdit(dream.id,changed);}
    },
    flushNativeEdits:()=>{
      if(officialNativeFlush)return officialNativeFlush;
      officialNativeFlush=(async()=>{
      const ownerId=window.SHEXAuth.current()?.userId;
      while(true){
        const entry=[...officialNativePending].find(([,p])=>p.ownerId===ownerId);if(!entry)break;const [key,pending]=entry;
        pending.operationId=pending.operationId||'official-'+crypto.randomUUID();pending.operationIssuedAt=pending.operationIssuedAt||Date.now();
        const result=await window.SHEXBeautify.api.storage.officialStageRequest('releaseOfficialStageNativeFields',{scopeType:'user_dream',scopeId:pending.dreamId,baseRevision:pending.baseRevision,nativeFields:pending.fields,operationId:pending.operationId,operationIssuedAt:pending.operationIssuedAt});
        if(window.SHEXAuth.current()?.userId!==ownerId)return;
        if(officialNativePending.get(key)===pending){officialNativePending.delete(key);officialNativeEditHolds.delete(key);}
        else {const next=officialNativePending.get(key);next.baseRevision=result.document?.revision||result.documentRevision;}
        persistOfficialNativePending(ownerId);
        const visual=result.document?.stageNativeSnapshot;if(visual)officialStageNativeVisuals.set(key,{...structuredClone(visual),__documentRevision:result.document.revision});
        if(activeStageBeautifyScope()?.scopeId===pending.dreamId)await ensureStageConfirmedAppearanceRuntime()?.refreshAfterVersionChange?.('OFFICIAL_NATIVE_EDIT_COMMITTED');
      }
      })().finally(()=>{officialNativeFlush=null;});return officialNativeFlush;
    },
    setSignature:(identity,signature)=>{if(identity.scope?.scopeType==='user_dream'&&identity.ownerId===window.SHEXAuth.current()?.userId){const key=identity.ownerId+':'+identity.scope.scopeId,value=String(signature||'');if(officialStageSignatures.get(key)!==value){officialStageSignatures.set(key,value);window.SHEXBeautify?.runtime?.timeTicker?.resync?.();}}},
    setNativeVisual:(identity,visual)=>{
      if(identity.scope?.scopeType!=='user_dream'||identity.ownerId!==window.SHEXAuth.current()?.userId)return false;
      const key=identity.ownerId+':'+identity.scope.scopeId;
      officialNativeKnownKeys.add(key);
      const normalized=visual?{...structuredClone(visual),__documentRevision:identity.documentRevision}:null;
      if(!normalized){officialNativeEditHolds.delete(key);officialNativePending.delete(key);}
      else if(!officialNativePending.has(key)){
        try{const pending=JSON.parse(localStorage.getItem('shex_official_native_edits:'+identity.ownerId)||'[]').find(p=>p.ownerId===identity.ownerId&&p.dreamId===identity.scope.scopeId);if(pending){pending.fields=pending.fields.filter(f=>!normalized.unfrozenFields?.includes(f));if(pending.fields.length){if(Date.now()-Number(pending.operationIssuedAt||0)>86400000){delete pending.operationId;delete pending.operationIssuedAt;pending.baseRevision=identity.documentRevision;}officialNativePending.set(key,pending);officialNativeEditHolds.set(key,new Set(pending.fields));}}}catch(_){}
      }
      const pending=officialNativePending.get(key);if(pending&&pending.fields.every(f=>normalized?.unfrozenFields?.includes(f))){officialNativePending.delete(key);officialNativeEditHolds.delete(key);}
      persistOfficialNativePending(identity.ownerId);
      const previous=officialStageNativeVisuals.get(key),{__documentRevision:ignored,...previousVisual}=previous||{};
      if(JSON.stringify(previous?previousVisual:null)===JSON.stringify(visual||null)){if(normalized)officialStageNativeVisuals.set(key,normalized);return false;}
      if(normalized)officialStageNativeVisuals.set(key,normalized);else officialStageNativeVisuals.delete(key);
      if(currentWorldDream(readState())?.id===identity.scope.scopeId)installWorldHome();
      return true;
    },
    project:(dreamId)=>{
      const state=readState(),dream=currentWorldDream(state),scope=activeStageBeautifyScope();
      if(scope?.scopeType!=='user_dream'||dream?.id!==dreamId)return null;
      let status='';try{statusModule();const template=document.createElement('template');template.innerHTML=window.SHEXStatusCore?.readCached?.(dreamId,'hisStatus')||'';status=template.content.querySelector('.x-letter-status-item p')?.textContent||'';}catch(_){}
      const values=window.SHEXBeautify?.official?.contract?.projectContext({user:{name:state.userName||window.SHEXAuth.current()?.nickname||'我'},character:dream,status,togetherSince:dream.datingTogetherSince||''});
      return values?{...values,signature:officialStageSignatures.get(window.SHEXAuth.current().userId+':'+dreamId)||''}:null;
    },
    photoDefault:(kind,dreamId)=>{
      const state=readState(),dream=xWorldRuntimeDisplayContext(state).dream;
      if(!dream||dreamId&&dream.id!==dreamId||activeStageBeautifyScope()?.scopeType!=='user_dream')return'';
      return kind==='user'?(dream?.__officialStageVisual?dream.__officialStageVisual.userAvatar||'':state.userAvatar||''):kind==='character'?dream?.avatar||'':'';
    }
  };
  // 高级美化官方预设：我的名字 / 我的头像 / 在一起天数 / 起始日。只读本机已有资料，X传讯与 X世界共用。
  window.SHEXPresetPersonContext={
    forDream:(dreamId)=>{
      const state=readState(),dream=dreamId?(state.dreams||[]).find(item=>item?.id===dreamId):null;
      const user={name:String(state.userName||window.SHEXAuth?.current?.()?.nickname||'我').slice(0,120),avatar:String(state.userAvatar||'').slice(0,2048)};
      const since=/^\d{4}-\d{2}-\d{2}$/.test(String(dream?.datingTogetherSince||''))?dream.datingTogetherSince:'';
      const label=since?window.SHEXBeautify?.official?.contract?.projectContext?.({togetherSince:since})?.daysLabel||'':'';
      const match=/第\s*(\d+)\s*天/.exec(label);
      return {user,couple:{days:match?Number(match[1]):'',since:match?since:''}};
    },
    forCurrentWorld:()=>window.SHEXPresetPersonContext.forDream(currentWorldDream(readState())?.id||'')
  };
