    const chained = saveDatingRelationshipThroughProfileChain(dreamId, { togetherSince: date }, options,
      '在一起时间已保存', '在一起时间没有保存成功，请稍后重试');
    if (chained) return await chained;
    const base = captureDatingProfileCloudBase(dreamId, 'datingRelationship');
    const write = () => updateState((draft) => {
      const target = draft.dreams.find((item) => String(item?.id || '') === String(dreamId || draft.currentDreamId || '')) || draft.dreams[0];
      if (!target) return;
      target.datingTogetherSince = date;
      target.updatedAt = Date.now();
      window.SHEXCharacterProfileSync?.touchGroup?.(target, 'datingRelationship', target.updatedAt);
    });
    const saved = window.SHEXUserData?.withDreamProfileLocalWrite
      ? window.SHEXUserData.withDreamProfileLocalWrite(write)
      : write();
    if (!saved) {
      showChatToast('在一起时间没有保存成功，请稍后重试');
      return false;
    }
    return await syncDatingProfileGroup(dreamId, base, '在一起时间已保存');
