  function openAlbumPicker(options = {}) {
    const onSelect = typeof options.onSelect === 'function' ? options.onSelect : null;
    const selectOriginal = options.selectOriginal === true;
    const title = String(options.title || '选择约会头像').trim() || '选择约会头像';
    const note = String(options.note || '从共享相册里选择一张照片，只会用于这次约会模块头像，不会改动背景或相册展示图。').trim();
    const aspectRatios = Array.isArray(options.aspectRatios) && options.aspectRatios.length ? options.aspectRatios : ['1:1', 'free', '3:4', '4:5'];
    const stageWorkbenchPicker = options.stageWorkbench === true;
    const datingPhotoBackground = options.datingPhotoBackground === true;
    document.getElementById('xAlbumPickerOverlay')?.remove();
    const overlay = document.createElement('div');
    overlay.className = 'x-album-picker-overlay';
    if (stageWorkbenchPicker) overlay.classList.add('x-album-picker-overlay--stage-workbench');
    overlay.id = 'xAlbumPickerOverlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', title);
    overlay.innerHTML = `
      <section class="x-album-picker-sheet">
        <header class="x-album-picker-header">
          <div>
            <small>X ALBUM</small>
            <h2>${escapeHtml(title)}</h2>
          </div>
          <button type="button" data-album-picker-close aria-label="关闭">×</button>
        </header>
        <div class="x-album-toolbar">
          <label class="x-album-upload">上传照片<input data-album-picker-upload ${datingPhotoBackground ? 'data-dating-photo-background' : ''} type="file" accept="image/*" ${datingPhotoBackground ? '' : 'multiple'}></label>
          <span data-album-picker-count>0 / ${ALBUM_MAX_PHOTOS}</span>
        </div>
        <p class="x-album-note">${escapeHtml(note)}</p>
        <div class="x-album-grid" data-album-picker-grid aria-live="polite"></div>
      </section>
    `;
    let source = 'account', datingPhotos = [], datingCursor = null, datingLoaded = false, datingLoading = false;
    const pickerPhotos = () => source === 'dating' ? datingPhotos : readAlbum();
    let selectingOriginal = false, pickerClosed = false;
    const close = (selected = false) => {
      if (pickerClosed || (selectOriginal && selectingOriginal && selected !== true)) return;
      pickerClosed = true;
      document.removeEventListener('keydown', onKeydown);
      document.body.classList.remove('x-album-picker-open');
      overlay.remove();
      if (selected !== true && typeof options.onClose === 'function') options.onClose();
    };
    const render = () => {
      const photos = pickerPhotos();
      const grid = overlay.querySelector('[data-album-picker-grid]');
      const count = overlay.querySelector('[data-album-picker-count]');
      if (count) count.textContent = `${photos.length} / ${ALBUM_MAX_PHOTOS}`;
      if (!grid) return;
      grid.innerHTML = photos.length ? photos.map((photo) => `
        <article class="x-album-item" data-album-photo-id="${escapeHtml(photo.id)}">
          <button class="x-album-select" type="button" data-album-picker-select="${escapeHtml(photo.id)}" aria-label="选择这张照片">
            ${albumPhotoMarkup(photo)}
            <span>选择</span>
          </button>
        </article>
      `).join('') : '<div class="x-album-empty"><strong>相册还是空的</strong><span>可以先上传一张照片，再选作约会头像。</span></div>';
      resolveAlbumPhotoImages(grid);
    };
    const onKeydown = (event) => {
      if (event.key === 'Escape') close();
    };
    overlay.addEventListener('click', async (event) => {
      if (event.target === overlay || event.target.closest('[data-album-picker-close]')) {
        close();
        return;
      }
      const button = event.target.closest('[data-album-picker-select]');
      if (!button) return;
      const photo = pickerPhotos().find((item) => item.id === button.dataset.albumPickerSelect);
      if (!photo) return;
      if (selectOriginal && selectingOriginal) return;
      button.disabled = true;
      try {
        if (selectOriginal) selectingOriginal = true;
        const renderedUrl = button.querySelector('img')?.currentSrc || button.querySelector('img')?.src || '';
        const view = selectOriginal ? photo.view || null : await chooseAlbumPhotoView(photo, aspectRatios, renderedUrl);
        if (view === undefined) {
          button.disabled = false;
          return;
        }
        await onSelect?.({ id: photo.id, fileID: photo.fileID, createdAt: photo.createdAt, view });
        close(true);
      } catch (error) {
        console.warn('[X_ALBUM_PICKER_SELECT_FAILED]', error);
        showChatToast('照片没有设置成功，请稍后重试');
        button.disabled = false;
      } finally {
        if (selectOriginal) selectingOriginal = false;
      }
    });
    overlay.querySelector('[data-album-picker-upload]')?.addEventListener('change', async (event) => {
      const input = event.currentTarget;
      const files = selectedUploadFiles(input);
      input.disabled = true;
      overlay.classList.add('is-uploading');
      try {
        const previousFiles = datingPhotoBackground ? new Set(readAlbum().map((photo) => photo.fileID)) : null;
        await uploadAlbumFiles(files);
        if (overlay.isConnected) {
          render();
          const uploaded = datingPhotoBackground && readAlbum().filter((photo) => !previousFiles.has(photo.fileID)).pop();
          if (uploaded) {
            await onSelect?.({ id: uploaded.id, fileID: uploaded.fileID, createdAt: uploaded.createdAt, view: uploaded.view });
            close();
          }
        }
      } finally {
        input.value = '';
        input.disabled = false;
        overlay.classList.remove('is-uploading');
      }
    });
    if (datingPhotoBackground && typeof options.loadDatingPhotos === 'function') {
      const nav = document.createElement('div');
      nav.className = 'x-album-toolbar';
      nav.innerHTML = '<button type="button" data-album-source="account" aria-pressed="true">账号相册</button><button type="button" data-album-source="dating" aria-pressed="false">约会相册</button><button type="button" data-album-more hidden>更多</button>';
      overlay.querySelector('.x-album-note').before(nav);
      const more = nav.querySelector('[data-album-more]');
      const load = async () => {
        if (datingLoading) return;
        datingLoading = true;
        more.disabled = true;
        try {
          const page = await options.loadDatingPhotos({ cursor: datingCursor || undefined });
          if (!overlay.isConnected) return;
          datingPhotos = [...new Map([...datingPhotos, ...(page.items || [])].map((photo) => [photo.id, photo])).values()];
          datingCursor = page.nextCursor || null;
          datingLoaded = true;
          render();
        } catch (error) { showChatToast('约会相册读取失败，请再次点击重试'); }
        finally { datingLoading = false; more.disabled = false; more.hidden = source !== 'dating' || !datingCursor; }
      };
      nav.addEventListener('click', async (event) => {
        const tab = event.target.closest('[data-album-source]');
        if (tab) {
          source = tab.dataset.albumSource;
          nav.querySelectorAll('[data-album-source]').forEach((button) => button.setAttribute('aria-pressed', String(button === tab)));
          more.hidden = source !== 'dating' || !datingCursor;
          render();
          if (source === 'dating' && !datingLoaded) await load();
        } else if (event.target.closest('[data-album-more]')) await load();
      });
    }
    document.addEventListener('keydown', onKeydown);
    document.body.classList.add('x-album-picker-open');
    document.body.appendChild(overlay);
    render();
    requestAnimationFrame(() => overlay.classList.add('is-open'));
    return true;
  }

  window.SHEXAlbumPicker = {
    open: openAlbumPicker
  };

  let dreamAvatarFileInput = null;
  let pendingDreamAvatarSelection = null;
  const dreamAvatarPhotos = {
    get(kind = 'dream', dreamId = '') {
      const state = readState();
      return datingAvatarPhotoFor(kind, dreamId, state, readAlbum());
    },
    async set(kind = 'dream', dreamId = '', photo = {}) {
      return setDatingAvatarPhoto(kind, dreamId, photo);
    },
    open(kind = 'dream', dreamId = '', onSaved = null) {
      const cleanKind = kind === 'user' ? 'user' : 'dream';
      const dream = dreamById(dreamId, readState());
      if (!dream) return false;
      if (cleanKind === 'dream' && !creatorExperienceForActive({ kind: 'single', dream }).allowTaAvatarEdit) {
        showChatToast('该角色使用创作者美化，TA头像不能修改');
        return false;
      }
      if (!dreamAvatarFileInput) {
        dreamAvatarFileInput = document.createElement('input');
        dreamAvatarFileInput.id = 'xDreamRelationshipAvatarInput';
        dreamAvatarFileInput.type = 'file';
        dreamAvatarFileInput.accept = 'image/*';
        dreamAvatarFileInput.hidden = true;
        dreamAvatarFileInput.addEventListener('change', async () => {
          const selection = pendingDreamAvatarSelection;
          pendingDreamAvatarSelection = null;
          const file = selectedUploadFiles(dreamAvatarFileInput)[0];
          if (!selection || !file) return;
          try {
            const fileID = await uploadUnifiedAvatarFile(file);
            if (await setDatingAvatarPhoto(selection.kind, selection.dreamId, { fileID })) {
              if (typeof selection.onSaved === 'function') selection.onSaved();
            }
          } catch (error) {
            showChatToast(error?.message || '头像上传失败，请检查网络后重试');
          } finally {
            dreamAvatarFileInput.value = '';
          }
        });
        document.body.appendChild(dreamAvatarFileInput);
      }
      pendingDreamAvatarSelection = { kind: cleanKind, dreamId, onSaved };
      dreamAvatarFileInput.value = '';
      dreamAvatarFileInput.click();
      return true;
    }
  };
  window.SHEXDreamAvatarPhotos = dreamAvatarPhotos;
  window.SHEXDatingAvatarPhotos = dreamAvatarPhotos;

  if (!window.SHEXCharacterProfileData && window.SHEXCharacterProfileDataCore?.createDataApi) {
    window.SHEXCharacterProfileData = window.SHEXCharacterProfileDataCore.createDataApi({
      readState,
      updateState,
      sync: syncUserDataAfterResourceChange,
      saveGroup: (options) => window.SHEXDreamProfileCloudStore?.saveGroup?.(options),
      resolveConflict: (options) => window.SHEXDreamProfileCloudStore?.resolveConflict?.(options),
      getCloudStatus: (dreamId) => window.SHEXUserData?.getDreamProfileStatus?.(dreamId),
      withLocalWrite: (callback) => window.SHEXUserData?.withDreamProfileLocalWrite
        ? window.SHEXUserData.withDreamProfileLocalWrite(callback)
        : callback(),
      notify: showChatToast,
      now: Date.now,
      // X103：尚未同步到云端的资料修改只记在本机（不进云端快照），刷新或重开后继续自动提交。
      pendingStore: (() => {
        // 按账号隔离，避免换账号后读到别人的待提交资料。
        const pendingKey = () => {
          let owner = '';
          try { owner = String(window.SHEXUserData?.ownerId?.() || ''); } catch (_) {}
          return `x103_dream_profile_pending_v1:${owner || 'guest'}`;
        };
        return {
          load() {
            try { return JSON.parse(localStorage.getItem(pendingKey()) || '[]'); } catch (_) { return []; }
          },
          save(items) {
            try {
              if (Array.isArray(items) && items.length) localStorage.setItem(pendingKey(), JSON.stringify(items));
              else localStorage.removeItem(pendingKey());
            } catch (_) {}
          }
        };
      })()
    });
    // X103：历史遗留的资料冲突静默结案（保留当前正在使用的版本），不再要求用户挑选版本。
    const settleDreamProfileConflicts = () => {
      try {
        const profileData = window.SHEXCharacterProfileData;
        if (typeof profileData?.autoResolveConflicts !== 'function') return;
        (readState().dreams || []).forEach((dream) => {
          const open = (Array.isArray(dream?.profileSyncConflicts) ? dream.profileSyncConflicts : [])
            .some((item) => item && item.resolved !== true);
          if (open && dream.id) profileData.autoResolveConflicts(String(dream.id)).catch(() => undefined);
        });
      } catch (error) {
        console.warn('[SHEX] settle dream profile conflicts failed', error);
      }
    };
    // 云端资料合并进本机之后再处理，确保读到的是合并后的最新状态。
    document.addEventListener('shex:user-data-merged', () => setTimeout(settleDreamProfileConflicts, 0));
    setTimeout(settleDreamProfileConflicts, 3000);
    setTimeout(() => retryDreamProfileSaves(), 5000);
    // 网络恢复或页面回到前台时，把尚未同步到云端的资料修改立即再提交一次。
    const retryDreamProfileSaves = () => {
      try { window.SHEXCharacterProfileData?.retryPendingSaves?.().catch(() => undefined); } catch (_) {}
    };
    window.addEventListener('online', retryDreamProfileSaves);
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') retryDreamProfileSaves();
    });
  }

  window.SHEXDatingProfileData = {
    getAnniversaries(dreamId = '') {
      return datingAnniversariesFor(dreamId);
    },
    async setAnniversaries(dreamId = '', anniversaries = [], options = {}) {
      return setDatingAnniversaries(dreamId, anniversaries, options);
    },
    getTogetherSince(dreamId = '') {
      return datingTogetherSinceFor(dreamId);
    },
    async setTogetherSince(dreamId = '', value = '', options = {}) {
      return setDatingTogetherSince(dreamId, value, options);
    },
    getPersona(dreamId = '') {
      return datingPersonaFor(dreamId);
    },
    async setPersona(dreamId = '', profile = {}, options = {}) {
      return window.SHEXCharacterProfileData.setPersonaV2(dreamId, profile, options);
    },
    getUserProfile(dreamId = '') {
      return datingUserProfileFor(dreamId);
    },
    async setUserProfile(dreamId = '', profile = {}, options = {}) {
      return window.SHEXCharacterProfileData.setUserProfileV1(dreamId, profile, options);
    }
  };

  function installAlbum() {
    const panel = $('#xAlbumPanel');
    const content = panel?.querySelector('.x-album-page-content');
    if (!panel || !content) return;
    const mode = albumPageMode;
    const isCompanionBackgroundMode = mode === 'companion-background';
    const isSelectionMode = mode === 'background' || mode === 'display' || isCompanionBackgroundMode;
    const selectedField = mode === 'display' ? 'albumDisplayPhotoId' : 'backgroundPhotoId';
    const title = mode === 'background'
      ? '设置背景'
      : mode === 'display'
        ? '设置相册展示图'
        : isCompanionBackgroundMode
          ? '选择陪伴背景'
          : '相册';
    const note = mode === 'background'
      ? '选择一张照片作为当前梦角的 X世界整页背景。上传与删除功能仍然可用。'
      : mode === 'display'
        ? '选择一张照片固定展示在 X世界首页的照片组件中。它可以和整页背景不同。'
        : isCompanionBackgroundMode
          ? '选择一张共享相册照片作为当前梦角的 X陪伴背景，不会重复上传文件。'
        : '账号内所有梦角共享这个相册。当前为预览模式，点击照片只查看，不会改变任何梦角设置。';
    content.innerHTML = `
      <header class="x-album-page-header">
        <small>X ALBUM</small>
        <div>
          <h2>${title}</h2>
          <span>${isSelectionMode ? '选图模式' : '预览模式'}</span>
        </div>
      </header>
      <div class="x-album-toolbar">
        <label class="x-album-upload">上传照片<input id="xAlbumUploadInput" type="file" accept="image/*" multiple></label>
        <span id="xAlbumCount">0 / ${ALBUM_MAX_PHOTOS}</span>
      </div>
      <p class="x-album-note">${note}</p>
      ${isSelectionMode && !isCompanionBackgroundMode ? `<button class="x-album-reset" type="button" data-album-reset>恢复默认</button>` : ''}
      <div class="x-album-grid" id="xAlbumGrid" aria-live="polite"></div>
    `;
    const render = () => {
      const formalPhotos = readAlbum();
      const pendingPhotos = readAlbumPendingPhotos();
      const photos = [...formalPhotos, ...pendingPhotos];
      const dream = currentWorldDream(readState());
      const companionBackground = normalizeBackgroundMedia(readState().companions[dream?.id]?.background)?.fileID || '';
      const grid = $('#xAlbumGrid', content);
      const count = $('#xAlbumCount', content);
      if (count) count.textContent = `${photos.length} / ${ALBUM_MAX_PHOTOS}`;
      if (!grid) return;
      grid.innerHTML = photos.length ? photos.map((photo) => {
        const selectedValue = isCompanionBackgroundMode ? companionBackground : String(dream?.[selectedField] || '');
        const selected = isSelectionMode && selectedValue === photo.fileID;
        const pendingLabel = photo.pendingStatus === 'failed'
          ? '上传失败，请手动重新选择'
          : photo.pendingStatus === 'uploading'
            ? '正在重传'
            : photo.pendingStatus === 'uploaded'
              ? '正在保存云端引用'
              : '待上传';
        const photoContent = photo.pending ? `
          <button class="x-album-preview" type="button" data-album-preview="${escapeHtml(photo.id)}" ${photo.fileID ? '' : 'disabled'} aria-label="${escapeHtml(pendingLabel)}">
            ${albumPhotoMarkup(photo)}
          </button>
          <span class="x-album-pending-status">${escapeHtml(pendingLabel)}</span>
        ` : isSelectionMode ? `
          <button class="x-album-select" type="button" data-album-select="${escapeHtml(photo.id)}" aria-pressed="${String(selected)}" aria-label="${isCompanionBackgroundMode ? '设为当前梦角陪伴背景' : mode === 'background' ? '设为当前梦角背景' : '设为当前梦角相册展示图'}">
            ${albumPhotoMarkup(photo)}
            <span>${selected ? (isCompanionBackgroundMode ? '当前陪伴背景' : mode === 'background' ? '当前背景' : '当前展示图') : '选择'}</span>
          </button>
        ` : `<button class="x-album-preview" type="button" data-album-preview="${escapeHtml(photo.id)}" aria-label="预览这张相册照片">${albumPhotoMarkup(photo)}</button>`;
        return `
          <article class="x-album-item${selected ? ' is-selected' : ''}${photo.pending ? ' is-pending' : ''}${photo.pendingStatus === 'failed' ? ' is-failed' : ''}" data-album-photo-id="${escapeHtml(photo.id)}">
            ${photoContent}
            ${photo.pending && photo.hasBlob && photo.pendingStatus === 'pending' ? `<button class="x-album-retry" type="button" data-album-retry="${escapeHtml(photo.taskId)}">重试</button>` : ''}
            <button class="x-album-delete" type="button" data-album-delete="${escapeHtml(photo.id)}" aria-label="删除这张照片">×</button>
          </article>
        `;
      }).join('') : `<div class="x-album-empty"><strong>相册还是空的</strong><span>${isSelectionMode ? '先上传一张照片，再为当前梦角选择。' : '上传第一张照片，开始整理你的共享相册。'}</span></div>`;
      resolveAlbumPhotoImages(grid);
    };
    content.onclick = async (event) => {
      const retryButton = event.target.closest('[data-album-retry]');
      if (retryButton) {
        event.preventDefault();
        event.stopPropagation();
        retryButton.disabled = true;
        await processAlbumUploadQueue({ reason: 'manual', manualTaskId: retryButton.dataset.albumRetry });
        return;
      }
      const resetButton = event.target.closest('[data-album-reset]');
      if (resetButton && isSelectionMode) {
        resetButton.disabled = true;
        const cleared = await clearCurrentDreamAlbumPhoto(selectedField);
        if (cleared) openPage('settings');
        else resetButton.disabled = false;
        return;
      }
      const deleteButton = event.target.closest('[data-album-delete]');
      if (deleteButton) {
        event.preventDefault();
        event.stopPropagation();
        const photo = [...readAlbum(), ...readAlbumPendingPhotos()].find((item) => item.id === deleteButton.dataset.albumDelete);
        if (!photo) return;
        deleteButton.disabled = true;
        if (photo.pending) await deletePendingAlbumPhoto(photo);
        else await deleteAlbumPhotos([photo]);
        if (content.isConnected) render();
        return;
      }
      const previewButton = event.target.closest('[data-album-preview]');
      if (previewButton && !isSelectionMode) {
        const photos = [...readAlbum(), ...readAlbumPendingPhotos()].filter((item) => item.fileID);
        const photo = photos.find((item) => item.id === previewButton.dataset.albumPreview);
        if (photo) openXWorldAlbumPreview(photo.fileID, photos);
        return;
      }
      const selectButton = event.target.closest('[data-album-select]');
      if (!selectButton || !isSelectionMode) return;
      const photo = readAlbum().find((item) => item.id === selectButton.dataset.albumSelect);
      if (!photo) return;
      selectButton.disabled = true;
      const renderedUrl = selectButton.querySelector('img')?.currentSrc || selectButton.querySelector('img')?.src || '';
      const view = await chooseAlbumPhotoView(photo, isCompanionBackgroundMode || selectedField === 'backgroundPhotoId'
        ? ['9:16', '16:9', 'free']
        : ['free', '1:1', '3:4', '4:5'], renderedUrl);
      if (view === undefined) {
        selectButton.disabled = false;
        return;
      }
      const saved = isCompanionBackgroundMode
        ? await setCurrentDreamCompanionBackgroundFromAlbum(photo.fileID, view)
        : await setCurrentDreamAlbumPhoto(photo.fileID, selectedField, view);
      if (saved) openPage(isCompanionBackgroundMode ? 'companion' : 'settings');
      else selectButton.disabled = false;
    };
    $('#xAlbumUploadInput', content)?.addEventListener('change', async (event) => {
      const input = event.currentTarget;
      const files = selectedUploadFiles(input);
      input.disabled = true;
      panel.classList.add('is-uploading');
      try {
        await uploadAlbumFiles(files);
        if (content.isConnected) render();
      } finally {
        input.value = '';
        input.disabled = false;
        panel.classList.remove('is-uploading');
      }
    });
    render();
    if (albumPendingRuntimeOwnerId !== albumQueueOwnerId()) {
      void refreshAlbumPendingRuntime(albumQueueOwnerId(), { render: true });
    }
  }

  function bindXWorldWidgetOrderControls(list, dreamId) {
    if (!list || list.dataset.orderBound === 'true') return;
    list.dataset.orderBound = 'true';
    let pressTimer = null;
    let draggedRow = null;
    let activePointerId = null;
    let dragging = false;
    const rows = () => Array.from(list.querySelectorAll('[data-x-world-widget-order]'));
    const persistOrder = async () => {
      const nextOrder = normalizeXWorldWidgetOrder(rows().map((row) => row.dataset.xWorldWidgetOrder));
      const saved = updateState((draft) => {
        const targetDream = draft.dreams.find((item) => item.id === dreamId);
        if (targetDream) targetDream.xWorldWidgetOrder = nextOrder;
      });
      if (!saved) {
        showChatToast('小组件顺序没有保存成功，请稍后重试');
        installSettings();
        return;
      }
      applyXWorldWidgetOrder(nextOrder);
      await syncUserDataAfterResourceChange('小组件顺序已保存');
    };
    const stopDragging = (save = false) => {
      window.clearTimeout(pressTimer);
      pressTimer = null;
      if (draggedRow) draggedRow.classList.remove('is-dragging');
      list.classList.remove('is-sorting');
      const shouldSave = dragging && save;
      draggedRow = null;
      activePointerId = null;
      dragging = false;
      if (shouldSave) void persistOrder();
    };
    list.addEventListener('pointerdown', (event) => {
      const handle = event.target.closest('[data-widget-drag-handle]');
      if (!handle) return;
      event.preventDefault();
      draggedRow = handle.closest('[data-x-world-widget-order]');
      activePointerId = event.pointerId;
      pressTimer = window.setTimeout(() => {
        if (!draggedRow) return;
        dragging = true;
        draggedRow.classList.add('is-dragging');
        list.classList.add('is-sorting');
        handle.setPointerCapture?.(activePointerId);
        navigator.vibrate?.(18);
      }, 320);
    });
    list.addEventListener('pointermove', (event) => {
      if (!dragging || event.pointerId !== activePointerId || !draggedRow) return;
      event.preventDefault();
      const target = document.elementFromPoint(event.clientX, event.clientY)?.closest?.('[data-x-world-widget-order]');
      if (!target || target === draggedRow || target.parentElement !== list) return;
      const rect = target.getBoundingClientRect();
      list.insertBefore(draggedRow, event.clientY < rect.top + rect.height / 2 ? target : target.nextSibling);
    });
    list.addEventListener('pointerup', (event) => {
      if (activePointerId !== null && event.pointerId === activePointerId) stopDragging(true);
    });
    list.addEventListener('pointercancel', () => stopDragging(false));
    list.addEventListener('click', (event) => {
      if (event.target.closest('[data-widget-drag-handle]')) event.preventDefault();
    });
    list.addEventListener('keydown', (event) => {
      const handle = event.target.closest('[data-widget-drag-handle]');
      if (!handle || !['ArrowUp', 'ArrowDown'].includes(event.key)) return;
      event.preventDefault();
      const row = handle.closest('[data-x-world-widget-order]');
      const allRows = rows();
      const index = allRows.indexOf(row);
      const targetIndex = event.key === 'ArrowUp' ? index - 1 : index + 1;
      if (targetIndex < 0 || targetIndex >= allRows.length) return;
      const target = allRows[targetIndex];
      if (event.key === 'ArrowUp') list.insertBefore(row, target);
      else list.insertBefore(row, target.nextSibling);
      handle.focus();
      void persistOrder();
    });
  }

  function stageAdvancedBeautifyGateEnabled() {
    return Boolean(window.SHEXAuth?.current?.()?.userId&&window.SHEXBeautify?.editor?.stageWorkbench?.open);
  }

  function stageConfirmedRuntimeGateEnabled() {
    return Boolean(window.SHEXAuth?.current?.()?.userId);
  }

  // 高级美化的 90 多个脚本在登录身份确定后才开始加载；刚进页面就点“高级美化”时它们可能还没加载完，
  // 以前会直接弹“暂时不可用”。现在先等它们加载完（最多 10 秒），再打开。
  function stageBeautifyModulesReady() {
    const root = window.SHEXBeautify;
    return Boolean(root?.api?.storage?.getBeautifyRestoreState && root?.runtime?.stageAppearanceCodec?.mergeSources && root?.editor?.stageWorkbench?.open);
  }
  function waitStageBeautifyModules(timeoutMs = 10000) {
    if (stageBeautifyModulesReady()) return Promise.resolve(true);
    return new Promise((resolve) => {
      let timer = 0, poll = 0;
      const finish = () => { window.clearTimeout(timer); window.clearInterval(poll); document.removeEventListener('shex:beautify-modules-ready', check); resolve(stageBeautifyModulesReady()); };
      const check = () => { if (stageBeautifyModulesReady() || window.SHEX_BEAUTIFY_MODULES_FAILED) finish(); };
      document.addEventListener('shex:beautify-modules-ready', check);
      poll = window.setInterval(check, 250);
      timer = window.setTimeout(finish, timeoutMs);
    });
  }
  function stageBeautifyOpenFailureText(result) {
    const code = String(result?.detail || result?.reason || '');
    if (code === 'STAGE_SCOPE_MISSING') return '请先选择一个 X世界，再打开高级美化';
    if (code === 'OWNER_MISSING' || code === 'AUTH_REQUIRED') return '请先登录，再打开高级美化';
    if (code === 'SESSION_EXPIRED') return '登录已过期，请重新登录后再打开高级美化';
    if (code === 'BEAUTIFY_SCOPE_FORBIDDEN') return '当前 X世界不能修改美化';
    if (code === 'MODULES_FAILED') return '高级美化没有加载完整（网络不稳定），请刷新页面后再试';
    if (code === 'MODULES_LOADING') return '高级美化还在加载，网络有点慢，请稍等几秒再点';
    const first = Array.isArray(result?.conflicts) ? result.conflicts[0] : (Array.isArray(result?.missingRequired) ? result.missingRequired[0] : null);
    const where = first ? ` · ${String(first.reasonCode || '')} · ${String(first.placementId || first.partId || '')}` : '';
    return `X世界美化暂时不可用，请稍后重试${code ? `（${code}${where}）` : ''}`;
  }

  // ===== 设置 → 高级组件：已添加组件的显示 / 隐藏 =====
  // 读的是和高级美化同一份正式外观；开关只改组件的 visible，保存走同一个 stagePersistence，然后刷新当前 X世界。
  const ADVANCED_COMPONENT_PLACEMENT_LABELS = { app_viewport_before:'第一页 · APP 上方', stage_bottom:'第一页 · APP 下方', page2_components:'第二页 · APP 上方', page2_bottom:'第二页 · APP 下方', stage_top:'页面最顶部' };
  async function loadAdvancedComponentState() {
    if (!stageBeautifyModulesReady() && !(await waitStageBeautifyModules(8000))) return null;
    const scope = activeStageBeautifyScope(), ownerId = String(window.SHEXAuth?.current?.()?.userId || '');
    if (!ownerId || !scope?.scopeType || !scope?.scopeId) return null;
    const state = await window.SHEXBeautify.api.storage.getBeautifyRestoreState(scope.scopeType, scope.scopeId, { host:'host_stage', knownBundleHash:'' });
    const codec = window.SHEXBeautify.runtime.stageAppearanceCodec;
    const decoded = codec.mergeSources(state?.sources || {});
    if (decoded?.ok === false) return null;
    const inheritedDraft = codec.mergeSources({ authorAppearanceLocked:state?.sources?.authorAppearanceLocked, authorAppearance:state?.sources?.authorAppearance, globalDocument:state?.sources?.globalDocument }).draft;
    return { scope, ownerId, draft:decoded?.draft || {}, inheritedDraft };
  }
  // 去掉高级美化里的页面背景，让 X世界设置里的背景显示出来（只改背景，主题、组件都不动）。
  async function useSettingsBackgroundOverAdvanced() {
    try {
      const fresh = await loadAdvancedComponentState();
      if (!fresh) throw Object.assign(new Error('STAGE_STATE_UNAVAILABLE'), { code:'STAGE_STATE_UNAVAILABLE' });
      if (fresh.draft?.background) {
        delete fresh.draft.background;
        const persistence = window.SHEXBeautify?.runtime?.stagePersistence?.create?.();
        const result = await persistence?.save?.({ identity:{ ownerId:fresh.ownerId, scopeType:fresh.scope.scopeType, scopeId:fresh.scope.scopeId }, draft:fresh.draft, inheritedDraft:fresh.inheritedDraft || null, pendingFiles:new Map() });
        if (!result?.ok || result.confirmed !== true) throw Object.assign(new Error(String(result?.reason || 'SAVE_FAILED')), { code:String(result?.reason || 'SAVE_FAILED') });
      }
      await ensureStageConfirmedAppearanceRuntime()?.refreshAfterVersionChange?.('SETTINGS_BACKGROUND_PREFERRED');
      const panel = $('#xWorldHome');
      if (panel?.dataset?.btyStageBackgroundOwned === 'true') showChatToast('这张背景来自作者预设或全局美化，暂时不能在这里替换', 3200);
      else showChatToast('已改用设置里的背景');
    } catch (error) {
      reportAppUiDiagnostic('settings_background_prefer_failed', error, {});
      showChatToast(`没有改成功，请稍后再试（${String(error?.code || error?.message || 'ERROR').slice(0, 40)}）`, 3200);
    }
  }

  let advancedComponentSaveQueue = Promise.resolve();
  async function renderAdvancedComponentRows(list) {
    if (!list) return;
    let loaded = null;
    try { loaded = await loadAdvancedComponentState(); } catch (error) { reportAppUiDiagnostic('advanced_components_list_failed', error, {}); }
    if (!list.isConnected) return;
    list.querySelectorAll('[data-advanced-component-row]').forEach((node) => node.remove());
    const components = Array.isArray(loaded?.draft?.components) ? loaded.draft.components : [];
    components.forEach((entry) => {
      const row = document.createElement('div');
      row.className = 'x-settings-widget-row x-settings-advanced-row';
      row.dataset.advancedComponentRow = String(entry.instanceId || '');
      const label = ADVANCED_COMPONENT_PLACEMENT_LABELS[entry.placementId] || '';
      row.innerHTML = `<span class="x-settings-advanced-dot" aria-hidden="true"></span><span class="x-settings-widget-name">${escapeHtml(entry.name || '高级组件')}${label ? `<small>${escapeHtml(label)}</small>` : ''}</span><label class="x-settings-widget-toggle" aria-label="显示${escapeHtml(entry.name || '高级组件')}"><input type="checkbox" ${entry.visible !== false ? 'checked' : ''}><span class="x-settings-switch" aria-hidden="true"></span></label>`;
      const input = row.querySelector('input');
      input.addEventListener('change', () => {
        const wanted = input.checked;
        input.disabled = true;
        // 多个开关连续点时排队保存：每次都基于上一次保存后的最新数据，不会互相覆盖。
        advancedComponentSaveQueue = advancedComponentSaveQueue.then(() => saveToggle(wanted)).catch(() => {});
      });
      const saveToggle = async (wanted) => {
        try {
          const fresh = await loadAdvancedComponentState();
          const target = fresh?.draft?.components?.find?.((item) => String(item.instanceId) === String(entry.instanceId));
          if (!fresh) throw Object.assign(new Error('STAGE_STATE_UNAVAILABLE'), { code:'STAGE_STATE_UNAVAILABLE' });
          if (!target) {
            // 这个组件已经在高级美化里删掉了，列表还没来得及刷新：直接移除这一行并提示怎么重新添加。
            row.remove();
            showChatToast(`「${entry.name}」已经被删除了，可以在“添加高级组件”里重新添加`, 3200);
            return;
          }
          target.visible = wanted;
          const persistence = window.SHEXBeautify?.runtime?.stagePersistence?.create?.();
          const result = await persistence?.save?.({ identity:{ ownerId:fresh.ownerId, scopeType:fresh.scope.scopeType, scopeId:fresh.scope.scopeId }, draft:fresh.draft, inheritedDraft:fresh.inheritedDraft || null, pendingFiles:new Map() });
          if (!result?.ok || result.confirmed !== true) throw Object.assign(new Error(String(result?.reason || 'SAVE_FAILED')), { code:String(result?.reason || 'SAVE_FAILED') });
          await ensureStageConfirmedAppearanceRuntime()?.refreshAfterVersionChange?.('ADVANCED_COMPONENT_VISIBILITY');
          showChatToast(wanted ? `已显示「${entry.name}」` : `已隐藏「${entry.name}」`);
        } catch (error) {
          input.checked = !wanted;
          reportAppUiDiagnostic('advanced_component_toggle_failed', error, {});
          const code = String(error?.code || error?.message || 'ERROR').slice(0, 40);
          showChatToast(code === 'STAGE_COMPONENT_PLACEMENT_INVALID' ? '云端还不认识这个组件的位置，需要先部署最新的云函数 shexBeautify' : `没有改成功，请稍后再试（${code}）`, 3200);
        } finally { input.disabled = false; }
      };
      list.appendChild(row);
    });
  }

  async function openStageBeautifyWorkbench(initialDraftOverride = null, mode = '') {
    // X103 根因修复：X世界高级美化编辑的是“当前 X世界”这一 scope，必须与 Stage 确认态 Runtime
    // （ensureStageConfirmedAppearanceRuntime → activeStageBeautifyScope）读取的 scope 完全一致。
    // 旧实现误用了 X传讯当前会话的 activeBeautifyHostScope()：管理员从 X世界主页进入设置时没有打开中的聊天，
    // scope 为 null，工作台在初始化前就返回 STAGE_BEAUTIFY_UNAVAILABLE，只弹“暂时不可用”。
    if(!stageBeautifyModulesReady()){
      const slowToast=window.setTimeout(()=>showChatToast('高级美化正在加载…'),400);
      const ready=await waitStageBeautifyModules();
      window.clearTimeout(slowToast);
      if(!ready){const detail=window.SHEX_BEAUTIFY_MODULES_FAILED?'MODULES_FAILED':'MODULES_LOADING';reportAppUiDiagnostic('stage_beautify_open_unavailable',null,{reason:detail});return{ok:false,reason:'STAGE_BEAUTIFY_UNAVAILABLE',detail};}
    }
    const scope=activeStageBeautifyScope(),ownerId=String(window.SHEXAuth?.current?.()?.userId||'');
    const storage=window.SHEXBeautify?.api?.storage,codec=window.SHEXBeautify?.runtime?.stageAppearanceCodec,workbench=window.SHEXBeautify?.editor?.stageWorkbench;
    const missing=!ownerId?'OWNER_MISSING':!scope?.scopeType||!scope?.scopeId?'STAGE_SCOPE_MISSING':!storage?.getBeautifyRestoreState?'STORAGE_UNAVAILABLE':!codec?.mergeSources?'CODEC_UNAVAILABLE':!workbench?.open?'WORKBENCH_UNAVAILABLE':'';
    if(missing){reportAppUiDiagnostic('stage_beautify_open_unavailable',null,{reason:missing});return{ok:false,reason:'STAGE_BEAUTIFY_UNAVAILABLE',detail:missing};}
    try{
      let state;
      try{state=await storage.getBeautifyRestoreState(scope.scopeType,scope.scopeId,{host:'host_stage',knownBundleHash:''});}
      catch(error){
        const code=String(error?.code||'');
        if(['SESSION_EXPIRED','AUTH_REQUIRED','BEAUTIFY_SCOPE_FORBIDDEN'].includes(code))throw error;
        reportAppUiDiagnostic('stage_beautify_restore_unavailable',error,{scopeType:scope.scopeType});
        const opened=workbench.open({mode,gate:()=>true,currentOwnerId:()=>ownerId,runtimeSession:{ownerId,scopeType:scope.scopeType,scopeId:scope.scopeId,readOnly:false}});
        if(opened?.ok)showChatToast('云端外观暂时无法读取，已打开本机草稿；恢复连接后再保存');
        return opened;
      }
      const decoded=codec.mergeSources(state?.sources||{});
      if(decoded?.ok===false)return decoded;
      const inheritedDraft=codec.mergeSources({authorAppearanceLocked:state?.sources?.authorAppearanceLocked,authorAppearance:state?.sources?.authorAppearance,globalDocument:state?.sources?.globalDocument}).draft;
      const opened=workbench.open({mode,gate:()=>true,currentOwnerId:()=>ownerId,runtimeSession:{ownerId,scopeType:scope.scopeType,scopeId:scope.scopeId,readOnly:false,initialDraft:initialDraftOverride||decoded?.draft||{},inheritedDraft}});
      if(opened?.ok&&state?.publishedHostPolicy?.reason==='AUTHOR_APPEARANCE_UNAVAILABLE')showChatToast('作者预设暂时无法读取；个人美化可继续编辑，稍后请重新确认显示效果');
      return opened;
    }catch(error){return{ok:false,reason:String(error?.code||'STAGE_BEAUTIFY_RESTORE_FAILED'),error};}
  }

