      chatAppearanceKnownRevisionByScope.delete(changedKey);preheatedConfirmedScopeKeys.delete(changedKey);
      if(lastCompleteRuntimeHotContext?.scopeKey===changedKey)lastCompleteRuntimeHotContext=null;
