    const scope=window.SHEXBeautify?.hosts?.hostChat?.scopeContext?.()||{};
    if(String(detail.identity?.scopeType||'')!==String(scope.scopeType||'')||String(detail.identity?.scopeId||'')!==String(scope.scopeId||''))return;
